/* ===== Registro de errores de la app (04-11-2026) =====
   Va primero en la plantilla para escuchar desde el arranque. Cada error de JavaScript (window 'error') y cada promesa
   rechazada sin atender ('unhandledrejection') se anota:
   - en este navegador (localStorage 'hilvanta-errores', los 30 más recientes), para verlo aunque no haya servidor;
   - en la versión conectada, también en la tabla error_app de la base, a nombre de quien usa la app. Solo un
     administrador los lee (Ajustes → «Errores de la app»).
   Para no inundar la base: a lo más 20 envíos por sesión y el mismo mensaje una sola vez. Nunca molesta a quien usa la
   app ni corta lo que estaba haciendo: no muestra nada ni detiene el error (las pruebas lo siguen viendo). */
const ERR_CLAVE='hilvanta-errores',ERR_MAX=30,ERR_ENVIOS=20;
const ERR_VISTOS=new Set();let errEnviados=0,errBase=null;
function erroresLocales(){try{return JSON.parse(localStorage.getItem(ERR_CLAVE)||'[]')}catch(e){return []}}
function anotarError(mensaje,detalle,donde){
  try{
    const m=String(mensaje||'Error sin mensaje').slice(0,500);
    const sec=typeof S!=='undefined'&&S&&S.ui?S.ui.route||'':'';
    const e={en:new Date().toISOString(),mensaje:m,detalle:String(detalle||'').slice(0,2000),donde:[sec,donde].filter(Boolean).join(' · ').slice(0,300),
      version:typeof VERSION!=='undefined'?VERSION:'',navegador:navigator.userAgent.slice(0,300)};
    try{const l=erroresLocales();l.unshift(e);localStorage.setItem(ERR_CLAVE,JSON.stringify(l.slice(0,ERR_MAX)))}catch(x){}
    if(ERR_VISTOS.has(m)||errEnviados>=ERR_ENVIOS)return;ERR_VISTOS.add(m);
    if(typeof conectada!=='function'||!conectada()||typeof SRV==='undefined'||!SRV||SRV.offline||!SRV.E||!S?.me)return;
    errEnviados++;
    SB.from('error_app').insert([{empresa_id:SRV.E,persona_id:S.me,mensaje:e.mensaje,detalle:e.detalle||null,donde:e.donde||null,version:e.version,navegador:e.navegador}]).then(()=>{},()=>{});
  }catch(x){}   // el registro de errores nunca debe causar otro error
}
window.addEventListener('error',ev=>{
  if(!ev.message&&ev.target&&ev.target!==window)return;   // un recurso que no cargó (imagen, script): no es un error de la app
  anotarError(ev.message,ev.error&&ev.error.stack,ev.filename?`${String(ev.filename).split('/').pop()}:${ev.lineno||''}`:'');
});
window.addEventListener('unhandledrejection',ev=>{const r=ev.reason;anotarError(r&&r.message||String(r),r&&r.stack,'promesa')});

// Ajustes → «Errores de la app» (solo administrador): los de este equipo y, en la versión conectada, los de toda la empresa
function erroresSection(){
  const fila=x=>`<li><b>${esc(x.mensaje)}</b><br><span class="hint">${esc(fmtFechaHora(x.en))}${x.persona?` · ${esc(x.persona)}`:''}${x.donde?` · ${esc(x.donde)}`:''}${x.version?` · versión ${esc(x.version)}`:''}</span></li>`;
  const loc=erroresLocales();
  const base=errBase===null?(typeof conectada==='function'&&conectada()?`<div class="bar-actions"><button class="btn ghost sm" data-act="errVerBase">Ver los de toda la empresa</button></div>`:'')
    :errBase.error?`<p class="hint">No se pudieron leer: ${esc(errBase.error)}</p>`
    :`<h3>Toda la empresa (últimos 50)</h3><ul class="act">${errBase.filas.map(fila).join('')||'<li class="empty">Nadie ha tenido errores.</li>'}</ul>`;
  return `<section class="box" id="errsec"><h2>Errores de la app</h2><p class="hint">Los errores que la app tuvo al usarse, para corregirlos sin que nadie tenga que avisar. En la versión conectada se guardan en el servidor; solo los ve un administrador.</p>
    <h3>En este equipo</h3><ul class="act">${loc.slice(0,10).map(fila).join('')||'<li class="empty">No hay errores en este equipo.</li>'}</ul>
    ${loc.length?`<div class="bar-actions"><button class="btn ghost sm" data-act="errLimpiar">Borrar los de este equipo</button></div>`:''}${base}</section>`;
}
function fmtFechaHora(iso){const d=new Date(iso);if(isNaN(d))return '';const p=n=>String(n).padStart(2,'0');return `${p(d.getDate())}-${p(d.getMonth()+1)}-${d.getFullYear()} ${p(d.getHours())}:${p(d.getMinutes())}`}
async function errVerBase(){
  try{const {data,error}=await SB.from('error_app').select('en,mensaje,donde,version,persona_id').order('en',{ascending:false}).limit(50);
    if(error)throw error;errBase={filas:(data||[]).map(r=>({...r,persona:(person(r.persona_id)||{}).name||''}))}}
  catch(e){errBase={error:e.message||String(e)}}
  renderMain();
}

