/* Cálculos que recorren colecciones completas (stock por producto, gastos por informe, fotos de boletas…) se arman una
   vez como índice y se reutilizan (rendimiento, 04-11-2026). Un índice vale mientras su colección sea el mismo arreglo
   con el mismo largo, y se descartan todos en cada guardado y cada vez que se dibuja (memoLimpiar en save y renderMain),
   así un cambio en un registro nunca deja un total viejo en pantalla. */
let MEMO=new Map();
const memoLimpiar=()=>{MEMO=new Map()};
function indice(k,arr,fn){const m=MEMO.get(k);if(m&&m.arr===arr&&m.len===arr.length)return m.v;const v=fn(arr);MEMO.set(k,{arr,len:arr.length,v});return v}
// Agrupa un arreglo por una clave: Map clave → [registros]
const agrupar=(arr,f)=>{const m=new Map();arr.forEach(x=>{const k=f(x);if(k==null||k==='')return;const l=m.get(k);l?l.push(x):m.set(k,[x])});return m};
const isDate=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v);
const monthsBetween=(a,b)=>{const x=P(a),y=P(b);let m=(y.getFullYear()-x.getFullYear())*12+y.getMonth()-x.getMonth();if(y.getDate()<x.getDate())m--;return Math.max(0,m)};
