const fmtAt=a=>fmt(toISO(new Date(a)));
// Negativos al estilo chileno: -$668.500 (Intl en es-CL escribe «$-668.500»); si al redondear queda en cero, sin signo
function fmtMoney(n,cur='CLP'){n=+n||0;if(n<0){const t=fmtMoney(-n,cur);return /[1-9]/.test(t)?'-'+t:t}
  if(cur==='UF')return 'UF '+n.toLocaleString('es-CL',{minimumFractionDigits:2,maximumFractionDigits:2});
  try{return (FMT_MON[cur]||(FMT_MON[cur]=new Intl.NumberFormat('es-CL',{style:'currency',currency:cur,maximumFractionDigits:cur==='CLP'?0:2}))).format(n)}catch(e){return cur+' '+n.toLocaleString('es-CL')}}
