function ago(at){const m=(Date.now()-new Date(at))/6e4;if(m<1)return 'recién';if(m<60)return `hace ${Math.round(m)} min`;if(m<1440)return `hace ${Math.round(m/60)} h`;if(m<2880)return 'ayer';return fmtAt(at)}
// Días hábiles: lunes a viernes sin feriados (FERIADOS_CL más los agregados y menos los quitados en Ajustes, función 31)
function feriadoDe(d){let x={};try{x=S&&S.feriados||{}}catch(e){}if((x.quitar||[]).includes(d))return '';const e=(x.extra||[]).find(f=>f.fecha===d);return e?e.nombre||'Feriado':FERIADOS_CL[d]||''}
const esHabil=d=>{const w=P(d).getDay();return w!==0&&w!==6&&!feriadoDe(d)};
function workdays(a,b){if(!a||!b||b<a)return 0;let n=0;for(let d=a;d<=b;d=addD(d,1))if(esHabil(d))n++;return n}
