function migrate(s,old){
  const p=s.projects.find(x=>x.id==='pr3');p.name=old.project||'Mi app de gestión';
  s.tasks=s.tasks.filter(t=>t.projectId!=='pr3');
  old.tasks.forEach(t=>{let o=s.people.find(x=>x.name.toLowerCase()===(t.owner||'').toLowerCase());
    if(!o&&t.owner){o={id:uid(),name:t.owner,role:''};s.people.push(o)}
    s.tasks.push({id:uid(),projectId:'pr3',name:t.name||'',ownerId:o?o.id:'',status:t.status||'todo',priority:'media',start:'',due:t.date||'',tags:[],desc:'',subtasks:[],comments:[],createdAt:TODAY,doneAt:t.status==='done'?TODAY:''})});
  s.log.unshift({at:new Date().toISOString(),text:'Se trajeron tus tareas del tablero anterior'});
}
