/* ===== Almacén: dónde se guardan los datos ===== */
/* La app lee y guarda solo a través de ALMACEN. Hoy es el navegador (localStorage).
   Para conectar un servidor basta con otro objeto con los mismos métodos:
     leer()               estado guardado, o null
     leerAnterior()       datos del tablero antiguo (migración), o null
     guardar(s, cambios)  s = estado completo; cambios = lo que cambió desde el guardado anterior
     leerPrefs() / guardarPrefs(p)   preferencias de este equipo (tema)
   Cada cambio es uno de:
     {col, op:'crear'|'cambiar', id, reg}   registro nuevo o modificado (reg es una copia)
     {col, op:'borrar', id}
     {col:'log', op:'anotar', reg}          línea nueva del registro de actividad
     {col:'auditoria', op:'anotar', reg}    entrada nueva del registro de auditoría (auditoria.js)
     {col:'ajustes', op:'ajustar', clave, valor}   empresa, áreas activas o campos personalizados
   Lo que es solo de esta pantalla (S.ui, S.me) no genera cambios. */
/* Datos grandes (rendimiento, 04-11-2026). localStorage admite unos 5 MB por sitio y una empresa con un año de datos
   pesa bastante más: antes, al pasarse, el guardado fallaba en silencio. Ahora lo que no cabe va a IndexedDB (del orden
   de cientos de MB) con la misma clave, y se quita de localStorage para que nunca quede una copia vieja ahí:
   - guardarLocal(k, texto): localStorage si cabe; si no, IndexedDB. Las escrituras en IndexedDB van en fila, en orden.
   - leerLocal(k): primero localStorage; si no está, IndexedDB (asíncrono).
   - borrarLocal(k): de los dos lados.
   Con los datos de ejemplo todo cabe en localStorage y nada cambia. */
const IDB_LOCAL=(()=>{let db=null,fila=Promise.resolve();const enIDB=new Set();
  const abrir=()=>db||(db=new Promise((ok,mal)=>{try{const r=indexedDB.open('hilvanta',1);r.onupgradeneeded=()=>r.result.createObjectStore('datos');r.onsuccess=()=>ok(r.result);r.onerror=()=>mal(r.error)}catch(e){mal(e)}}));
  const op=(modo,f)=>abrir().then(d=>new Promise((ok,mal)=>{const t=d.transaction('datos',modo),q=f(t.objectStore('datos'));t.oncomplete=()=>ok(q&&q.result);t.onerror=()=>mal(t.error)}));
  const enFila=f=>(fila=fila.then(f,f).catch(()=>{}));
  return {enIDB,
    guardar:(k,v)=>{enIDB.add(k);return enFila(()=>op('readwrite',s=>s.put(v,k)))},
    borrar:k=>{if(!enIDB.has(k))return Promise.resolve();enIDB.delete(k);return enFila(()=>op('readwrite',s=>s.delete(k)))},
    leer:k=>fila.then(()=>op('readonly',s=>s.get(k))).then(v=>{if(v!=null)enIDB.add(k);return v??null}).catch(()=>null)};
})();
// «<clave>|idb» en localStorage marca que esa clave está en IndexedDB (así al abrir solo se espera a IndexedDB si hace falta)
const marcaIDB=k=>k+'|idb',estaEnIDB=k=>{try{return localStorage.getItem(marcaIDB(k))==='1'}catch(e){return false}};
function guardarLocal(k,txt){
  try{localStorage.setItem(k,txt);if(estaEnIDB(k)){localStorage.removeItem(marcaIDB(k));IDB_LOCAL.enIDB.add(k);IDB_LOCAL.borrar(k)}return true}
  catch(e){try{localStorage.removeItem(k);localStorage.setItem(marcaIDB(k),'1')}catch(x){}IDB_LOCAL.guardar(k,txt);return false}}
async function leerLocal(k){let t=null;try{t=localStorage.getItem(k)}catch(e){}return t!=null?t:estaEnIDB(k)?await IDB_LOCAL.leer(k):null}
const leerLocalJSON=async k=>{try{return JSON.parse(await leerLocal(k)||'null')}catch(e){return null}};
function borrarLocal(k){const idb=estaEnIDB(k);try{localStorage.removeItem(k);localStorage.removeItem(marcaIDB(k))}catch(e){}if(!idb)return Promise.resolve();IDB_LOCAL.enIDB.add(k);return IDB_LOCAL.borrar(k)}
const ALMACEN_NAVEGADOR={
  leer(){try{return JSON.parse(localStorage.getItem(KEY))}catch(e){return null}},
  leerAnterior(){try{return JSON.parse(localStorage.getItem(OLD))}catch(e){return null}},
  guardar(s,cambios,txt){guardarLocal(KEY,txt||JSON.stringify(s))},
  leerPrefs(){try{return JSON.parse(localStorage.getItem(PREF))||{}}catch(e){return {}}},
  guardarPrefs(p){try{localStorage.setItem(PREF,JSON.stringify(p))}catch(e){}}
};
