/* Registros con id, uno por fila en el servidor; y ajustes que se guardan enteros */
const colecciones=s=>Object.assign({projects:s.projects||[],tasks:s.tasks||[],people:s.people||[],roles:s.roles||[]},s.d||{});
const AJUSTES=['company','mods','custom','auto','aprob','caja','checklists','integ','feriados','flujos','gastoCats','funciones','jornada','marca','correlativos','textosDoc','estados','karin','vistasEmpresa','inicioEmpresa','funcApagadas','jefaturas','prevencion'];
const lineaLog=a=>a.at+'|'+a.text;

/* Foto de lo guardado: texto de cada registro, para comparar en el siguiente guardado */
let FOTO=null;
function fotoDe(s){
  const f={col:{},ajustes:{},log:new Set((s.log||[]).map(lineaLog)),audit:new Set((s.audit||[]).map(x=>x.id))};
  Object.entries(colecciones(s)).forEach(([c,l])=>{const m=f.col[c]={};l.forEach(r=>{m[r.id]=JSON.stringify(r)})});
  AJUSTES.forEach(k=>f.ajustes[k]=JSON.stringify(s[k]??null));
  return f;
}
function cambiosEntre(a,b,s){
  const out=[];
  Object.entries(b.col).forEach(([c,m])=>{const ant=a.col[c]||{};
    Object.entries(m).forEach(([id,txt])=>{if(ant[id]!==txt)out.push({col:c,op:id in ant?'cambiar':'crear',id,reg:JSON.parse(txt)})});
    Object.keys(ant).forEach(id=>{if(!(id in m))out.push({col:c,op:'borrar',id})})});
  Object.keys(a.col).forEach(c=>{if(!(c in b.col))Object.keys(a.col[c]).forEach(id=>out.push({col:c,op:'borrar',id}))});
  AJUSTES.forEach(k=>{if(a.ajustes[k]!==b.ajustes[k])out.push({col:'ajustes',op:'ajustar',clave:k,valor:JSON.parse(b.ajustes[k])})});
  (s.log||[]).filter(x=>!a.log.has(lineaLog(x))).reverse().forEach(x=>out.push({col:'log',op:'anotar',reg:Object.assign({},x)}));
  (s.audit||[]).filter(x=>!a.audit.has(x.id)).reverse().forEach(x=>out.push({col:'auditoria',op:'anotar',reg:JSON.parse(JSON.stringify(x))}));
  return out;
}
