  if(cambios.some(c=>['crear','cambiar','borrar'].includes(c.op))){if(!modo&&ULTIMO){DESHACER={s:ULTIMO,at:Date.now()};if(typeof mostrarDeshacer==='function')mostrarDeshacer()}ULTIMO=texto()}
