const pcol=p=>PCOLORS[(+(p?.color)||0)%PCOLORS.length];
const ini=n=>(n||'?').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();   // sin tilde: «MA», no «MÁ»
