const canSee=(ent,r,mod)=>{if(ENT[ent].verRegistro)return ENT[ent].verRegistro(r);if(ENT[ent].jefatura&&r&&jefaturaDe(r[ENT[ent].owner])===S.me)return true;   // la jefatura ve lo de su gente (permisos y vacaciones)
  if(ENT[ent].ver&&!ENT[ent].ver())return false;const l=lvl(mod||ENT[ent].mod);if(ENT[ent].publico&&l>=1)return true;
  if(ENT[ent].gasto)return l>=2||(isOwn(ent,r)&&esRendidor())||apruebaA(r.persona);   // gastos: rol en gastos y flujo de aprobación (fondos.js)
  return l>=2||(l===1&&(isOwn(ent,r)||!!ENT[ent].veTambien&&r[ENT[ent].veTambien]===S.me))};   // veTambien: otro campo de persona que también lo ve (no lo edita)
const canEditRec=(ent,r,mod)=>{const E=ENT[ent],l=lvl(mod||E.mod);if(E.editaRegistro)return E.editaRegistro(r);if(l>=3)return true;
  if(E.gasto)return isOwn(ent,r)&&esRendidor()&&E.ownEdit(r);
  return l===1&&!!E.ownEdit&&isOwn(ent,r)&&E.ownEdit(r)};
const canCreate=(ent,mod)=>{const E=ENT[ent],l=lvl(mod||E.mod);if(E.crearTodos)return !!person(S.me);if(E.gasto)return l>=3||esRendidor();return l>=3||(l===1&&!!E.ownEdit)};
// Acciones: las de aprobar, según quién aprueba el nivel pendiente; las "propias" (enviar mi informe), el dueño que rinde; el resto, quien edita el área
const actionsFor=(ent,r,mod)=>{const l=lvl(mod||ENT[ent].mod);return(ENT[ent].actions?ENT[ent].actions(r):[]).filter(a=>a.approve?puedeAprobar(ent,r,mod):a.propio?l>=3||(isOwn(ent,r)&&esRendidor()):l>=3)};

/* ===== Aprobaciones por monto y en varios niveles ===== */
/* Reglas en S.aprob (las configura un administrador en Ajustes):
     {id, ent:'ocs'|'rends', moneda, desde, hasta, niveles:['r:<rol>'|'p:<persona>', ...]}
   La regla aplica si el monto es mayor que "desde" (o desde es 0) y hasta "hasta" (vacío = sin tope);
   si hay varias, manda la primera de la lista. Sin regla, aprueba quien tiene "Editar y aprobar" en el área, como antes.
   Con regla, cada nivel lo aprueba una persona de ese rol (o esa persona) que tenga al menos "Editar" en el área,
   y nadie aprueba lo que él mismo pidió (salvo un administrador, que puede aprobar cualquier nivel).
   Historial en el registro, r.aprobaciones: [{nivel, por, at, accion:'aprobó'|'rechazó'|'devolvió'}].
   Solo se agregan entradas. Una ronda termina con un rechazo o una devolución; las aprobaciones cuentan desde ahí.
   Las mismas reglas las aplica la base (modelo/permisos.sql: hilvanta.revisar_aprobaciones). */
const APROB_ENTS={
  ocs:{monto:r=>+r.neto||0,moneda:r=>r.moneda||'CLP',ok:'Aprobada',no:'Borrador',inicio:['Borrador','Por aprobar'],area:'compras'},
  rends:{monto:r=>+r.monto||0,moneda:r=>r.moneda||'CLP',ok:'Aprobada',no:'Rechazada',inicio:['Pendiente'],area:'contabilidad',flujo:1},
  leaves:{ok:'Aprobada',no:'Rechazada',inicio:['Pendiente'],area:'rrhh'},
  // Solicitud de fondos e informe de gastos (fondos.js): sin reglas por monto; con flujo, lo aprueban las personas del flujo
  fondos:{ok:'Aprobada',no:'Rechazada',inicio:['Pendiente'],area:'contabilidad',flujo:1},
  informes:{ok:'Aprobado',no:'Rechazado',inicio:['Borrador','Enviado'],area:'contabilidad',flujo:1}};
let SIMULA=false;   // las automatizaciones prueban un botón sobre una copia: sin avisos
const APROB_REG={ocs:'Orden de compra',rends:'Rendición'};
const nivelOC=r=>Math.max(lvl('compras'),r.tipo==='Importación'?lvl('comex'):0);
const nivelAprob=(ent,r)=>ent==='ocs'?nivelOC(r):lvl(APROB_ENTS[ent].area);
function reglaAprob(ent,r){
  const A=APROB_ENTS[ent];if(!A||!A.monto)return null;const m=A.monto(r),mon=A.moneda(r);
  return (S.aprob||[]).find(x=>x.ent===ent&&(x.moneda||'CLP')===mon&&(+x.desde<=0||m>+x.desde)&&(x.hasta===''||x.hasta==null||m<=+x.hasta))||null;
}
/* Niveles: si la persona que pide tiene un flujo de aprobación de gastos (Ajustes → Gastos), sus pasos ('f:<persona>');
   si no, la regla por monto (OC y rendiciones); null = sin regla (aprueba quien tiene "Editar y aprobar") */
function nivelesDe(ent,r){
  if(ent==='leaves'){const j=jefaturaDe(r.persona);return j?['f:'+j]:null}   // jefatura del área (funcopc.js)
  if(APROB_ENTS[ent]?.flujo){const f=flujoDe(r.persona,r.flujo);if(f)return f.pasos.map(p=>'f:'+p)}
  return reglaAprob(ent,r)?.niveles||null;
}
const totalNiveles=(ent,r)=>(nivelesDe(ent,r)||[null]).length;
/* Aprobaciones de la ronda actual */
function ronda(r){let k=0;(r.aprobaciones||[]).forEach(x=>{if(x.accion==='aprobó')k++;else k=0});return k}
// Un gasto dentro de un informe se aprueba con el informe
const aprobCompleta=(ent,r)=>ent==='rends'&&r.informe?['Aprobado','Cerrado'].includes(informeDe(r)?.estado):ronda(r)>=totalNiveles(ent,r);
const nomNivel=s=>!s?'':s.startsWith('r:')?(S.roles.find(x=>x.id===s.slice(2))?.name||'Rol eliminado'):(person(s.slice(2))?.name||'Persona eliminada');
const esDelNivel=(s,pid)=>{const p=person(pid);return !!p&&(s==='p:'+pid||s==='f:'+pid||s==='r:'+p.roleId)};
/* ¿Quien tiene la sesión puede aprobar (o rechazar) el nivel que sigue? mod = área desde donde mira (sin regla).
   Un paso de flujo ('f:') lo aprueba esa persona aunque no tenga nivel en el área (la asignó el administrador). */
function puedeAprobar(ent,r,mod){
  if(ent==='rends'&&r.informe){const inf=informeDe(r);return !!inf&&inf.estado==='Enviado'&&puedeAprobar('informes',inf,mod)}
  const ns=nivelesDe(ent,r);
  if(!ns)return lvl(mod||ENT[ent].mod)>=4;
  const s=ns[ronda(r)];
  if(s&&s.startsWith('f:'))return isAdmin()||(s==='f:'+S.me&&r[ENT[ent].owner]!==S.me);
  if(nivelAprob(ent,r)<3)return false;if(isAdmin())return true;
  if(!s||r[ENT[ent].owner]===S.me)return false;
  return esDelNivel(s,S.me);
}
/* Personas que pueden aprobar el nivel pendiente (para avisarles); null si no hay regla */
function aprobadoresDe(ent,r){
  const ns=nivelesDe(ent,r);if(!ns)return null;const s=ns[ronda(r)];if(!s)return [];
  return S.people.filter(p=>p.estado!=='Inactivo'&&(p.id!==r[ENT[ent].owner]||roleOf(p).admin)&&esDelNivel(s,p.id)).map(p=>p.id);
}
const anotar=(r,x)=>(r.aprobaciones=r.aprobaciones||[]).push(Object.assign({por:S.me,at:new Date().toISOString()},x));
function aprobar(ent,r,extra){
  const A=APROB_ENTS[ent],L=totalNiveles(ent,r);anotar(r,Object.assign({nivel:ronda(r)+1,accion:'aprobó'},extra));
  if(ronda(r)>=L){r.estado=A.ok;if(ent==='ocs'){r.aprobador=S.me;stampOC(r)}if(ent==='leaves'&&!SIMULA)avisarRRHHPermiso(r,'Pendiente');return}
  if(SIMULA)return;
  const nota=extra&&extra.nota?` · ${refName('people',S.me)} te dejó un comentario: «${extra.nota.length>80?extra.nota.slice(0,80)+'…':extra.nota}»`:'';
  const sig=aprobadoresDe(ent,r)||[],txt=`${ENT[ent].title(r)} espera tu aprobación (nivel ${ronda(r)+1} de ${L})${nota}`,at=new Date().toISOString();
  sig.forEach(p=>S.d.avisos.unshift({id:uid(),para:p,texto:txt,ent,reg:r.id,regla:'',at,leido:false}));
}
function rechazar(ent,r){const niv=ent==='rends'&&r.informe?ronda(informeDe(r)||{})+1:ronda(r)+1;anotar(r,{nivel:niv,accion:'rechazó'});r.estado=APROB_ENTS[ent].no}
/* Al volver a un estado previo a la aprobación desde el formulario, la ronda se cierra (la base hace lo mismo) */
function cerrarRonda(ent,r){
  const A=APROB_ENTS[ent],k=ronda(r);
  if(k>0&&A.inicio.includes(r.estado)&&(k>=totalNiveles(ent,r)||(ent==='ocs'&&r.estado==='Borrador')||(ent==='informes'&&r.estado==='Borrador')))anotar(r,{accion:'devolvió'});
}
const aprobLabel=(ent,r)=>{const L=totalNiveles(ent,r);return L>1?`Aprobar (nivel ${ronda(r)+1} de ${L})`:'Aprobar'};
/* Bloque de la ficha: niveles que exige la regla y el historial */
function aprobResumen(ent,r){
  const ns=nivelesDe(ent,r),h=r.aprobaciones||[];if(!r.id||(!ns&&!h.length))return '';
  const k=ronda(r),pend=['Por aprobar','Pendiente','Enviado'].includes(r.estado);if(!h.length&&!pend)return '';   // ya resuelto antes de la regla
  const nv=!ns?'':`<p class="hint">${ns.length>1?`Requiere ${ns.length} niveles`:'Aprueba'}: ${ns.map((s,i)=>`${ns.length>1?(i+1)+'. ':''}${esc(nomNivel(s))}${i<k?' ✓':pend&&i===k?' (pendiente)':''}`).join(' · ')}</p>`;
  // El hilo de la aprobación (diseño W3): lo que ya pasó y, si sigue pendiente, el nivel que falta
  const nodo=(tipo,txt,cuando)=>`<li class="h-${tipo}"><span class="hnodo" aria-hidden="true">${hiloNodo(tipo)}</span><span class="htx"><b>${txt}</b>${cuando?`<span>${cuando}</span>`:''}</span></li>`;
  const hist=h.map(x=>nodo(x.accion==='aprobó'?'ok':'late',`${esc(refName('people',x.por)||'Alguien')} ${x.accion}${x.nivel&&ns&&ns.length>1?` (nivel ${x.nivel})`:''}`,fmtAt(x.at)+(x.nota?` · «${esc(x.nota)}»`:''))).join('')
    +(pend&&ns&&k<ns.length?ns.slice(k).map((s,i)=>nodo(i?'fut':'now',`${ns.length>1?`Nivel ${k+i+1} · `:''}${esc(nomNivel(s))}`,i?'después':'pendiente')).join(''):'');
  return `<div class="wide aprobs"><b>Aprobaciones</b>${nv}${hist?`<ol class="hilo compacto">${hist}</ol>`:''}</div>`;
}

/* ===== Configuración (Ajustes, solo administrador) ===== */
const montoTxt=(v,cur)=>v===''||v==null?'':fmtMoney(v,cur);
function aprobRango(a){
  const d=+a.desde>0?`más de ${montoTxt(a.desde,a.moneda)}`:'',h=a.hasta!==''&&a.hasta!=null?`hasta ${montoTxt(a.hasta,a.moneda)}`:'';
  return [d,h].filter(Boolean).join(' y ')||'cualquier monto';
}
function aprobSection(){
  const rows=S.aprob.map(a=>`<tr data-aprobedit="${a.id}" tabindex="0"><td class="nm">${APROB_REG[a.ent]}</td><td>${esc(a.moneda||'CLP')}</td><td>${esc(aprobRango(a))}</td><td>${a.niveles.map(s=>esc(nomNivel(s))).join(' → ')}</td></tr>`).join('');
  return `<section class="box" id="apsec"><h2>Aprobaciones por monto</h2><p class="hint">Quién aprueba cada orden de compra o rendición según su monto, en uno o más niveles. Manda la primera regla de la lista que calce. Quien aprueba un nivel necesita al menos “Editar” en el área, y nadie aprueba lo que él mismo pidió. Sin regla, aprueba quien tiene “Editar y aprobar”.</p>
    <div class="tablewrap"><table class="rt"><thead><tr><th>Registro</th><th>Moneda</th><th>Monto</th><th>Niveles</th></tr></thead><tbody>
    ${rows||`<tr><td colspan="4">${empty('Aún no hay reglas: aprueba quien tiene “Editar y aprobar”.')}</td></tr>`}</tbody></table></div>
    <div class="bar-actions"><button class="btn" data-aprobnew>+ Nueva regla de aprobación</button></div></section>`;
}
function editAprob(id){
  if(!isAdmin())return;
  const a=id?S.aprob.find(x=>x.id===id):{ent:'ocs',moneda:'CLP',desde:0,hasta:'',niveles:[]};if(!a)return;
  const quien=[['','—'],...S.roles.map(r=>['r:'+r.id,'Rol: '+r.name]),...S.people.filter(p=>p.estado!=='Inactivo').map(p=>['p:'+p.id,p.name])];
  const sel=(n,arr,v,lab)=>`<label>${lab}<select name="${n}" id="ap_${n}">${arr.map(([k,t])=>`<option value="${esc(k)}" ${String(v??'')===String(k)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
  const body=sel('ent',Object.entries(APROB_REG),a.ent,'Registro')+sel('moneda',['CLP','USD','EUR','UF'].map(x=>[x,x]),a.moneda||'CLP','Moneda del registro')
    +`<label>Más de<input name="desde" id="ap_desde" type="number" step="any" inputmode="decimal" value="${esc(a.desde??0)}"></label>`
    +`<label>Hasta (vacío = sin tope)<input name="hasta" id="ap_hasta" type="number" step="any" inputmode="decimal" value="${esc(a.hasta??'')}"></label>`
    +[0,1,2].map(i=>sel('n'+i,quien,a.niveles[i]||'',`Nivel ${i+1}${i?' (opcional)':' *'}`)).join('');
  openModal(id?'Editar regla de aprobación':'Nueva regla de aprobación',null,{},o=>{
    Object.assign(a,{ent:o.ent,moneda:o.ent==='rends'&&o.moneda==='UF'?'CLP':o.moneda,desde:+String(o.desde||0).replace(',','.')||0,hasta:o.hasta===''?'':+String(o.hasta).replace(',','.'),niveles:[o.n0,o.n1,o.n2].filter(Boolean)});
    if(!id){a.id='ap_'+uid();S.aprob.push(a)}addLog(`${meName()} ${id?'editó':'creó'} la regla de aprobación: ${APROB_REG[a.ent]} ${aprobRango(a)}`);
  },id?()=>{S.aprob=S.aprob.filter(x=>x!==a);addLog(`${meName()} eliminó la regla de aprobación: ${APROB_REG[a.ent]} ${aprobRango(a)}`)}:null,'¿Eliminar esta regla de aprobación?',null,body);
  modalValidate=o=>{const ns=[o.n0,o.n1,o.n2];
    if(!o.n0)return 'Elige quién aprueba el nivel 1.';if(!o.n1&&o.n2)return 'Completa el nivel 2 antes del 3.';
    if(new Set(ns.filter(Boolean)).size<ns.filter(Boolean).length)return 'Un mismo rol o persona no puede aprobar dos niveles.';
    if(o.hasta!==''&&+o.hasta<=+(o.desde||0))return '“Hasta” debe ser mayor que “Más de”.';return ''};
}

