function accMissing(){let n=0;const ppl=accPeople();const cls=[...new Set(S.d.reqs.map(q=>q.cliente))];
  cls.forEach(c=>{const reqs=S.d.reqs.filter(q=>q.cliente===c);ppl.forEach(p=>{if(S.d.accdocs.some(x=>x.persona===p.id&&reqs.some(q=>q.id===x.req)))reqs.forEach(q=>{if(!S.d.accdocs.find(x=>x.persona===p.id&&x.req===q.id))n++})})});return n}

/* ===== Automatizaciones: "cuando pase X, haz Y" ===== */
/* Las reglas están en S.auto y las configura un administrador en Ajustes. Cada regla:
     {id, nombre, activa, ent, disparador:{tipo, ...}, accion:{tipo, ...}}
   Disparadores: crear (se crea un registro) · estado (pasa de un estado a otro) ·
     monto (un monto o número pasa a ser mayor que un valor) · fecha (vence en N días o menos).
   Acciones: notificar (aviso en S.d.avisos) · estado · tarea (crea una tarea) · asignar (persona en un campo).
   Corren dentro de save() con los cambios de ese guardado y la versión anterior de cada registro,
   así las dispara cualquier vía: formulario, botones de acción, desplegable de estado o arrastre.
   Una sola pasada: lo que cambia una automatización no dispara otras (no hay bucles).
   Actúan con los permisos de quien provoca el cambio: si su rol no alcanza, la acción se omite y
   queda anotada, igual que la rechazaría la base (modelo/permisos.sql).
   Cada ejecución queda en S.d.autoruns; las de fecha usan su clave para no repetirse.
   Desde el 24-10-2026: disparador «programada» (cada día, cada semana en un día o cada mes en un día o el último
   hábil), que se revisa al abrir la app junto con las de fecha y actúa una vez por período sobre cada registro en el
   estado elegido; acción «campo» (pone un valor fijo o la fecha de hoy en un campo), y plantillas listas para usar. */
const autoEnts=()=>['tasks',...CFENTS];
const TASKF=[{k:'name',label:'Nombre'},{k:'status',label:'Estado',type:'select',options:STATES.map(s=>s.id)},
  {k:'ownerId',label:'Responsable',type:'ref',ref:'people'},{k:'start',label:'Inicio',type:'date'},{k:'due',label:'Plazo',type:'date',late:t=>t.status!=='done'}];
function autoInfo(ent){
  if(ent==='tasks')return {name:'Tarea',mod:'proyectos',owner:'ownerId',fields:TASKF,title:t=>t.name||'Sin nombre',proyecto:t=>t.projectId};
  const E=ENT[ent];return {name:E.name,mod:E.mod,owner:E.owner,fields:fieldsOf(ent),title:E.title,proyecto:r=>r.proyecto};
}
const autoLabel=f=>f.label.replace(/ \(.*\)$/,'');
const autoCampo=(ent,k)=>autoInfo(ent).fields.find(f=>f.k===k);
const autoTieneEstado=ent=>ent==='tasks'||ENT[ent].fields.some(f=>f.k==='estado'&&f.type==='select');
const autoEstadosDe=ent=>ent==='tasks'?STATES.map(s=>[s.id,s.name]):autoTieneEstado(ent)?ENT[ent].fields.find(f=>f.k==='estado').options.map(o=>[o,o]):[];
const autoNomEstado=(ent,v)=>ent==='tasks'?stOf(v).name:v;
const autoMontos=ent=>autoInfo(ent).fields.filter(f=>isNum(f));
const autoFechas=ent=>autoInfo(ent).fields.filter(f=>f.type==='date'&&!f.calc);
const autoPersonas=ent=>autoInfo(ent).fields.filter(f=>f.type==='ref'&&f.ref==='people'&&!f.calc&&!f.ro);
const autoTieneProyecto=ent=>ent==='tasks'||ENT[ent].fields.some(f=>f.k==='proyecto'&&f.ref==='projects');
const autoDueno=(ent,r)=>{const k=autoInfo(ent).owner;return !k?'':k==='id'?r.id:r[k]||''};
function autoValor(f,r){let v;try{v=f.raw?f.raw(r):f.calc?f.calc(r):r[f.k]}catch(e){return null}return v===''||v==null||isNaN(+v)?null:+v}

/* ¿La regla se dispara con este registro? antes = versión del guardado anterior (null si es nuevo).
   Devuelve true, false o, en las de fecha, la clave que evita repetirla. */
function autoDispara(a,ent,r,antes){
  const d=a.disparador;
  if(ent==='tasks'){if(!r.name)return false;if(antes&&!antes.name)antes=null}   // una tarea "nace" cuando recibe nombre
  if(d.tipo==='crear')return !antes;
  if(d.tipo==='estado'){const k=ent==='tasks'?'status':'estado',prev=antes?antes[k]:undefined;
    return r[k]===d.hasta&&prev!==d.hasta&&(!d.desde||prev===d.desde)}
  if(d.tipo==='monto'){const f=autoCampo(ent,d.campo);if(!f)return false;const v=autoValor(f,r),p=antes?autoValor(f,antes):null;
    return v!=null&&v>+d.valor&&!(p!=null&&p>+d.valor)}
  if(d.tipo==='fecha')return autoFecha(a,ent,r);
  return false;
}
function autoFecha(a,ent,r){
  const d=a.disparador,f=autoCampo(ent,d.campo),v=f&&r[f.k];
  if(!isDate(v)||(f.late&&!f.late(r)))return '';
  const n=diff(TODAY,v);if(n<0||n>(+d.dias||0))return '';
  const clave=`${a.id}|${r.id}|${v}`;return S.d.autoruns.some(x=>x.clave===clave)?'':clave;
}
function autoDestinos(a,ent,r){
  const p=a.accion.para||'',mod=autoInfo(ent).mod;let ids=[];
  if(p==='dueno')ids=[autoDueno(ent,r)];
  else if(p==='aprob'&&aprobadoresDe(ent,r)?.length)ids=aprobadoresDe(ent,r);
  else if(p==='aprob')ids=S.people.filter(x=>nivelDe(x,mod)>=4).map(x=>x.id);
  else if(p.startsWith('r:'))ids=S.people.filter(x=>x.roleId===p.slice(2)).map(x=>x.id);
  else if(p.startsWith('p:'))ids=[p.slice(2)];
  return [...new Set(ids)].filter(id=>{const x=person(id);return x&&x.estado!=='Inactivo'});
}
/* Estados a los que quien provoca el cambio puede llevar el registro (las mismas reglas que el formulario) */
function autoEstadosPermitidos(ent,r){
  const E=ENT[ent];if(!canEditRec(ent,r))return [];
  if(lvl(E.mod)<3&&(E.lock||[]).includes('estado'))return [r.estado];
  return E.estados?E.estados(r):E.fields.find(f=>f.k==='estado').options;
}
let AUTO_MSG=[];
/* Aplica la acción de la regla. clave: solo en las de fecha. Devuelve true si cambió algo. */
function autoEjecutar(a,ent,r,clave){
  const I=autoInfo(ent),x=a.accion,tit=I.title(r),rol=`el rol de ${meName()}`;let no='',hecho='';
  if(x.tipo==='notificar'){const ds=autoDestinos(a,ent,r);
    if(!ds.length)no='no hay a quién avisar';
    else{const txt=`${x.mensaje||a.nombre} · ${tit}`,at=new Date().toISOString();
      ds.forEach(p=>S.d.avisos.unshift({id:uid(),para:p,texto:txt,ent,reg:r.id,regla:a.id,at,leido:false}));
      hecho=`avisó a ${ds.map(id=>person(id).name).join(', ')}`}}
  else if(x.tipo==='estado'){const k=ent==='tasks'?'status':'estado',nom=autoNomEstado(ent,x.estado);
    if(r[k]===x.estado)no=`ya estaba en «${nom}»`;
    else if(ent==='tasks'){if(canEditTask(r)){setStatus(r,x.estado);hecho=`pasó a «${nom}»`}else no=`${rol} no permite cambiar esta tarea`}
    else{const E=ENT[ent];
      // Si hay un botón de acción que lleva a ese estado (Aprobar, Marcar recibida...), se usa: anota aprobador y fechas
      SIMULA=true;let ac;try{ac=actionsFor(ent,r).find(y=>{const c=JSON.parse(JSON.stringify(r));y.run(c);return c.estado===x.estado})}finally{SIMULA=false}
      if(ac)ac.run(r);else if(autoEstadosPermitidos(ent,r).includes(x.estado)){r.estado=x.estado;E.onSave&&E.onSave(r,false)}
      else no=`${rol} no permite pasar a «${nom}»`;
      if(!no)hecho=`pasó a «${nom}»`}}
  else if(x.tipo==='tarea'){const pid=x.proyecto||I.proyecto(r),pr=proj(pid);
    if(!pr)no='no hay proyecto donde crear la tarea';else if(!canEditProj())no=`${rol} no permite crear tareas`;
    else{const own=x.responsable==='dueno'?autoDueno(ent,r):person(x.responsable)?x.responsable:'',nm=`${x.nombre} · ${tit}`;
      S.tasks.push({id:uid(),projectId:pid,name:nm,ownerId:own,status:'todo',priority:'media',start:TODAY,due:x.plazo===''||x.plazo==null?'':addD(TODAY,+x.plazo),
        tags:[],desc:`Creada por la automatización «${a.nombre}» a partir de: ${tit}.`,subtasks:[],comments:[],createdAt:TODAY,doneAt:''});
      hecho=`creó la tarea «${x.nombre}» en ${pr.name}`}}
  else if(x.tipo==='campo'){const f=autoCampo(ent,x.campo),v=x.valor==='hoy'&&f?.type==='date'?TODAY:x.valor;
    if(!f)no='el campo ya no existe';
    else if(ent==='tasks'?!canEditTask(r):!(canEditRec(ent,r)&&(lvl(I.mod)>=3||!(ENT[ent].lock||[]).includes(f.k))))no=`${rol} no permite cambiar «${autoLabel(f)}»`;
    else if(String(r[f.k]??'')===String(v))no=`«${autoLabel(f)}» ya tenía ese valor`;
    else{r[f.k]=isNum(f)&&v!==''?+v:v;if(ent!=='tasks')ENT[ent].onSave&&ENT[ent].onSave(r,false);hecho=`puso «${v===TODAY&&x.valor==='hoy'?fmt(v):v}» en «${autoLabel(f)}»`}}
  else if(x.tipo==='asignar'){const f=autoCampo(ent,x.campo),p=person(x.persona);
    if(!f||!p)no='el campo o la persona ya no existen';
    else if(ent==='tasks'?!canEditProj():!(canEditRec(ent,r)&&(lvl(I.mod)>=3||!(ENT[ent].lock||[]).includes(f.k))))no=`${rol} no permite cambiar «${autoLabel(f)}»`;
    else if(r[f.k]===p.id)no=`${p.name} ya estaba en «${autoLabel(f)}»`;
    else{r[f.k]=p.id;hecho=`asignó a ${p.name} en «${autoLabel(f)}»`}}
  if(no&&clave)return false;   // las de fecha se reintentan cuando abra la app alguien a quien sí le alcance
  const res=no?`no se aplicó: ${no}`:hecho;
  S.d.autoruns.unshift({id:uid(),regla:a.id,ent,reg:r.id,clave:clave||'',at:new Date().toISOString(),por:S.me,res:`${res} · ${tit}`});
  addLog(`Automatización «${a.nombre}»: ${res} · ${tit}`);AUTO_MSG.push(`«${a.nombre}»: ${res}`);
  return true;
}
/* Lo llama save() con los cambios del guardado y la foto anterior */
function correrAuto(cambios,foto){
  const reglas=(S.auto||[]).filter(a=>a.activa);if(!reglas.length)return false;
  const cols=colecciones(S);let hizo=false;
  cambios.forEach(c=>{
    if(c.op!=='crear'&&c.op!=='cambiar')return;
    const rs=reglas.filter(a=>a.ent===c.col);if(!rs.length)return;
    const r=cols[c.col].find(x=>x.id===c.id);if(!r)return;
    const antes=c.op==='cambiar'?JSON.parse(foto.col[c.col][c.id]):null;
    rs.forEach(a=>{const k=autoDispara(a,c.col,r,antes);if(k)hizo=autoEjecutar(a,c.col,r,typeof k==='string'?k:'')||hizo});
  });
  if(AUTO_MSG.length){const m=AUTO_MSG.length>1?`${AUTO_MSG.length} automatizaciones se aplicaron. Revisa la actividad.`:'Automatización '+AUTO_MSG[0];setTimeout(()=>toast(m),1500)}
  AUTO_MSG=[];return hizo;
}
/* Fechas por vencer: se revisan al abrir la app y al cambiar de usuario */
function revisarFechas(){
  let hizo=false;const cols=colecciones(S);
  (S.auto||[]).filter(a=>a.activa&&a.disparador.tipo==='fecha').forEach(a=>(cols[a.ent]||[]).forEach(r=>{
    if(a.ent==='tasks'&&!r.name)return;const k=autoFecha(a,a.ent,r);if(k)hizo=autoEjecutar(a,a.ent,r,k)||hizo}));
  (S.auto||[]).filter(a=>a.activa&&a.disparador.tipo==='programada').forEach(a=>{const per=autoPeriodo(a.disparador);if(!per)return;
    (cols[a.ent]||[]).forEach(r=>{if(a.ent==='tasks'&&!r.name)return;const d=a.disparador,k=a.ent==='tasks'?'status':'estado';
      if(d.estado&&r[k]!==d.estado)return;const clave=`${a.id}|${r.id}|${per}`;if(S.d.autoruns.some(x=>x.clave===clave))return;
      hizo=autoEjecutar(a,a.ent,r,clave)||hizo})});
  if(alertasAcreditacion())hizo=true;
  AUTO_MSG=[];if(hizo)save('fechas');return hizo;
}

/* Período de una regla programada: la fecha en que le toca correr en el período actual, si ya llegó; si no, ''.
   cada: dia (días hábiles) · semana (dia 1 = lunes … 7 = domingo) · mes (dia 1 a 28, o 'ult' = último día hábil) */
function autoPeriodo(d){
  if(d.cada==='dia')return esHabil(TODAY)?TODAY:'';
  if(d.cada==='semana'){const f=addD(lunesDe(TODAY),(+d.dia||1)-1);return TODAY>=f?f:''}
  if(d.cada==='mes'){const ini=TODAY.slice(0,8)+'01';let f;
    if(d.dia==='ult'){f=addD(addM(ini,1),-1);while(!esHabil(f))f=addD(f,-1)}else f=TODAY.slice(0,8)+String(Math.min(28,+d.dia||1)).padStart(2,'0');
    return TODAY>=f?f:''}
  return '';
}
const DIAS_LUN=['lunes','martes','miércoles','jueves','viernes','sábado','domingo'];
function autoCadaTxt(d){return d.cada==='dia'?'Cada día hábil':d.cada==='semana'?`Cada ${DIAS_LUN[(+d.dia||1)-1]}`:d.dia==='ult'?'El último día hábil de cada mes':`El día ${+d.dia||1} de cada mes`}
