      if(r.ownerId&&r.ownerId!==antes?.ownerId)avisar(r.ownerId,`${meName()} te asignó la tarea «${r.name}»`,'tasks',r.id);
      else if(antes&&(r.comments||[]).length>(antes.comments||[]).length)avisar(r.ownerId,`${meName()} comentó en tu tarea «${r.name}»`,'tasks',r.id);
