const barraInventario=()=>`<input id="scan" type="search" placeholder="Escanear o escribir código" aria-label="Escanear código de producto" autocomplete="off"><button type="button" class="btn ghost" data-etiquetas="">Etiquetas QR</button>`;
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='scan'){e.preventDefault();const v=e.target.value;e.target.value='';escanear(v)}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-etiquetas]');if(b)imprimirEtiquetas(b.dataset.etiquetas)});

/* ===== Activos y mantención ===== */
/* Área "Activos" (MOD.activos): vehículos, herramientas, equipos e instrumentos (ENT.activos) con su responsable,
   y mantenciones programadas (ENT.mants): revisión técnica, calibraciones, preventivas, correctivas, permiso de
   circulación y seguro. Al marcar una mantención como realizada, si tiene frecuencia, se programa sola la
   siguiente (mant.siguiente apunta a ella, así no se duplica). "Solo lo suyo" ve los activos y mantenciones de
   los que es responsable. */
ICON.wrench='<path d="M14.5 5.5a4 4 0 00-5.2 5.2L4 16v4h4l5.3-5.3a4 4 0 005.2-5.2l-2.6 2.6-2.4-.6-.6-2.4z"/>';
function mantSt(r){
  if(r.estado==='Realizada')return {label:'Realizada',tone:'done'};if(r.estado==='Cancelada')return {label:'Cancelada',tone:'todo'};
  if(!r.fecha)return {label:'Sin fecha',tone:'todo'};const d=diff(TODAY,r.fecha);
  if(d<0)return {label:'Atrasada',tone:'stuck'};if(d<=30)return {label:'Próxima',tone:'prog'};return {label:'Programada',tone:'todo'};
}
const mantsDe=a=>S.d.mants.filter(m=>m.activo===a.id);
const proxMant=a=>mantsDe(a).filter(m=>m.estado==='Programada'&&m.fecha).sort((x,y)=>x.fecha<y.fecha?-1:1)[0];
function activoSt(a){
  if(a.estado==='Dado de baja')return {label:'Dado de baja',tone:'todo'};if(a.estado==='Fuera de servicio')return {label:'Fuera de servicio',tone:'stuck'};
  if(a.estado==='En mantención')return {label:'En mantención',tone:'prog'};
  const m=proxMant(a),s=m&&mantSt(m);
  if(s&&s.tone==='stuck')return {label:'Mantención atrasada',tone:'stuck'};if(s&&s.tone==='prog')return {label:'Mantención próxima',tone:'prog'};
  return {label:'Operativo',tone:'done'};
}
/* Realizada: anota la fecha y programa la siguiente si se repite */
function mantRealizada(r){
  if(r.estado!=='Realizada'||SIMULA)return;
  if(!r.realizada)r.realizada=TODAY;
  if(+r.frecuencia>0&&!r.siguiente&&r.id){
    const n={id:uid(),activo:r.activo,tipo:r.tipo,fecha:addM(r.realizada,+r.frecuencia),frecuencia:r.frecuencia,estado:'Programada',realizada:'',proveedor:r.proveedor||'',responsable:r.responsable||'',costo:'',nota:''};
    S.d.mants.push(n);r.siguiente=n.id;addLog(`Se programó la próxima ${r.tipo.toLowerCase()} de ${refName('activos',r.activo)} para el ${fmt(n.fecha)}`);
  }
}
function mantEventos(){
  return S.d.mants.filter(m=>m.fecha&&m.estado==='Programada'&&canSee('mants',m)).map(m=>({d:m.fecha,label:`${m.tipo} · ${refName('activos',m.activo)}`,c:'--s-prog',rec:'mants:'+m.id,late:m.fecha<TODAY}));
}
function mantCalendario(){
  return `<p class="hint">Mantenciones, revisiones y calibraciones programadas. Clic en una para abrirla y marcarla como realizada.</p>${calHTML(mantEventos(),false,0)}`;
}

/* ===== Plantillas de proyecto y materiales previstos ===== */
/* S.d.plantillas: {id, nombre, desc, fases:[{nombre, tareas:[{nombre, dia, dur, prio}]}], materiales:[{producto, cantidad}]}
   - dia: días desde el inicio del proyecto; dur: días que dura la tarea.
   - Al crear un proyecto con plantilla, cada tarea se crea con su fecha y con la fase como etiqueta, y el
     proyecto recibe los materiales previstos (p.materiales).
   - "Guardar como plantilla" hace lo inverso con un proyecto existente (fase = primera etiqueta de la tarea).
   - Las ve quien tiene Proyectos "Ver" o más; las crea y cambia quien puede editar proyectos.
   Vista "Materiales" del proyecto: previsto, entregado (salidas de bodega imputadas al proyecto) y stock. */
/* Texto ↔ fases. Formato: "Fase: Nombre" y luego "Tarea; día de inicio; duración en días" por línea. */
function fasesATexto(fs){return fs.map(f=>[`Fase: ${f.nombre}`,...f.tareas.map(t=>`${t.nombre}; ${t.dia}; ${t.dur}`)].join('\n')).join('\n')}
function textoAFases(txt){
  const fs=[];let err='';
  txt.split('\n').map(l=>l.trim()).filter(Boolean).forEach((l,i)=>{
    const m=/^(fase:|#)\s*(.+)$/i.exec(l);if(m){fs.push({nombre:m[2].trim(),tareas:[]});return}
    const [n,d,u]=l.split(';').map(x=>(x||'').trim());
    if(!n||isNaN(+(d||0))||isNaN(+(u||1))){err=err||`Revisa la línea ${i+1}: «${l}»`;return}
    if(!fs.length)fs.push({nombre:'General',tareas:[]});
    fs[fs.length-1].tareas.push({nombre:n,dia:Math.max(0,Math.round(+(d||0))),dur:Math.max(0,Math.round(+(u||1))),prio:'media'});
  });
  return {fs,err};
}
const prodPorTexto=t=>{const n=norm(t);return S.d.products.find(p=>norm(p.codigo)===n)||S.d.products.find(p=>norm(p.nombre)===n)};
function materialesATexto(ms){return (ms||[]).map(m=>{const p=S.d.products.find(x=>x.id===m.producto);return `${p?(p.codigo||p.nombre):'?'}; ${m.cantidad}`}).join('\n')}
function textoAMateriales(txt){
  const ms=[];let err='';
  txt.split('\n').map(l=>l.trim()).filter(Boolean).forEach(l=>{const [c,q]=l.split(';').map(x=>(x||'').trim()),p=prodPorTexto(c);
    if(!p){err=err||`No hay un producto con el código o nombre «${c}»`;return}
    if(!(+q>0)){err=err||`Revisa la cantidad de «${c}»`;return}
    const ya=ms.find(x=>x.producto===p.id);if(ya)ya.cantidad+= +q;else ms.push({producto:p.id,cantidad:+q})});
  return {ms,err};
}
const nTareas=pl=>sum(pl.fases,f=>f.tareas.length);
const duracionPl=pl=>Math.max(0,...pl.fases.flatMap(f=>f.tareas.map(t=>t.dia+t.dur)));
/* Crea las tareas y los materiales de la plantilla en el proyecto */
function aplicarPlantilla(p,pl){
  const ini=p.start||TODAY;
  pl.fases.forEach(f=>f.tareas.forEach(t=>S.tasks.push({id:uid(),projectId:p.id,name:t.nombre,ownerId:'',status:'todo',priority:t.prio||'media',
    start:addD(ini,t.dia),due:addD(ini,t.dia+t.dur),tags:[f.nombre],desc:'',subtasks:[],comments:[],createdAt:TODAY,doneAt:''})));
  p.materiales=(pl.materiales||[]).map(m=>Object.assign({},m));p.plantilla=pl.id;   // para comparar lo planificado con lo real (lecciones.js)
  if(!p.end||p.end<addD(ini,duracionPl(pl)))p.end=addD(ini,duracionPl(pl));
}
/* Sección en la página de Proyectos */
function plantillasSection(){
  if(lvl('proyectos')<2)return '';
  const rows=S.d.plantillas.map(pl=>`<tr data-plantilla="${pl.id}" tabindex="0"><td class="nm">${esc(pl.nombre)}</td><td>${pl.fases.map(f=>esc(f.nombre)).join(' → ')}</td><td class="num">${nTareas(pl)}</td><td class="num">${duracionPl(pl)} días</td><td class="num">${(pl.materiales||[]).length}</td></tr>`).join('');
  return `<section class="box" id="plsec"><h2>Plantillas de proyecto</h2><p class="hint">Fases, tareas y materiales tipo para crear proyectos repetibles. Elige una al crear un proyecto: las tareas se crean con sus fechas desde el inicio del proyecto.</p>
    <div class="tablewrap"><table class="rt"><thead><tr><th>Plantilla</th><th>Fases</th><th>Tareas</th><th>Duración</th><th>Materiales</th></tr></thead><tbody>${rows||`<tr><td colspan="5">${empty('Aún no hay plantillas.')}</td></tr>`}</tbody></table></div>
    ${canEditProj()?'<div class="bar-actions"><button class="btn ghost" data-plantillanew>+ Nueva plantilla</button></div>':''}</section>`;
}
function editPlantilla(id,base){
  const pl=id?S.d.plantillas.find(x=>x.id===id):Object.assign({nombre:'',desc:'',fases:[],materiales:[]},base||{});if(!pl)return;
  const ro=!canEditProj();
  const body=`<label class="wide">Nombre *<input name="nombre" id="pl_nombre" value="${esc(pl.nombre)}" required placeholder="Ej: Sitio ERNC"></label>
    <label class="wide">Descripción<input name="desc" value="${esc(pl.desc||'')}"></label>
    <label class="wide">Fases y tareas<textarea name="fases" id="pl_fases" rows="10" placeholder="Fase: Ingeniería&#10;Levantamiento en terreno; 0; 2&#10;Diseño eléctrico; 2; 5">${esc(fasesATexto(pl.fases))}</textarea></label>
    <p class="wide hint">Una línea «Fase: Nombre» por fase y, debajo, una línea por tarea: <b>nombre; día de inicio; duración en días</b>. El día 0 es el inicio del proyecto.</p>
    <label class="wide">Materiales tipo<textarea name="materiales" id="pl_mat" rows="4" placeholder="PAN-550; 20&#10;BAT-200; 8">${esc(materialesATexto(pl.materiales))}</textarea></label>
    <p class="wide hint">Una línea por material: <b>código o nombre del producto; cantidad</b>.</p>${aprendizajeBloque(pl)}`;
  openModal(id?esc(pl.nombre):'Nueva plantilla de proyecto',null,{},ro?null:o=>{
    pl.nombre=o.nombre;pl.desc=o.desc||'';pl.fases=textoAFases(o.fases||'').fs;pl.materiales=textoAMateriales(o.materiales||'').ms;
    if(!id){pl.id='pl_'+uid();S.d.plantillas.push(pl)}addLog(`${meName()} ${id?'editó':'creó'} la plantilla «${pl.nombre}»`);
  },id&&!ro?()=>{S.d.plantillas=S.d.plantillas.filter(x=>x!==pl);addLog(`${meName()} eliminó la plantilla «${pl.nombre}»`)}:null,'¿Eliminar esta plantilla? Los proyectos ya creados no cambian.',null,body,{ro});
  modalValidate=o=>{const a=textoAFases(o.fases||''),b=textoAMateriales(o.materiales||'');
    if(a.err)return a.err;if(!nTareas({fases:a.fs}))return 'Agrega al menos una tarea.';if(b.err)return b.err;
    if(S.d.plantillas.some(x=>x!==pl&&norm(x.nombre)===norm(o.nombre)))return 'Ya existe una plantilla con ese nombre.';return ''};
}
function plantillaDeProyecto(){
  const p=proj(S.ui.projectId);if(!p||!canEditProj())return;const ini=p.start||TODAY,fs=[];
  S.tasks.filter(t=>t.projectId===p.id&&t.name).sort((a,b)=>(a.start||a.due||'9')<(b.start||b.due||'9')?-1:1).forEach(t=>{
    const fn=t.tags[0]||'General';let f=fs.find(x=>x.nombre===fn);if(!f)fs.push(f={nombre:fn,tareas:[]});
    const a=t.start||t.due||ini,b=t.due||a;f.tareas.push({nombre:t.name,dia:Math.max(0,diff(ini,a)),dur:Math.max(0,diff(a,b)),prio:t.priority||'media'})});
  editPlantilla(null,{nombre:`${p.name} (plantilla)`,desc:p.desc||'',fases:fs,materiales:p.materiales||[]});
}
/* Vista "Materiales" del proyecto */
function entregado(pid,prod){return sum(S.d.moves.filter(m=>m.proyecto===pid&&m.producto===prod&&m.tipo==='Salida'),m=>m.cantidad)}
function projMateriales(){
  const p=proj(S.ui.projectId),ms=p.materiales||[],puede=canCreate('moves','logistica');
  const fila=m=>{const pr=S.d.products.find(x=>x.id===m.producto);if(!pr)return '';const e=entregado(p.id,pr.id),falta=Math.max(0,m.cantidad-e),st=stockOf(pr);
    const s=!falta?{label:'Entregado',tone:'done'}:st>=falta?{label:'Pendiente',tone:'prog'}:{label:'Falta stock',tone:'stuck'};
    return `<tr><td class="nm">${esc(REF.products.label(pr))}</td><td class="r num">${m.cantidad} ${esc(pr.unidad||'')}</td><td class="r num">${e}</td><td class="r num">${falta}</td><td class="r num ${st<falta?'late':''}">${st}</td><td>${tonePill(s)}</td>
      <td>${falta&&puede?`<button type="button" class="btn ghost sm" data-salida="${pr.id}:${falta}">Registrar salida</button>`:''}</td></tr>`};
  return `<p class="hint">Materiales previstos para el proyecto (vienen de la plantilla o se editan en «Editar proyecto»). Lo entregado son las salidas de bodega imputadas a este proyecto.</p>
  <div class="tablewrap"><table class="rt"><thead><tr><th>Material</th><th class="r">Previsto</th><th class="r">Entregado</th><th class="r">Falta</th><th class="r">En bodega</th><th>Estado</th><th></th></tr></thead><tbody>
  ${ms.map(fila).join('')||`<tr><td colspan="7">${empty('Este proyecto no tiene materiales previstos.')}</td></tr>`}</tbody></table></div>`;
}
document.addEventListener('click',e=>{
  if(e.target.closest('[data-plantillanew]'))return editPlantilla();
  const r=e.target.closest('[data-plantilla]');if(r&&!e.target.closest('#modal'))return editPlantilla(r.dataset.plantilla);
  const s=e.target.closest('[data-salida]');if(s){const [prod,q]=s.dataset.salida.split(':');return editRec('moves',null,{tipo:'Salida',producto:prod,cantidad:+q,proyecto:S.ui.projectId},'logistica')}
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset&&e.target.dataset.plantilla)editPlantilla(e.target.dataset.plantilla)});

/* ===== Carga de trabajo por persona ===== */
/* Horas estimadas de cada tarea (t.horas; vacío = HORAS_DEF) repartidas en los días hábiles entre su inicio y su
   plazo; lo atrasado cuenta en la semana actual y lo que empezó antes, desde hoy. Capacidad semanal de cada persona
   (p.capacidad; vacío = la jornada de la empresa, jornada()). Sobre el 100 % es sobrecarga (rojo, con alerta en Inicio); desde el 80 %, amarillo.
   Solo cuentan las tareas abiertas, con nombre y con fecha. Descuenta los feriados (esHabil, función 31). */
const HORAS_DEF=8,CARGA_SEMANAS=6;
/* Jornada semanal: la que fije la empresa (S.jornada.horas) o la legal en Chile a esa fecha (Ley 21.561: 44 h,
   42 h desde el 26-04-2026 y 40 h desde el 26-04-2028) */
const jornadaLegal=f=>(f||TODAY)>='2028-04-26'?40:(f||TODAY)>='2026-04-26'?42:44;
const jornada=f=>+(typeof S!=='undefined'&&S?.jornada?.horas)>0?+S.jornada.horas:jornadaLegal(f);
const horasTarea=t=>+t.horas>0?+t.horas:HORAS_DEF;
const capacidad=p=>+p?.capacidad>0?+p.capacidad:jornada();
const lunesDe=d=>addD(d,-((P(d).getDay()+6)%7));
const semanasCarga=(n=CARGA_SEMANAS)=>[...Array(n)].map((_,i)=>addD(lunesDe(TODAY),i*7));
/* Horas de una tarea por semana (lunes → horas) */
function repartir(t){
  let a=t.start||t.due,b=t.due||t.start;if(!b)return {};
  if(b<TODAY)a=b=TODAY;else if(a<TODAY)a=TODAY;if(a>b)a=b;
  const dias=[];for(let d=a;d<=b;d=addD(d,1)){if(esHabil(d))dias.push(d)}
  if(!dias.length)dias.push(b);
  const h=horasTarea(t),r={};dias.forEach(d=>{const s=lunesDe(d);r[s]=(r[s]||0)+h/dias.length});return r;
}
function cargaDe(pid,semanas){
  const tot={};S.tasks.filter(t=>t.ownerId===pid&&t.status!=='done'&&t.name).forEach(t=>Object.entries(repartir(t)).forEach(([s,h])=>{tot[s]=(tot[s]||0)+h}));
  return semanas.map(s=>Math.round((tot[s]||0)*10)/10);
}
const cargaTono=(h,cap)=>h>cap?'stuck':h>=cap*.8?'prog':h?'done':'todo';
const hTxt=h=>`${String(h).replace('.',',')}\u00a0h`;   // espacio que no se corta: «97,5 h» en una línea
/* Sobrecargas de esta semana y la siguiente (para las alertas) */
function sobrecargas(){
  if(!fnOn('carga'))return [];
  const ss=semanasCarga(2),ppl=lvl('proyectos')>=2?S.people.filter(p=>p.estado!=='Inactivo'):[person(S.me)].filter(Boolean),out=[];
  ppl.forEach(p=>cargaDe(p.id,ss).forEach((h,i)=>{if(h>capacidad(p))out.push({p,semana:ss[i],h,cap:capacidad(p)})}));return out;
}
function cargaSection(){
  if(lvl('proyectos')<2)return '';
  const ss=semanasCarga(),ppl=S.people.filter(p=>p.estado!=='Inactivo'&&S.tasks.some(t=>t.ownerId===p.id&&t.status!=='done'));
  const fila=p=>{const c=cargaDe(p.id,ss),cap=capacidad(p);
    return `<tr><td class="nm"><span class="who">${av(p.id)}<span>${esc(p.name)}<br><span class="hint">${cap} h por semana</span></span></span></td>
      ${c.map(h=>{const x=TONES[cargaTono(h,cap)];return `<td class="r"><span class="carga" style="background:var(${x.bg});color:var(${x.t})" title="${hTxt(h)} de ${cap} h">${hTxt(h)}<small>${h>cap?`+${hTxt(h-cap)} extra`:`${Math.round(h/cap*100)}%`}</small></span></td>`}).join('')}</tr>`};
  return `<section class="box" id="cargasec"><h2>Carga por semana <span class="hint sub">horas estimadas de tareas abiertas</span></h2>
    <p class="hint">Cada tarea reparte sus horas estimadas en los días hábiles entre su inicio y su plazo (sin horas, cuenta ${HORAS_DEF} h). Verde: con espacio; amarillo: desde el 80 % de la jornada; rojo: pasa la jornada, y lo que sobra se muestra como horas extra. Las horas de cada tarea y la capacidad de cada persona se cambian en la tarea y en su ficha.</p>
    <div class="tablewrap"><table class="rt cargat"><thead><tr><th>Persona</th>${ss.map((s,i)=>`<th class="r">${i===0?'Esta semana':`Sem. ${fmtShort(s)}`}</th>`).join('')}</tr></thead><tbody>
    ${ppl.map(fila).join('')||`<tr><td colspan="${ss.length+1}">${empty('Nadie tiene tareas abiertas.')}</td></tr>`}</tbody></table></div></section>`;
}
/* Resumen propio en "Mis tareas" */
function miCarga(){const p=person(S.me);if(!p)return '';const [h]=cargaDe(p.id,semanasCarga(1)),cap=capacidad(p);
  return `<p class="hint">Esta semana tienes ${hTxt(h)} estimadas de ${cap} h ${tonePill({label:h>cap?'Sobrecarga':h>=cap*.8?'Cerca del límite':'Con espacio',tone:cargaTono(h,cap)})}</p>`}

/* ===== Costo real contra presupuesto por proyecto ===== */
/* Datos del proyecto: presupuesto de costo (p.presupuesto), monto del contrato (p.contrato; vacío = ventas
   facturadas) y valor hora de la mano de obra (p.valorHora). Todo en CLP.
   - Costo real = facturas de proveedor + rendiciones aprobadas + materiales de bodega (projFin) + mano de obra
     (horas de las tareas listas × valor hora). Comprometido = real + OC aprobadas o compradas sin recibir.
   - Avance físico = horas de tareas listas / horas de todas las tareas (horasTarea). Avance financiero = real / presupuesto.
   - Costo estimado al término = real + presupuesto × (1 − avance físico) (sin presupuesto: el comprometido).
   - Margen estimado = contrato − costo estimado al término. */
function presupuestoDe(p){
  const f=projFin(p.id),ts=S.tasks.filter(t=>t.projectId===p.id&&t.name);
  const hTot=sum(ts,horasTarea),hHechas=sum(ts.filter(t=>t.status==='done'),horasTarea);
  const mo=Math.round(hHechas*(+p.valorHora||0)),real=f.costo+mo,comprometido=real+f.oc;
  const pres=+p.presupuesto||0,contrato=+p.contrato||f.ventas,fis=hTot?hHechas/hTot:0,fin=pres?real/pres:null;
  const eac=pres?Math.round(real+pres*(1-fis)):comprometido,margen=contrato?contrato-eac:null;
  return {f,hTot,hHechas,mo,real,comprometido,pres,contrato,fis,fin,eac,margen};
}
const pct=x=>x==null?'—':`${Math.round(x*100)}%`;
function presEstado(x){
  if(!x.pres)return {label:'Sin presupuesto',tone:'todo'};
  if(x.eac>x.pres*1.0001)return {label:'Sobre presupuesto',tone:'stuck'};
  if(x.fin!=null&&x.fin-x.fis>0.10)return {label:'Gasto adelantado',tone:'prog'};
  return {label:'En línea',tone:'done'};
}
const barra=(v,c)=>`<span class="bar pbar" data-sem="no"><span style="width:${Math.min(100,Math.round((v||0)*100))}%;background:var(${c})"></span></span>`;
/* Bloque superior de "Costos y compras" del proyecto */
function presupuestoBloque(p){
  const x=presupuestoDe(p),s=presEstado(x);
  return `<div class="kpis">${kpi('Presupuesto de costo',x.pres?fmtMoney(x.pres):'—','money',x.pres?`Contrato ${x.contrato?fmtMoney(x.contrato):'—'}`:'Defínelo en «Editar proyecto»')}
    ${kpi('Costo real',fmtMoney(x.real),'money',`Facturas ${fmtMoney(x.f.compras)} · Rendiciones ${fmtMoney(x.f.rends)} · Bodega ${fmtMoney(x.f.mat)} · Mano de obra ${fmtMoney(x.mo)}`)}
    ${kpi('Costo estimado al término',fmtMoney(x.eac),'money'+(x.pres&&x.eac>x.pres?' bad':''),x.pres?`${x.eac>x.pres?'Sobre':'Bajo'} el presupuesto en ${fmtMoney(Math.abs(x.pres-x.eac))}`:'Sin presupuesto: costo comprometido')}
    ${kpi('Margen estimado',x.margen==null?'—':fmtMoney(x.margen),'money'+(x.margen<0?' bad':''),x.contrato&&x.margen!=null?`${Math.round(x.margen/x.contrato*100)}% del contrato`:'Sin contrato ni ventas')}</div>
  <section class="box"><h2>Avance físico y financiero ${tonePill(s)}</h2>
    <div class="avances"><span>Avance físico <b>${pct(x.fis)}</b></span>${barra(x.fis,'--s-done')}<span class="hint">${hTxt(Math.round(x.hHechas*10)/10)} de ${hTxt(Math.round(x.hTot*10)/10)} en tareas listas</span>
    <span>Presupuesto gastado <b>${pct(x.fin)}</b></span>${barra(x.fin,x.fin!=null&&x.fin-x.fis>0.10?'--s-stuck':'--accent2')}<span class="hint">${fmtMoney(x.real)} de ${x.pres?fmtMoney(x.pres):'—'}</span></div>
    <p class="hint">Si el gasto va más adelantado que el avance físico, el proyecto terminará costando más de lo presupuestado. Comprometido con OC aún no recibidas: ${fmtMoney(x.f.oc)}.</p></section>`;
}
/* Tabla de todos los proyectos con presupuesto (Contabilidad → Resultado por proyecto) */
function presupuestoTabla(){
  const rows=S.projects.filter(p=>+p.presupuesto>0).map(p=>({p,x:presupuestoDe(p)}));
  if(!rows.length)return `<h2 class="sh">Presupuesto contra real</h2>${empty('Ningún proyecto tiene presupuesto. Defínelo en «Editar proyecto».')}`;
  const td=(v,neg)=>`<td class="r num nw ${neg&&v<0?'late':''}">${v==null?'—':fmtMoney(v)}</td>`;
  return `<h2 class="sh">Presupuesto contra real</h2><div class="tablewrap"><table class="rt"><thead><tr><th>Proyecto</th><th class="r">Presupuesto</th><th class="r">Costo real</th><th class="r">Gastado</th><th class="r">Avance físico</th><th class="r">Estimado al término</th><th class="r">Margen estimado</th><th>Estado</th></tr></thead><tbody>
  ${rows.map(({p,x})=>`<tr data-proj="${p.id}" tabindex="0"><td class="nm"><span class="who"><span class="pdot" style="background:${pcol(p)}"></span>${esc(p.name)}</span></td>${td(x.pres)}${td(x.real)}<td class="r num">${pct(x.fin)}</td><td class="r num">${pct(x.fis)}</td>${td(x.eac)}${td(x.margen,1)}<td>${tonePill(presEstado(x))}</td></tr>`).join('')}</tbody></table></div>`;
}
/* Alertas: proyectos activos sobre presupuesto o con el gasto adelantado */
function alertasPresupuesto(){
  if(!fnOn('presupuesto')||(lvl('contabilidad')<2&&lvl('proyectos')<2))return [];
  return S.projects.filter(p=>p.status==='activo'&&+p.presupuesto>0).map(p=>({p,x:presupuestoDe(p)})).map(({p,x})=>({p,x,s:presEstado(x)})).filter(o=>o.s.tone!=='done')
    .map(({p,x,s})=>({tone:s.tone,mod:'Proyectos',txt:`${s.label} · ${p.name}`,det:`Gastado ${pct(x.fin)} con avance físico ${pct(x.fis)} · estimado ${fmtMoney(x.eac)} de ${fmtMoney(x.pres)}`,proj:p.id,d:TODAY}));
}

/* ===== Cuadro comparativo de cotizaciones ===== */
/* ENT.cotizaciones (Compras), con su propio editor (ENT[x].editor en editRec):
     {id, num:'CC-0001', titulo, proyecto, solicitante, fecha, estado:'Abierta'|'Adjudicada'|'Anulada',
      items:[{d, q}], ofertas:[{id, proveedor, moneda, precios:[por ítem], plazo, validez, condiciones}],
      elegida (id de oferta), justificacion, oc (id de la OC generada)}
   Total de cada oferta = suma de cantidad × precio. Si se elige una que no es la más barata (en la misma moneda),
   hay que justificarlo. "Generar OC" crea la OC en Borrador con las líneas y precios de la elegida. */
const CC_MAX=5;
const totalOferta=(cc,o)=>Math.round(cc.items.reduce((a,it,i)=>a+(+it.q||0)*(+(o.precios||[])[i]||0),0)*100)/100;
function masBarata(cc){const os=cc.ofertas.filter(o=>o.proveedor&&totalOferta(cc,o)>0);if(!os.length)return null;
  const mon=os[0].moneda;if(os.some(o=>o.moneda!==mon))return null;return os.reduce((a,o)=>totalOferta(cc,o)<totalOferta(cc,a)?o:a)}
const ofertaElegida=cc=>cc.ofertas.find(o=>o.id===cc.elegida);
function ccSt(cc){return toneOf({Abierta:'prog',Adjudicada:'done',Anulada:'stuck'},cc.estado)}
let ccCtx=null;
function ccBody(cc,ro){
  const dis=ro?'disabled':'',provs=S.d.contacts.filter(c=>c.tipo!=='Cliente'),mb=masBarata(cc);
  const selP=(j,v)=>`<select name="of_prov_${j}" ${dis} aria-label="Proveedor ${j+1}"><option value="">Proveedor…</option>${provs.map(c=>`<option value="${c.id}" ${c.id===v?'selected':''}>${esc(c.nombre)}</option>`).join('')}</select>`;
  const selM=(j,v)=>`<select name="of_mon_${j}" ${dis} aria-label="Moneda ${j+1}">${['CLP','USD','EUR','UF'].map(m=>`<option ${m===v?'selected':''}>${m}</option>`).join('')}</select>`;
  const O=cc.ofertas;
  return `<label>Título *<input name="titulo" value="${esc(cc.titulo||'')}" required ${dis} placeholder="Ej: Paneles para sitio Norte"></label>
    <label>Proyecto o centro de costo<select name="proyecto" ${dis}><option value="">—</option>${opts(S.projects,cc.proyecto)}</select></label>
    <label>Fecha<input type="date" name="fecha" value="${esc(cc.fecha||'')}" ${dis}></label>
    <label>Estado<select name="estado" ${dis}>${['Abierta','Adjudicada','Anulada'].map(s=>`<option ${s===cc.estado?'selected':''}>${s}</option>`).join('')}</select></label>
    <div class="wide"><div class="tablewrap"><table class="ccuadro"><thead><tr><th>Ítem</th><th class="r">Cant.</th>${O.map((o,j)=>`<th>${selP(j,o.proveedor)}${selM(j,o.moneda)}${ro?'':`<button type="button" class="x sm" data-cc="delof:${j}" aria-label="Quitar cotización ${j+1}">×</button>`}</th>`).join('')}</tr></thead><tbody>
      ${cc.items.map((it,i)=>`<tr><td><input name="it_d_${i}" value="${esc(it.d||'')}" ${dis} placeholder="Descripción" aria-label="Ítem ${i+1}">${ro?'':`<button type="button" class="x sm" data-cc="delitem:${i}" aria-label="Quitar ítem">×</button>`}</td><td><input name="it_q_${i}" type="number" step="any" value="${esc(it.q??1)}" ${dis} aria-label="Cantidad ${i+1}"></td>
        ${O.map((o,j)=>`<td><input name="of_p_${j}_${i}" type="number" step="any" value="${esc((o.precios||[])[i]??'')}" ${dis} placeholder="Precio unitario" aria-label="Precio de ${i+1} en cotización ${j+1}"></td>`).join('')}</tr>`).join('')}
      <tr class="cctot"><td colspan="2"><b>Total neto</b></td>${O.map(o=>`<td class="num"><b>${fmtMoney(totalOferta(cc,o),o.moneda)}</b>${mb&&mb.id===o.id?' <span class="pill" style="background:var(--s-done-bg);color:var(--t-done)">Más barata</span>':''}</td>`).join('')}</tr>
      <tr><td colspan="2">Plazo de entrega (días)</td>${O.map((o,j)=>`<td><input name="of_plazo_${j}" type="number" value="${esc(o.plazo??'')}" ${dis} aria-label="Plazo ${j+1}"></td>`).join('')}</tr>
      <tr><td colspan="2">Condiciones de pago</td>${O.map((o,j)=>`<td><input name="of_cond_${j}" value="${esc(o.condiciones||'')}" ${dis} placeholder="Ej: 30 días" aria-label="Condiciones ${j+1}"></td>`).join('')}</tr>
      <tr><td colspan="2">Válida hasta</td>${O.map((o,j)=>`<td><input name="of_val_${j}" type="date" value="${esc(o.validez||'')}" ${dis} aria-label="Validez ${j+1}"></td>`).join('')}</tr>
      <tr><td colspan="2"><b>Elegida</b></td>${O.map((o,j)=>`<td><label class="subl"><input type="radio" name="elegida" value="${j}" ${o.id===cc.elegida?'checked':''} ${dis}> Elegir</label></td>`).join('')}</tr>
    </tbody></table></div>
    ${ro?'':`<div class="bar-actions"><button type="button" class="btn ghost sm" data-cc="additem">+ Ítem</button><button type="button" class="btn ghost sm" data-servidor="8:Pedir las cotizaciones por el portal de proveedores">Pedir cotizaciones por el portal</button>${O.length<CC_MAX?'<button type="button" class="btn ghost sm" data-cc="addof">+ Cotización</button>':''}</div>`}</div>
    <label class="wide">Justificación de la elección (obligatoria si no es la más barata)<textarea name="justificacion" rows="2" ${dis}>${esc(cc.justificacion||'')}</textarea></label>
    ${cc.oc?`<p class="wide hint">Generó la orden de compra <b>${esc(refName('ocs',cc.oc)||'(eliminada)')}</b>.</p>`:''}`;
}
/* Lee el formulario a un borrador (sin perder lo que no está en pantalla) */
function ccDeForm(cc,o){
  const d=JSON.parse(JSON.stringify(cc));
  ['titulo','proyecto','fecha','estado','justificacion'].forEach(k=>{if(k in o)d[k]=o[k]});
  d.items=d.items.map((it,i)=>({d:o[`it_d_${i}`]??it.d,q:o[`it_q_${i}`]===''?'':+(o[`it_q_${i}`]??it.q)}));
  d.ofertas=d.ofertas.map((of,j)=>Object.assign(of,{proveedor:o[`of_prov_${j}`]??of.proveedor,moneda:o[`of_mon_${j}`]??of.moneda,
    precios:d.items.map((_,i)=>{const v=o[`of_p_${j}_${i}`];return v===undefined?(of.precios||[])[i]??'':v===''?'':+v}),
    plazo:o[`of_plazo_${j}`]===''?'':+(o[`of_plazo_${j}`]??of.plazo),condiciones:o[`of_cond_${j}`]??of.condiciones,validez:o[`of_val_${j}`]??of.validez}));
  d.elegida=o.elegida!==undefined&&d.ofertas[+o.elegida]?d.ofertas[+o.elegida].id:'';
  return d;
}
function editCotizacion(id,preset,mod){
  const E=ENT.cotizaciones,isNew=!id;mod=mod||'compras';
  if(isNew&&!canCreate('cotizaciones',mod))return toast('Tu rol no permite crear cuadros comparativos');
  const cc=isNew?Object.assign(E.defaults(),preset||{}):S.d.cotizaciones.find(x=>x.id===id);if(!cc)return;
  if(!isNew&&!canSee('cotizaciones',cc,mod))return toast('Tu rol no permite ver este cuadro');
  const ro=!isNew&&!canEditRec('cotizaciones',cc,mod);
  const acts=isNew?[]:actionsFor('cotizaciones',cc,mod),ctx={cc,ro,vista:JSON.parse(JSON.stringify(cc))};
  openModal(isNew?'Nuevo cuadro comparativo':esc(E.title(cc)),null,{},o=>{
    Object.assign(cc,ccDeForm(ctx.vista,o));
    if(isNew){cc.id=uid();cc.num=siguienteNum('cotizaciones');S.d.cotizaciones.push(cc)}
    addLog(`${meName()} ${isNew?'creó':'actualizó'} el cuadro comparativo ${cc.num}: ${cc.titulo}`);
  },!isNew&&!ro?()=>{S.d.cotizaciones=S.d.cotizaciones.filter(x=>x!==cc);addLog(`${meName()} eliminó el cuadro comparativo ${cc.num}`)}:null,'¿Eliminar este cuadro comparativo?',acts,ccBody(cc,ro),{ro});
  ccCtx=ctx;modalCtx={ent:'cotizaciones',id:cc.id,mod};
  modalValidate=o=>{const d=ccDeForm(ctx.vista,o);
    if(!d.items.some(it=>it.d))return 'Agrega al menos un ítem.';
    if(d.elegida){const el=ofertaElegida(d),mb=masBarata(d);if(!el.proveedor)return 'La cotización elegida no tiene proveedor.';
      if(!(totalOferta(d,el)>0))return 'La cotización elegida no tiene precios.';
      if(mb&&mb.id!==el.id&&!String(d.justificacion||'').trim())return 'Elegiste una cotización que no es la más barata: escribe la justificación.'}
    return ''};
}
/* Cambios de estructura (+ítem, +cotización, quitar): se relee el formulario y se vuelve a dibujar */
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-cc]');if(!b||!ccCtx)return;
  const d=ccDeForm(ccCtx.vista,Object.fromEntries(new FormData($('modal')))),[acc,i]=b.dataset.cc.split(':');
  if(acc==='additem'){d.items.push({d:'',q:1});d.ofertas.forEach(of=>of.precios.push(''))}
  else if(acc==='addof'&&d.ofertas.length<CC_MAX)d.ofertas.push({id:uid(),proveedor:'',moneda:'CLP',precios:d.items.map(()=>''),plazo:'',condiciones:'',validez:''});
  else if(acc==='delitem'&&d.items.length>1){d.items.splice(+i,1);d.ofertas.forEach(of=>of.precios.splice(+i,1))}
  else if(acc==='delof'&&d.ofertas.length>1){if(d.ofertas[+i].id===d.elegida)d.elegida='';d.ofertas.splice(+i,1)}
  ccCtx.vista=d;$('modal').querySelector('.mgrid').innerHTML=ccBody(d,ccCtx.ro);   // el registro real solo cambia al guardar
});
/* Totales en vivo */
document.addEventListener('input',e=>{
  if(!ccCtx||!e.target.closest('#modal .ccuadro'))return;
  const d=ccDeForm(ccCtx.vista,Object.fromEntries(new FormData($('modal')))),mb=masBarata(d);
  $('modal').querySelectorAll('.cctot td.num').forEach((td,j)=>{const of=d.ofertas[j];if(of)td.innerHTML=`<b>${fmtMoney(totalOferta(d,of),of.moneda)}</b>${mb&&mb.id===of.id?' <span class="pill" style="background:var(--s-done-bg);color:var(--t-done)">Más barata</span>':''}`});
});
/* La cotización elegida genera la OC (botón de acción: runAction anota y guarda) */
function generarOC(cc){
  const of=ofertaElegida(cc);if(SIMULA||!of||cc.oc||!canCreate('ocs','compras'))return;
  const lineas=cc.items.map((it,i)=>({d:it.d,q:+it.q||0,p:+(of.precios[i]||0)})).filter(l=>l.d&&l.q);
  const oc={id:uid(),num:siguienteNum('ocs'),tipo:'Nacional',proveedor:of.proveedor,proyecto:cc.proyecto||'',fecha:TODAY,
    entrega:of.plazo!==''&&of.plazo!=null?addD(TODAY,+of.plazo):'',moneda:of.moneda,solicitante:S.me,lineas,neto:Math.round(sum(lineas,l=>l.q*l.p)*100)/100,estado:'Borrador',
    detalle:`Desde el cuadro comparativo ${cc.num} (${cc.titulo}).${cc.justificacion?' Elección: '+cc.justificacion:''}${of.condiciones?' Condiciones: '+of.condiciones+'.':''}`};
  S.d.ocs.push(oc);cc.oc=oc.id;cc.estado='Adjudicada';
  setTimeout(()=>{editRec('ocs',oc.id,null,'compras');toast(`${oc.num} creada en borrador: revísala y envíala a aprobación`)},0);
}


/* ===== Libro de obra digital e informe de avance al cliente ===== */
/* ENT.bitacora: una entrada por día y proyecto (clima, personal en obra, actividades, incidentes, visitas), con fotos
   adjuntas (gestor documental). Vive dentro del proyecto (vista "Libro de obra"), no en una pestaña de área:
   ENT.bitacora.enProyecto hace que areaDeRegistro la reconozca. Dueño = autor; "Solo lo suyo" escribe sus entradas y
   las corrige el mismo día.
   Informe al cliente: página HTML del período elegido con avance por fase, tareas terminadas y próximas, bitácora con
   fotos, materiales instalados e incidentes; para imprimir o guardar como PDF. */
