/* ===== Estados de pago ligados a hitos ===== */
/* ENT.edps (Contabilidad → "Estados de pago", y vista del proyecto): cada estado de pago es un hito del proyecto
   con su monto (o porcentaje del contrato) y, si se quiere, la tarea que lo cumple.
   Estado guardado: Pendiente → Enviado al cliente → Aprobado por el cliente → Facturado (o Anulado).
   "Listo para cobrar" no se guarda: se calcula (Pendiente y la tarea ligada está lista, o sin tarea). Así quien cierra
   la tarea no necesita permisos de Contabilidad. Al cerrarse la tarea se avisa a quienes editan Contabilidad.
   "Generar factura" crea la factura de venta del EDP (cliente del proyecto, monto neto, línea con el hito). */
const montoEDP=r=>+r.monto>0?+r.monto:Math.round((+proj(r.proyecto)?.contrato||0)*(+r.porcentaje||0)/100);
const edpListo=r=>r.estado==='Pendiente'&&(!r.tarea||task(r.tarea)?.status==='done');
function edpSt(r){
  if(edpListo(r))return {label:'Listo para cobrar',tone:'prog'};
  return toneOf({Pendiente:'todo','Enviado al cliente':'prog','Aprobado por el cliente':'prog',Facturado:'done',Anulado:'stuck'},r.estado);
}
const clienteDe=p=>p&&S.d.contacts.find(c=>norm(c.nombre)===norm(p.client||''));
function facturarEDP(r){
  if(SIMULA||r.factura)return;const p=proj(r.proyecto),m=montoEDP(r);
  const d={id:uid(),tipo:'Venta',numero:`Por emitir · ${r.num}`,contraparte:clienteDe(p)?.id||'',proyecto:r.proyecto,emision:TODAY,vence:addD(TODAY,30),
    lineas:[{d:`${r.num}: ${r.hito}${p?' · '+p.name:''}`,q:1,p:m}],neto:m,pagado:0,notas:`Estado de pago ${r.num}`};
  S.d.docs.push(d);r.factura=d.id;r.estado='Facturado';if(!r.fecha)r.fecha=TODAY;
  setTimeout(()=>{editRec('docs',d.id,null,'contabilidad');toast('Factura creada: completa el N° de documento y guarda')},0);
}
