const posGasto=x=>indice('posGasto',S.d.rends,rs=>new Map(rs.map((y,i)=>[y,i]))).get(x)??0;   // empates en el orden de siempre
const dupTag=r=>{const s=similares(r);return s.length?`<span class="duptag" title="${esc(`Se parece ${s[0].p}% a ${gastoNombre(s[0].r)} del ${fmt(s[0].r.fecha)}`)}">Posible duplicado ${s[0].p}%</span>`:''};
const dupInforme=inf=>{const n=gastosDe(inf).filter(x=>similares(x).length).length;return n?`<span class="duptag">${cuenta(n,'gasto parecido a otro','gastos parecidos a otros')}</span>`:''};
