/* ===== Lector del código de barras de boletas y facturas (pedido de Miguel, 20-10-2026) =====
   Las boletas y facturas electrónicas chilenas traen el timbre electrónico del SII: un código PDF417 con un XML (TED)
   que dice el RUT del emisor (RE), el tipo de documento (TD), el folio (F), la fecha de emisión (FE), el monto total
   (MNT) y la razón social del emisor (RS, dentro del CAF). Con eso se llena la rendición sin escribir.
   El botón «Escanear código» abre la cámara y lee en vivo (escanearCodigo); la foto se lee igual (leerCodigoDe).
   Lee primero con el lector del propio navegador (BarcodeDetector: Chrome en Android y otros; funciona sin internet)
   y, si no hay, con ZXing (cdn.jsdelivr.net, se carga la primera vez que hace falta). */
const ZXING_URL='https://cdn.jsdelivr.net/npm/@zxing/library@0.21.3/umd/index.min.js';
// Huella del archivo (SRI): si el CDN entregara otro contenido, el navegador no lo ejecuta. Se calcula con el paquete de npm
// (el mismo archivo) y pruebas/correr.mjs sri la compara con lo que entrega el CDN.
const ZXING_SRI='sha384-BzBxP10ZE72aitqj5UMmUsbKFliP/DZqA8Wq+BNNhlIJDGoEd1tpkMYXOg9+n6sB';
const TIPO_DTE={33:'Factura',34:'Factura',46:'Factura',39:'Boleta',41:'Boleta',52:'Otro',56:'Otro',61:'Otro',110:'Factura'};
let zxingCargando=null;
const cargarZXing=()=>zxingCargando??=new Promise((ok,mal)=>{if(window.ZXing)return ok(window.ZXing);
  const s=document.createElement('script');s.src=ZXING_URL;s.integrity=ZXING_SRI;s.crossOrigin='anonymous';s.onload=()=>window.ZXing?ok(window.ZXing):mal(new Error('ZXing no cargó'));
  s.onerror=()=>{zxingCargando=null;mal(new Error('sin conexión para cargar el lector'))};document.head.appendChild(s)});
async function leerCodigoDe(src){
  const img=await new Promise((ok,mal)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=()=>mal(new Error('No pude abrir la imagen'));i.src=src});
  if('BarcodeDetector' in window){
    try{const fmts=await BarcodeDetector.getSupportedFormats();const usar=['pdf417','qr_code','data_matrix','aztec'].filter(f=>fmts.includes(f));
      if(usar.length){const r=await new BarcodeDetector({formats:usar}).detect(img);const t=(r.find(x=>x.format==='pdf417')||r[0])?.rawValue;if(t)return t}}
    catch(e){}
  }
  const Z=await cargarZXing();
  const hints=new Map();hints.set(Z.DecodeHintType.POSSIBLE_FORMATS,[Z.BarcodeFormat.PDF_417,Z.BarcodeFormat.QR_CODE]);hints.set(Z.DecodeHintType.TRY_HARDER,true);
  const lector=new Z.BrowserMultiFormatReader(hints);
  // Fotos grandes: se prueba a tamaño completo y reducida (el PDF417 de una boleta es chico)
  for(const k of [1,0.6]){
    const c=document.createElement('canvas');c.width=Math.round(img.width*k);c.height=Math.round(img.height*k);c.getContext('2d').drawImage(img,0,0,c.width,c.height);
    try{const r=await lector.decodeFromImageUrl(c.toDataURL('image/png'));if(r)return r.getText()}catch(e){}
  }
  return null;
}
/* Timbre del SII → datos del documento (null si el texto no es un TED) */
function leerTED(t){
  t=String(t||'');if(!/<TED[\s>]/i.test(t)||!/<DD>/i.test(t))return null;
  const tag=(n,dentro)=>{const m=(dentro||t).match(new RegExp(`<${n}>([^<]*)</${n}>`,'i'));return m?m[1].trim():''};
  const caf=(t.match(/<CAF[\s\S]*?<\/CAF>/i)||[''])[0];
  const td=+tag('TD');
  return {rut:tag('RE'),emisor:tag('RS',caf)||tag('RS'),tipoDTE:td,tipo:TIPO_DTE[td]||'Otro',folio:tag('F'),fecha:/^\d{4}-\d{2}-\d{2}$/.test(tag('FE'))?tag('FE'):'',monto:+tag('MNT')||0};
}
/* Llena la ficha abierta (rendición o factura de proveedor) con lo que dice el timbre */
function llenarDesdeTED(ent,d){
  const puestos=[],pon=(k,v,et)=>{if(ponerCampo(k,v))puestos.push(et)};
  if(ent==='rends'){pon('fecha',d.fecha,'fecha');pon('comercio',d.emisor,'proveedor');pon('rutComercio',d.rut,'RUT');pon('tipoDoc',d.tipo,'tipo de documento');
    pon('numDoc',d.folio,'N° de documento');pon('moneda','CLP','moneda');pon('monto',d.monto||'','monto')}
  else if(ent==='docs'){const prov=d.rut&&S.d.contacts.find(x=>x.rut&&rutN(x.rut)===rutN(d.rut));
    pon('numero',d.folio,'N°');pon('emision',d.fecha,'emisión');if(prov)pon('contraparte',prov.id,'proveedor');
    if(d.monto)pon('neto',Math.round(d.monto/1.19),'neto (calculado del total)')}
  return puestos;
}
/* Escáner en vivo (pedido de Miguel, 20-10-2026): abre la cámara y lee el timbre mientras se apunta, sin sacar foto.
   Con BarcodeDetector (Android) lee el video directo; si no, toma un cuadro cada 300 ms y lo lee con ZXing.
   Sin cámara (o sin permiso) ofrece usar una foto. Devuelve el texto leído, 'foto' si eligió foto, o null. */
let escaneo=null;
function cerrarEscaner(v){if(!escaneo)return;const e=escaneo;escaneo=null;clearTimeout(e.t);e.stream?.getTracks().forEach(x=>x.stop());e.el.remove();e.ok(v)}
async function escanearCodigo(){
  if(!navigator.mediaDevices?.getUserMedia)return 'foto';
  if(escaneo)cerrarEscaner(null);
  return new Promise(async ok=>{
    const el=document.createElement('div');el.className='escaner';el.setAttribute('role','dialog');el.setAttribute('aria-label','Escanear código');
    el.innerHTML=`<div class="esc-caja"><div class="esc-cab"><b>Escanear el código del documento</b><span>Apunta al timbre del SII (el código ancho de abajo de la boleta o factura). Acércate hasta que llene el recuadro, con buena luz.</span></div>
      <div class="esc-video"><video playsinline muted autoplay></video><div class="esc-marco" aria-hidden="true"></div></div>
      <div class="esc-est" aria-live="polite">Abriendo la cámara…</div>
      <div class="bar-actions"><button type="button" class="btn ghost" data-esc="foto">Usar una foto</button><button type="button" class="btn ghost" data-esc="no">Cancelar</button></div></div>`;
    document.body.appendChild(el);escaneo={el,ok,t:0,stream:null};
    el.addEventListener('click',e=>{const b=e.target.closest('[data-esc]');if(b)cerrarEscaner(b.dataset.esc==='foto'?'foto':null)});
    const est=t=>{const x=el.querySelector('.esc-est');if(x)x.textContent=t};
    let stream;
    try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}},audio:false})}
    catch(e){if(escaneo?.el===el)cerrarEscaner('foto');toast(e?.name==='NotAllowedError'?'La cámara no tiene permiso: dáselo en el navegador o usa una foto.':'No se pudo abrir la cámara; usa una foto.',6000);return}
    if(escaneo?.el!==el){stream.getTracks().forEach(x=>x.stop());return}
    escaneo.stream=stream;const v=el.querySelector('video');v.srcObject=stream;try{await v.play()}catch(e){}
    let leer=null;
    if('BarcodeDetector' in window){try{const f=await BarcodeDetector.getSupportedFormats();if(f.includes('pdf417')){const bd=new BarcodeDetector({formats:['pdf417','qr_code'].filter(x=>f.includes(x))});
      leer=async()=>{const r=await bd.detect(v);return (r.find(x=>x.format==='pdf417')||r[0])?.rawValue||null}}}catch(e){}}
    if(!leer){est('Cargando el lector…');
      try{const Z=await cargarZXing(),h=new Map();h.set(Z.DecodeHintType.POSSIBLE_FORMATS,[Z.BarcodeFormat.PDF_417,Z.BarcodeFormat.QR_CODE]);h.set(Z.DecodeHintType.TRY_HARDER,true);
        const mf=new Z.MultiFormatReader();mf.setHints(h);const c=document.createElement('canvas');
        leer=async()=>{if(!v.videoWidth)return null;c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);
          try{return mf.decode(new Z.BinaryBitmap(new Z.HybridBinarizer(new Z.HTMLCanvasElementLuminanceSource(c))),h).getText()}catch(e){return null}}}
      catch(e){if(escaneo?.el===el)cerrarEscaner('foto');toast(`No se pudo cargar el lector (${e.message}); usa una foto.`,6000);return}}
    est('Buscando el código…');
    const vuelta=async()=>{if(escaneo?.el!==el)return;let t=null;try{t=await leer()}catch(e){}
      if(escaneo?.el!==el)return;if(t){navigator.vibrate?.(80);return cerrarEscaner(t)}escaneo.t=setTimeout(vuelta,300)};
    vuelta();
  });
}
document.addEventListener('keydown',e=>{if(escaneo&&e.key==='Escape'){e.stopPropagation();cerrarEscaner(null)}},true);
/* Botón "Escanear código" (data-codigo="ent:id": cámara en vivo, o una foto) y lectura automática al tomar la foto (gastos.js) */
function llenarConCodigo(ent,t,silencioso){
  const d=leerTED(t);
  if(!d){if(!silencioso)toast('Leí un código, pero no es el timbre del SII. Completa los datos a mano o usa «Leer con IA».',6000);return false}
  const p=llenarDesdeTED(ent,d);
  toast(p.length?`El código del documento llenó: ${p.join(', ')}. Revisa antes de guardar.`:'El timbre no traía datos nuevos.',6000);
  return p.length>0;
}
async function leerCodigoYLlenar(ent,src,silencioso){
  let t=null;
  try{t=await leerCodigoDe(src)}catch(e){if(!silencioso)toast(`No se pudo leer el código: ${e.message}`,5000);return false}
  if(!t){if(!silencioso)toast('No encontré un código en la foto. Acércate al timbre (el código ancho de abajo) con buena luz.',6000);return false}
  return llenarConCodigo(ent,t,silencioso);
}
