/* ===== Flujo de caja proyectado y conciliación bancaria ===== */
/* Flujo (Contabilidad → "Flujo de caja"): 8 semanas desde la actual, más lo vencido.
     Entradas: saldo de facturas de venta (por su vencimiento) y estados de pago por cobrar sin factura (en 30 días).
     Salidas: saldo de facturas de proveedor (por su vencimiento), OC aprobadas o compradas sin factura registrada
     (entrega + 30 días, estimado; las de dólar o euro, en pesos al cambio de su fecha) y rendiciones aprobadas por reembolsar (esta semana).
     Saldo inicial: S.caja.saldo (manual) o el saldo de la última línea de la cartola.
   Conciliación (Contabilidad → "Conciliación bancaria"): S.d.cartola con las líneas del banco (pegar o subir un CSV;
   las columnas se reconocen por nombre: fecha, descripción/glosa, cargo, abono, monto, saldo). Para cada abono se
   sugiere la factura de venta con ese saldo, y para cada cargo la de proveedor; al conciliar se registra el pago
   (doc.pagado) y la línea queda "Conciliado". */
const SEM_CAJA=8;
const saldoBanco=()=>{const u=[...S.d.cartola].filter(m=>m.saldo!==''&&m.saldo!=null).sort((a,b)=>a.fecha<b.fecha?1:-1)[0];
  return S.caja&&S.caja.saldo!==''&&S.caja.saldo!=null&&(!u||S.caja.fecha>=u.fecha)?{v:+S.caja.saldo,f:S.caja.fecha,de:'manual'}:u?{v:+u.saldo,f:u.fecha,de:'cartola'}:{v:0,f:'',de:''}};
function flujoCaja(){
  const l0=lunesDe(TODAY),sem=[...Array(SEM_CAJA)].map((_,i)=>addD(l0,i*7)),fin=addD(l0,SEM_CAJA*7);
  const col=d=>!d||d<l0?-1:d>=fin?null:Math.floor(diff(l0,d)/7);
  const filas={cobros:Array(SEM_CAJA+1).fill(0),edp:Array(SEM_CAJA+1).fill(0),pagos:Array(SEM_CAJA+1).fill(0),oc:Array(SEM_CAJA+1).fill(0),rend:Array(SEM_CAJA+1).fill(0)};
  const pon=(k,d,v)=>{const c=col(d);if(c!==null)filas[k][c+1]+=v};
  S.d.docs.forEach(r=>{const s=saldoCLP(r);if(!s)return;pon(r.tipo==='Venta'?'cobros':'pagos',r.vence||TODAY,r.tipo==='Venta'?s:-s)});
  S.d.edps.filter(r=>!r.factura&&(edpListo(r)||['Enviado al cliente','Aprobado por el cliente'].includes(r.estado))).forEach(r=>pon('edp',addD(TODAY,30),Math.round(montoEDP(r)*1.19)));
  // OC por pagar sin factura registrada (la factura ya cuenta en los pagos); las del exterior, en pesos y sin IVA
  S.d.ocs.filter(o=>['Aprobada','Enviada'].includes(o.estado)&&!S.d.docs.some(d=>d.oc===o.id)).forEach(o=>pon('oc',addD(o.entrega||TODAY,30),-(enPesos(o.moneda)?Math.round((+o.neto||0)*1.19):ocCLP(o))));
  S.d.rends.filter(r=>r.estado==='Aprobada').forEach(r=>pon('rend',TODAY,-clpRend(r).real));
  const neto=filas.cobros.map((_,i)=>Object.values(filas).reduce((a,f)=>a+f[i],0));
  const b=saldoBanco();let acc=b.v;const saldo=neto.map(v=>acc+=v);
  return {sem,filas,neto,saldo,banco:b};
}
