/* ---------- Cartola ---------- */
function leerCSV(txt){
  const lineas=String(txt).replace(/\r/g,'').split('\n').filter(l=>l.trim());if(lineas.length<2)return {err:'La cartola debe tener encabezados y al menos una línea.'};
  const sep=[';','\t',','].find(s=>lineas[0].split(s).length>2)||';';
  const celdas=l=>{const out=[];let cur='',q=false;for(const ch of l){if(ch==='"')q=!q;else if(ch===sep&&!q){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out.map(c=>c.trim())};
  const h=celdas(lineas[0]).map(norm),idx=re=>h.findIndex(x=>re.test(x));
  const iF=idx(/fecha/),iD=idx(/descrip|glosa|detalle|concepto/),iC=idx(/cargo|debe|egreso/),iA=idx(/abono|haber|ingreso|deposito/),iM=idx(/monto|importe/),iS=idx(/saldo/);
  if(iF<0||(iM<0&&iC<0&&iA<0))return {err:'No encontré las columnas Fecha y Monto (o Cargo y Abono).'};
  const num=s=>{s=String(s||'').replace(/\$|\s/g,'');if(!s)return 0;if(/,\d{1,2}$/.test(s))s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/[.,](?=\d{3}(\D|$))/g,'');return +s||0};
  const fecha=s=>{const m=/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/.exec(s);if(m)return `${m[3].length===2?'20'+m[3]:m[3]}-${pad(+m[2])}-${pad(+m[1])}`;return isDate(String(s).slice(0,10))?String(s).slice(0,10):''};
  const movs=[];let mal=0;
  lineas.slice(1).forEach(l=>{const c=celdas(l),f=fecha(c[iF]);if(!f){mal++;return}
    const monto=iM>=0?num(c[iM]):num(c[iA])-num(c[iC]);if(!monto){mal++;return}
    movs.push({fecha:f,glosa:iD>=0?c[iD]:'',monto,saldo:iS>=0&&c[iS]!==''?num(c[iS]):''})});
  return {movs,mal};
}
/* Facturas sugeridas: misma dirección (abono → venta, cargo → proveedor) con saldo igual al monto, la de fecha más
   cercana, sin repetir una factura. Se calculan al dibujar (no se guardan): navegar no genera cambios. */
function sugerencias(){
  const usados=new Set(),out=new Map();
  [...S.d.cartola].filter(m=>m.estado==='Pendiente').sort((a,b)=>a.fecha.localeCompare(b.fecha)).forEach(m=>{
    const tipo=m.monto>0?'Venta':'Compra',v=Math.abs(m.monto);
    // En pesos, el saldo exacto; en dólares o euros, el saldo al cambio de ese día con un 3 % de margen
    const calza=d=>enPesos(d.moneda)?docSaldo(d)===v:docSaldo(d)>0&&Math.abs(Math.round(docSaldo(d)*(tasa(d.moneda,m.fecha)||0))-v)<=v*0.03;
    const c=S.d.docs.filter(d=>d.tipo===tipo&&calza(d)&&!usados.has(d.id)).sort((a,b)=>Math.abs(diff(a.vence||a.emision||TODAY,m.fecha))-Math.abs(diff(b.vence||b.emision||TODAY,m.fecha)))[0];
    if(c){usados.add(c.id);out.set(m.id,c)}});
  return out;
}
function conciliarMov(m,docId){
  const d=S.d.docs.find(x=>x.id===docId);if(!d||m.estado!=='Pendiente')return false;
  // Una factura en dólares o euros queda pagada completa y guarda lo que de verdad salió o entró en pesos
  if(enPesos(d.moneda))d.pagado=Math.min(docTotal(d),(+d.pagado||0)+Math.abs(m.monto));
  else{d.pagado=docTotal(d);d.pagadoCLP=(+d.pagadoCLP||0)+Math.abs(m.monto)}
  m.doc=d.id;m.estado='Conciliado';return true;
}
function concView(){
  const ms=[...S.d.cartola].sort((a,b)=>b.fecha.localeCompare(a.fecha)),pend=ms.filter(m=>m.estado==='Pendiente'),edit=lvl('contabilidad')>=3;
  const sg=sugerencias(),suger=pend.filter(m=>sg.has(m.id));
  const fila=m=>{const d=m.doc?S.d.docs.find(x=>x.id===m.doc):sg.get(m.id);
    return `<tr><td class="nw">${fmt(m.fecha)}</td><td>${esc(m.glosa)}</td><td class="r num nw ${m.monto<0?'late':''}">${fmtMoney(m.monto)}</td>
      <td>${m.estado==='Conciliado'?`${tonePill({label:'Conciliado',tone:'done'})} <span class="hint">${esc(ENT.docs.title(d||{}))}</span>`:m.estado==='Ignorado'?tonePill({label:'Ignorado',tone:'todo'}):d?`<span class="hint">Sugerida:</span> ${esc(ENT.docs.title(d))} · ${esc(refName('contacts',d.contraparte))}`:'<span class="hint">Sin factura que calce</span>'}</td>
      <td class="nw">${edit&&m.estado==='Pendiente'?`${d?`<button type="button" class="btn sm" data-conc="${m.id}">Conciliar</button>`:''}<button type="button" class="btn ghost sm" data-concign="${m.id}">Ignorar</button>`:''}</td></tr>`};
  return `<div class="kpis">${kpi('Líneas de cartola',ms.length)}${kpi('Por conciliar',pend.length,pend.length?'bad':'')}${kpi('Con factura sugerida',suger.length)}${kpi('Conciliadas',ms.filter(m=>m.estado==='Conciliado').length)}</div>
  ${edit?`<section class="box"><h2>Cargar cartola</h2><p class="hint">Pega el contenido de la cartola en CSV (o sube el archivo) con columnas como Fecha, Descripción, Cargo, Abono y Saldo. Se reconocen el separador (punto y coma, tab o coma) y los montos chilenos ($1.234.567).</p>
    <textarea id="cartolaTxt" rows="4" placeholder="Fecha;Descripción;Cargo;Abono;Saldo&#10;13-10-2026;Transferencia Cliente B;;2.737.000;15.400.000"></textarea>
    <div class="bar-actions"><button type="button" class="btn" data-act="cargarCartola">Cargar</button><label class="btn ghost">Subir archivo CSV<input type="file" accept=".csv,text/csv,text/plain" id="cartolaFile" hidden></label>${suger.length?`<button type="button" class="btn ghost" data-act="conciliarSugeridas">Conciliar las ${suger.length} sugeridas</button>`:''}</div></section>`:''}
  <div class="tablewrap"><table class="rt"><thead><tr><th>Fecha</th><th>Descripción</th><th class="r">Monto</th><th>Factura</th><th></th></tr></thead><tbody>
  ${ms.map(fila).join('')||`<tr><td colspan="5">${empty('Aún no se ha cargado una cartola.')}</td></tr>`}</tbody></table></div>`;
}
function cargarCartola(txt){
  if(lvl('contabilidad')<3)return;const r=leerCSV(txt);if(r.err)return toast(r.err);
  let nuevos=0;r.movs.forEach(m=>{if(S.d.cartola.some(x=>x.fecha===m.fecha&&x.monto===m.monto&&x.glosa===m.glosa))return;S.d.cartola.push(Object.assign({id:uid(),estado:'Pendiente',doc:''},m));nuevos++});
  addLog(`${meName()} cargó una cartola: ${nuevos} línea${nuevos===1?'':'s'} nueva${nuevos===1?'':'s'}`);commit();
  toast(`${nuevos} línea${nuevos===1?'':'s'} cargada${nuevos===1?'':'s'}${r.mal?` · ${r.mal} sin fecha o monto`:''}${r.movs.length-nuevos?` · ${r.movs.length-nuevos} repetida${r.movs.length-nuevos===1?'':'s'}`:''}`);
}
