/* ===== Centros de costo, UF y dólar ===== */
/* Centros de costo (ENT.centros), uno por área de la empresa. Todo gasto queda imputado: las OC, facturas de
   proveedor y rendiciones sin proyecto se imputan solas al centro del área de quien las pide (imputar).
   UF, dólar y euro (ENT.indicadores) se ingresan a mano por fecha; tasa(moneda, fecha) da los pesos por unidad con
   el último valor a esa fecha. Se usan para llevar a CLP el gasto por centro y como tipo de cambio por defecto en el
   costeo de importación. La carga automática desde una fuente oficial queda para la Fase D (24b). */
function tasa(mon,fecha){
  if(!mon||mon==='CLP')return 1;const k={UF:'uf',USD:'dolar',EUR:'euro'}[mon];if(!k)return null;
  const l=S.d.indicadores.filter(x=>+x[k]>0&&(!fecha||x.fecha<=fecha)).sort((a,b)=>a.fecha<b.fecha?1:-1);
  const v=(l[0]||S.d.indicadores.filter(x=>+x[k]>0).sort((a,b)=>a.fecha<b.fecha?-1:1)[0]);return v?+v[k]:null;
}
const aCLP=(monto,mon,fecha)=>{const t=tasa(mon,fecha);return t==null?null:Math.round((+monto||0)*t)};
/* Imputa el gasto al centro del área de quien lo pide, si no tiene proyecto ni centro */
function imputar(ent,r){
  if(r.proyecto||r.centro||(ent==='docs'&&r.tipo!=='Compra'))return;
  const a=person(ent==='rends'?r.persona:r.solicitante||S.me)?.area,act=S.d.centros.filter(c=>c.activo!=='No');
  const c=act.find(x=>x.area===a)||act.find(x=>x.area==='Administración')||act[0];if(c)r.centro=c.id;
}
/* Gasto por proyecto y centro de costo, en CLP */
function gastoPorCentro(){
  const filas=[...S.projects.map(p=>{const c=p.centro&&S.d.centros.find(y=>y.id===p.centro);return {id:p.id,nombre:nombreProy(p),tipo:'Proyecto'+(c?' · '+(c.codigo||c.nombre):''),k:'proyecto'}}),...S.d.centros.map(c=>({id:c.id,nombre:`${c.codigo?c.codigo+' · ':''}${c.nombre}`,tipo:'Centro de costo',k:'centro'}))];
  let sinTasa=0;const conv=(m,mon,f)=>{const v=aCLP(m,mon,f);if(v==null){sinTasa++;return 0}return v};
  return {sinTasa,filas:filas.map(x=>{const de=r=>r[x.k]===x.id;
    const oc=sum(S.d.ocs.filter(o=>de(o)&&['Aprobada','Enviada'].includes(o.estado)),o=>conv(o.neto,o.moneda,o.fecha));
    const fac=sum(S.d.docs.filter(d=>d.tipo==='Compra'&&de(d)),d=>clpDoc(d).real);
    const ren=sum(S.d.rends.filter(r=>de(r)&&GASTO_OK.includes(r.estado)),r=>r.monto);
    const mat=x.k==='proyecto'?S.d.moves.filter(m=>m.proyecto===x.id&&m.tipo==='Salida').reduce((a,m)=>{const p=S.d.products.find(y=>y.id===m.producto);return a+(+m.cantidad||0)*(+p?.costo||0)},0):0;
    return Object.assign(x,{oc,fac,ren,mat,total:fac+ren+mat})}).filter(x=>x.oc||x.total||x.tipo==='Centro de costo')};
}
function centrosView(){
  const g=gastoPorCentro(),td=v=>`<td class="r num nw">${v?fmtMoney(v):'<span class="hint">—</span>'}</td>`;
  return `<p class="hint">Gasto real (facturas de proveedor, rendiciones aprobadas y materiales de bodega) y comprometido (OC aprobadas o compradas, convertidas a pesos con la UF, el dólar o el euro del día de la OC) por proyecto y centro de costo. Los gastos sin proyecto se imputan al centro de costo del área de quien los pide.</p>
  ${g.sinTasa?`<p class="warn">${g.sinTasa} monto${g.sinTasa===1?'':'s'} en moneda extranjera sin valor de UF, dólar o euro: ingrésalo en la pestaña «UF y dólar».</p>`:''}
  <div class="tablewrap"><table class="rt"><thead><tr><th>Proyecto o centro</th><th>Tipo</th><th class="r">OC comprometidas</th><th class="r">Facturas proveedor</th><th class="r">Rendiciones</th><th class="r">Materiales</th><th class="r">Gasto real</th></tr></thead><tbody>
  ${g.filas.map(x=>`<tr ${x.k==='proyecto'?`data-proj="${x.id}"`:`data-rec="centros:${x.id}:contabilidad"`} tabindex="0"><td class="nm">${esc(x.nombre)}</td><td>${x.tipo}</td>${td(x.oc)}${td(x.fac)}${td(x.ren)}${td(x.mat)}<td class="r num nw"><b>${fmtMoney(x.total)}</b></td></tr>`).join('')}</tbody></table></div>`;
}
/* ---------- UF, dólar y euro automáticos (24b): mindicador.cl, gratis y sin cuenta ----------
   Se puede consultar directo desde la página (permite otros orígenes). Trae los valores del día y los guarda en
   «UF y dólar» (crea o completa la fila de esa fecha). Quien puede crear valores lo hace con el botón; la versión
   conectada lo hace sola al abrir la app si falta el día. En la app de claude.ai no funciona: bloquea conexiones. */
const MINDICADOR='https://mindicador.cl/api';
let indLeyendo=null;   // las pruebas esperan la consulta
async function traerIndicadores(silencioso){
  if(!canCreate('indicadores','contabilidad')){if(!silencioso)toast('Tu rol no permite cargar la UF y el dólar');return}
  try{
    const r=await fetch(MINDICADOR);if(!r.ok)throw new Error('respondió '+r.status);const j=await r.json();
    const fecha=String(j.uf?.fecha||j.fecha||'').slice(0,10)||TODAY,v=k=>+(j[k]?.valor)||'';
    const x=S.d.indicadores.find(i=>i.fecha===fecha);
    if(x&&+x.uf===+v('uf')&&+x.dolar===+v('dolar')&&+x.euro===+v('euro')){if(!silencioso)toast(`Los valores del ${fmt(fecha)} ya estaban al día`);return}
    if(x)Object.assign(x,{uf:v('uf'),dolar:v('dolar'),euro:v('euro')});else S.d.indicadores.push({id:uid(),fecha,uf:v('uf'),dolar:v('dolar'),euro:v('euro')});
    addLog(`Se cargaron la UF (${fmtMoney(v('uf'))}), el dólar (${fmtMoney(v('dolar'))}) y el euro del ${fmt(fecha)} desde mindicador.cl`);commit();
    if(!silencioso)toast(`UF ${fmtMoney(v('uf'))} · dólar ${fmtMoney(v('dolar'))} · euro ${fmtMoney(v('euro'))} (${fmt(fecha)})`);
  }catch(e){if(!silencioso)toast('No se pudo consultar mindicador.cl: '+(e.message||e)+'. Revisa tu conexión o ingrésalos a mano.')}
}
document.addEventListener('click',e=>{if(e.target.closest('[data-indauto]'))indLeyendo=traerIndicadores(false)});

