function leerChecklist(txt){
  const out=[];let err='';txt.split('\n').map(l=>l.trim()).filter(Boolean).forEach(l=>{const [t,r]=l.split(';').map(x=>(x||'').trim());
    const rol=S.roles.find(x=>norm(x.name)===norm(r||''));if(!t)return;if(!rol){err=err||`No hay un rol llamado «${r||''}»`;return}out.push({texto:t,rol:rol.id})});
  return {out,err};
}
