/* ===== Capacitaciones, matriz de competencias y evaluación de desempeño ===== */
/* - ENT.cursos (catálogo, con vigencia en meses y el tipo de trabajo que habilita; vacío = curso general).
   - ENT.capacitaciones (persona, curso, fecha; vence = fecha + vigencia, si no se indica). Dueño = la persona.
   - ENT.trabajos (tipos de trabajo). Una persona está habilitada para un trabajo si tiene vigentes todas las
     capacitaciones de los cursos de ese trabajo (amarillo si alguna vence en 30 días).
   - ENT.evaluaciones: 5 criterios de 1 a 5 con pesos (EVAL_CRIT); puntaje 0 a 100; bono = base × % del tramo
     (BONO_TRAMOS). Propuesta inicial: no estaba la herramienta anterior de evaluación de técnicos; se ajusta aquí. */
function puntajeEval(r){if(!EVAL_CRIT.every(([k])=>+r[k]>=1))return null;return Math.round(EVAL_CRIT.reduce((a,[k,,w])=>a+w*(+r[k]-1)/4,0))}
const pctBono=p=>p==null?0:BONO_TRAMOS.find(([m])=>p>=m)[1];
const bonoEval=r=>Math.round((+r.base||0)*pctBono(puntajeEval(r))/100);
function capSt(c){if(!c)return {label:'Falta',tone:'stuck'};if(!c.vence)return {label:'Vigente',tone:'done'};const d=diff(TODAY,c.vence);
  return d<0?{label:'Vencida',tone:'stuck'}:d<=30?{label:'Por vencer',tone:'prog'}:{label:'Vigente',tone:'done'}}
/* La capacitación más reciente de una persona en un curso */
const capDe=(pid,cid)=>S.d.capacitaciones.filter(c=>c.persona===pid&&c.curso===cid).sort((a,b)=>(b.fecha||'').localeCompare(a.fecha||''))[0];
function habilitacion(pid,tb){
  const cs=S.d.cursos.filter(c=>c.trabajo===tb.id);if(!cs.length)return {tone:'todo',label:'Sin cursos',ok:0,n:0};
  const st=cs.map(c=>capSt(capDe(pid,c.id)).tone),ok=st.filter(t=>t!=='stuck').length;
  return st.includes('stuck')?{tone:'stuck',label:'No habilitado',ok,n:cs.length}:st.includes('prog')?{tone:'prog',label:'Habilitado (por vencer)',ok,n:cs.length}:{tone:'done',label:'Habilitado',ok,n:cs.length};
}
function competenciasView(mod){
  const ppl=S.people.filter(p=>p.estado!=='Inactivo'&&canSee('people',p,mod||'rrhh')),tbs=S.d.trabajos;
  if(!tbs.length)return `<section class="box">${empty('Define los tipos de trabajo y sus cursos en las pestañas «Tipos de trabajo» y «Cursos».')}</section>`;
  const gen=S.d.cursos.filter(c=>!c.trabajo);
  return `<p class="hint">Habilitado: tiene vigentes todos los cursos de ese tipo de trabajo. Amarillo: alguno vence en 30 días. Rojo: falta o venció alguno. Clic en una celda para ver qué falta.</p>
  <div class="tablewrap"><table class="rt semt"><thead><tr><th>Colaborador</th>${tbs.map(t=>`<th>${esc(t.nombre)}</th>`).join('')}${gen.length?'<th>Cursos generales</th>':''}</tr></thead><tbody>
  ${ppl.map(p=>`<tr><td class="nm"><span class="who">${av(p.id)}<span>${esc(p.name)}<br><span class="hint">${esc(p.role||'')}</span></span></span></td>
    ${tbs.map(t=>{const h=habilitacion(p.id,t);return `<td><span title="${esc(S.d.cursos.filter(c=>c.trabajo===t.id).map(c=>`${c.nombre}: ${capSt(capDe(p.id,c.id)).label}`).join(' · '))}">${semCelda(h)}</span></td>`}).join('')}
    ${gen.length?`<td>${(()=>{const ok=gen.filter(c=>capSt(capDe(p.id,c.id)).tone!=='stuck').length;return tonePill({label:`${ok} de ${gen.length}`,tone:ok===gen.length?'done':'stuck'})})()}</td>`:''}</tr>`).join('')}</tbody></table></div>`;
}
/* Para el portal: lo propio */
function misCompetencias(){
  const caps=S.d.cursos.map(c=>({c,x:capDe(S.me,c.id)})).filter(o=>o.x),evs=S.d.evaluaciones.filter(e=>e.persona===S.me).sort((a,b)=>(b.periodo||'').localeCompare(a.periodo||''));
  return `<div class="g2"><section class="box"><h2>Mis capacitaciones</h2>${caps.map(({c,x})=>`<div class="appr"><span class="modtag">Curso</span><span class="tt" data-rec="capacitaciones:${x.id}"><span class="tname">${esc(c.nombre)}</span><span class="hint">${fmt(x.fecha)}${x.vence?` · vence ${fmt(x.vence)}`:''}</span></span>${tonePill(capSt(x))}</div>`).join('')||empty('Aún no tienes capacitaciones registradas.')}
    ${S.d.trabajos.length?`<h3>Habilitaciones</h3>${S.d.trabajos.map(t=>`<div class="appr"><span class="modtag">Trabajo</span><span class="tt"><span class="tname">${esc(t.nombre)}</span></span>${semCelda(habilitacion(S.me,t))}</div>`).join('')}`:''}</section>
  <section class="box"><h2>Mis evaluaciones</h2>${evs.map(e=>`<div class="appr"><span class="modtag">${esc(e.periodo)}</span><span class="tt" data-rec="evaluaciones:${e.id}"><span class="tname">${puntajeEval(e)??'—'} puntos</span><span class="hint">Bono ${fmtMoney(bonoEval(e))}</span></span></div>`).join('')||empty('Aún no tienes evaluaciones.')}</section></div>`;
}

/* ===== Panel gerencial que cruza las áreas ===== */
/* Menú "Panel gerencial" (administrador, o quien ve Proyectos y Contabilidad). Junta, con las mismas funciones de
   cada área: margen por proyecto (projFin y presupuestoDe), gasto contra presupuesto, días de respuesta de compras
   (OC de los últimos 90 días: solicitud → aprobación y → compra), personal acreditado (semaforo) y habilitado
   (habilitacion), y saldo de caja proyectado (flujoCaja). Una medida por gráfico; barras de una sola serie.
   Valores negativos en rojo y con etiqueta (no solo color). */
const verGerencia=()=>isAdmin()||(lvl('proyectos')>=2&&lvl('contabilidad')>=2);
/* Barras horizontales de una serie: [{n, v, txt, sub}]. tono(x) da el color: un tono del semáforo (done, prog,
   stuck, todo) o un color #hex, como el de la etiqueta de un estado; sin tono, el color de siempre */
function barras(items,fmtv,tono){
  const max=Math.max(1,...items.map(x=>Math.abs(x.v)));
  const fondo=x=>{const t=tono&&tono(x);return t?`;background:${t[0]==='#'?t:`var(--s-${t})`}`:''};
  return `<div class="kbars">${items.map(x=>`<div class="kbar" title="${esc(x.n)}: ${esc(fmtv(x.v))}${x.sub?' · '+esc(x.sub):''}"><span class="kbn">${esc(x.n)}</span>
    <span class="kbt"><span class="kbf ${x.v<0?'neg':''}" style="width:${Math.max(1,Math.round(Math.abs(x.v)/max*100))}%${fondo(x)}"></span></span><span class="kbv ${x.v<0?'late':''}">${esc(fmtv(x.v))}${x.v<0?' (pérdida)':''}</span></div>`).join('')}</div>`;
}
function respuestaCompras(){
  const ocs=S.d.ocs.filter(o=>o.fecha&&diff(o.fecha,TODAY)<=90);
  const prom=(f)=>{const ds=ocs.filter(o=>o[f]).map(o=>Math.max(0,diff(o.fecha,o[f])));return ds.length?Math.round(ds.reduce((a,b)=>a+b,0)/ds.length*10)/10:null};
  return {aprob:prom('f_aprob'),compra:prom('f_envio'),n:ocs.length,pend:S.d.ocs.filter(o=>o.estado==='Por aprobar')};
}
function personalAcreditado(){
  const cls=clientesAcc(),ppl=accPeople();if(!cls.length||!ppl.length)return {pct:null,porCliente:[]};
  const porCliente=cls.map(c=>{const rs=reqsDe(c.id),ok=ppl.filter(p=>semaforo(p.id,rs).tone!=='stuck').length;return {n:c.nombre,v:Math.round(ok/ppl.length*100),sub:`${ok} de ${ppl.length} personas`}});
  const pares=cls.length*ppl.length,ok=cls.reduce((a,c)=>a+ppl.filter(p=>semaforo(p.id,reqsDe(c.id)).tone!=='stuck').length,0);
  return {pct:Math.round(ok/pares*100),porCliente};
}
// Resumen fijo (la primera pestaña del panel gerencial, para quien ve Proyectos y Contabilidad); los paneles por comité
// están en comites.js
function resumenGerencia(){
  const pr=S.projects.filter(p=>p.status!=='cerrado').map(p=>({p,f:projFin(p.id),x:presupuestoDe(p)}));
  const margen=sum(pr,o=>o.f.margen),est=pr.filter(o=>o.x.margen!=null),rc=respuestaCompras(),ac=personalAcreditado(),fc=flujoCaja();
  const conPres=pr.filter(o=>o.x.pres),fin=fc.saldo[fc.saldo.length-1],minS=Math.min(...fc.saldo);
  const hab=S.d.trabajos.length?(()=>{const ppl=accPeople(),t=S.d.trabajos.length*ppl.length;return t?Math.round(ppl.reduce((a,p)=>a+S.d.trabajos.filter(tb=>habilitacion(p.id,tb).tone!=='stuck').length,0)/t*100):null})():null;
  const venc=S.d.docs.filter(d=>d.tipo==='Venta'&&docSt(d).label==='Vencida');
  return `<p class="hint">Resumen de las áreas con los mismos cálculos de cada una. Solo se suman montos en pesos; los proyectos cerrados no se incluyen.</p>
  <div class="kpis">${kpi('Margen de proyectos activos',fmtMoney(margen),'money'+(margen<0?' bad':''),'Ventas menos costos registrados')}
    ${kpi('Margen estimado al término',est.length?fmtMoney(sum(est,o=>o.x.margen)):'—','money'+(sum(est,o=>o.x.margen)<0?' bad':''),`${est.length} proyecto${est.length===1?'':'s'} con contrato o ventas`)}
    ${kpi('Respuesta de compras',rc.compra==null?'—':`${String(rc.compra).replace('.',',')} días`,'',`De la solicitud a la compra · aprobación en ${rc.aprob==null?'—':String(rc.aprob).replace('.',',')} días`)}
    ${kpi('Personal acreditado',ac.pct==null?'—':`${ac.pct}%`,ac.pct!=null&&ac.pct<80?'bad':'','Puede ingresar donde cada cliente lo exige')}
    ${kpi('Caja en 8 semanas',fmtMoney(fin),'money'+(minS<0?' bad':''),minS<0?'Queda negativa en algún momento':`Hoy ${fmtMoney(fc.banco.v)}`)}</div>
  <div class="g2"><section class="box"><h2>Margen estimado al término por proyecto</h2>${est.length?barras(est.map(o=>({n:o.p.name,v:o.x.margen,sub:`contrato ${fmtMoney(o.x.contrato)}`})),fmtMoney,x=>x.v<0?'stuck':'done'):empty('Ningún proyecto tiene contrato ni ventas.')}</section>
    ${fnOn('presupuesto')?`<section class="box"><h2>Gasto contra presupuesto</h2>${conPres.length?`<div class="tablewrap"><table class="rt compacta"><thead><tr><th>Proyecto</th><th class="r">Gastado</th><th class="r">Avance</th><th>Estado</th></tr></thead><tbody>
      ${conPres.map(o=>`<tr data-proj="${o.p.id}" tabindex="0"><td class="nm">${esc(o.p.name)}</td><td class="r num">${pct(o.x.fin)}</td><td class="r num">${pct(o.x.fis)}</td><td>${tonePill(presEstado(o.x))}</td></tr>`).join('')}</tbody></table></div>`:empty('Ningún proyecto tiene presupuesto.')}</section>`:''}</div>
  <div class="g2"><section class="box"><h2>Personal que puede ingresar, por cliente</h2>${ac.porCliente.length?barras(ac.porCliente,v=>`${v}%`,x=>x.v>=80?'done':x.v>=50?'prog':'stuck'):empty('No hay requisitos de acreditación.')}
      ${hab!=null?`<p class="hint">Habilitados para sus tipos de trabajo: <b>${hab}%</b> de las combinaciones persona × trabajo.</p>`:''}</section>
    <section class="box"><h2>Saldo de caja proyectado</h2>${barras(fc.saldo.map((v,i)=>({n:i===0?'Con lo vencido':i===1?'Esta semana':`Sem. ${fmtShort(fc.sem[i-1])}`,v})),fmtMoney,x=>x.v<0?'stuck':x.v<fc.banco.v?'prog':'done')}</section></div>
  <section class="box"><h2>Pendientes que conviene mirar</h2><div class="kpis">
    ${kpi('OC por aprobar',rc.pend.length,rc.pend.length?'bad':'',fmtMoney(sum(rc.pend.filter(o=>o.moneda==='CLP'),o=>o.neto)))}
    ${kpi('Cobros vencidos',venc.length,venc.length?'bad':'',fmtMoney(sum(venc,saldoCLP)))}
    ${kpi('Estados de pago listos para cobrar',S.d.edps.filter(edpListo).length,'',fmtMoney(sum(S.d.edps.filter(edpListo),montoEDP)))}
    ${kpi('Mantenciones atrasadas',S.d.mants.filter(m=>m.estado==='Programada'&&mantSt(m).tone==='stuck').length)}
    ${kpi('Sobrecargas esta semana',sobrecargas().filter(x=>x.semana===lunesDe(TODAY)).length)}</div></section>`;
}
