document.addEventListener('keydown',e=>{if(!PRES)return;
  if(e.key==='Escape'){e.preventDefault();e.stopPropagation();return cerrarPres()}
  const d=['ArrowRight','PageDown',' '].includes(e.key)?1:['ArrowLeft','PageUp'].includes(e.key)?-1:0;
  if(d){e.preventDefault();PRES.i=Math.max(0,Math.min(PRES.n-1,PRES.i+d));pintarPres()}},true);
document.addEventListener('fullscreenchange',()=>{if(PRES&&!document.fullscreenElement&&$('presenta')){/* salir de pantalla completa no cierra la presentación */}});

