// Monto en palabras («un millón cuatrocientos ochenta y ocho mil cuarenta y cuatro pesos»)
function enLetras(n){
  n=Math.floor(Math.abs(+n||0));if(!n)return 'cero';
  const U=['','uno','dos','tres','cuatro','cinco','seis','siete','ocho','nueve','diez','once','doce','trece','catorce','quince','dieciséis','diecisiete','dieciocho','diecinueve','veinte','veintiuno','veintidós','veintitrés','veinticuatro','veinticinco','veintiséis','veintisiete','veintiocho','veintinueve'];
  const D=['','','','treinta','cuarenta','cincuenta','sesenta','setenta','ochenta','noventa'],C=['','ciento','doscientos','trescientos','cuatrocientos','quinientos','seiscientos','setecientos','ochocientos','novecientos'];
  const hasta999=x=>{if(x===100)return 'cien';const c=Math.floor(x/100),r=x%100;const dec=r<30?U[r]:D[Math.floor(r/10)]+(r%10?' y '+U[r%10]:'');return [C[c],dec].filter(Boolean).join(' ')};
  const corto=t=>t.replace(/veintiuno$/,'veintiún').replace(/uno$/,'un');   // «veintiún mil», «un millón»
  const mill=Math.floor(n/1e6),miles=Math.floor(n%1e6/1000),resto=n%1000,partes=[];
  if(mill)partes.push(mill===1?'un millón':corto(hasta999(mill>999?999:mill))+' millones');
  if(miles)partes.push(miles===1?'mil':corto(hasta999(miles))+' mil');
  if(resto)partes.push(hasta999(resto));
  return partes.join(' ');
}
