/* ===== Remuneraciones, segunda parte (paso 2, tanda E, 11-11-2026) =====
   - Anticipos y préstamos (función a elección «prestamos»; ENT.prestamos, Personas → «Anticipos y préstamos»; en la base
     prestamo): monto, cuotas y mes del primer descuento. Cada liquidación del mes descuenta sola la cuota que toca
     (`cuotasDe`, usada por `calcPersona`); lo pagado se cuenta en las liquidaciones aprobadas.
   - Boletas de honorarios (función a elección «honorarios»; ENT.honorarios, Personas → «Honorarios»; en la base
     boleta_honorarios): bruto, retención del año (`RETENCION_HON`) y líquido.
   - Finiquitos (ENT.finiquitos, Personas → «Finiquitos»; en la base finiquito): causal, años de servicio, indemnización
     por años de servicio y aviso previo (solo art. 161, con tope de 11 años y 90 UF), vacaciones proporcionales en días
     corridos, remuneración pendiente y descuentos; documento para firmar ante ministro de fe.
   - Asiento contable de remuneraciones (Contabilidad → «Remuneraciones»): debe y haber del mes con las liquidaciones
     aprobadas y las boletas de honorarios, y la distribución del gasto por proyecto (horas de sus tareas del mes) o por
     el centro de costo del área de cada persona; se descarga en CSV.
   Los cálculos son de referencia: RRHH y el contador los revisan antes de pagar. */
const RETENCION_HON={2024:13.75,2025:14.5,2026:15.25,2027:16,2028:17};
const retencionHon=f=>{const y=+String(f||TODAY).slice(0,4);return RETENCION_HON[y]??(y<2024?13:17)};
const mesesEntre=(a,b)=>(+b.slice(0,4)-+a.slice(0,4))*12+(+b.slice(5,7)-+a.slice(5,7));

/* ---------- Anticipos y préstamos ---------- */
function cuotaN(pr,k){const n=Math.max(1,+pr.cuotas||1),m=+pr.monto||0,base=Math.floor(m/n);return k<n-1?base:m-base*(n-1)}
function cuotasDe(pid,per){
  if(!fnOn('prestamos'))return [];
  return (S.d.prestamos||[]).filter(x=>x.persona===pid&&x.estado!=='Anulado'&&x.desde&&+x.monto>0).map(x=>{const k=mesesEntre(x.desde,per),n=Math.max(1,+x.cuotas||1);
    return k>=0&&k<n?{n:n>1?`${x.tipo||'Préstamo'} (cuota ${k+1} de ${n})`:(x.tipo||'Anticipo'),v:cuotaN(x,k),prest:x.id}:null}).filter(Boolean);
}
const pagadoPrestamo=pr=>S.d.liquidaciones.filter(l=>liqAprobada(l)&&l.calc).reduce((a,l)=>a+(l.calc.otros||[]).filter(o=>o.prest===pr.id).reduce((b,o)=>b+o.v,0),0);
const saldoPrestamo=pr=>pr.estado==='Anulado'?0:Math.max(0,(+pr.monto||0)-pagadoPrestamo(pr));
const estadoPrestamo=pr=>pr.estado==='Anulado'?{label:'Anulado',tone:'todo'}:saldoPrestamo(pr)<=0?{label:'Pagado',tone:'done'}:{label:'Vigente',tone:'prog'};

/* ---------- Finiquitos ---------- */
// CAUSALES (causales de término) está en constantes.js: ENT.finiquitos la usa al cargar
const esArt161=c=>/^Art\. 161/.test(c||'');
function finiquitoCalc(f){
  const p=person(f.persona)||{},R=p.rem||{},fin=f.fecha||TODAY,per=fin.slice(0,7),I=indRemDe(per);
  const fijosImp=(R.otros||[]).filter(x=>x.imp).reduce((a,x)=>a+(+x.v||0),0),fijosNo=(R.otros||[]).filter(x=>!x.imp).reduce((a,x)=>a+(+x.v||0),0);
  const sueldo=p.rem?sueldoBaseDe(p,per):0;
  const grati=R.grati==='no'?0:Math.min(Math.round((sueldo+fijosImp)*.25),gratiTope(I));
  // Última remuneración mensual (art. 172): lo fijo y regular, sin horas extra ni asignación familiar; tope 90 UF
  const ultima=sueldo+fijosImp+grati+(+R.colacion||0)+(+R.movilizacion||0)+fijosNo,tope=Math.round(90*I.uf),base=Math.min(ultima,tope);
  let anios=0;if(p.ingreso){const m=monthsBetween(p.ingreso,fin);anios=Math.floor(m/12)+(m%12>6?1:0)}
  const aniosTope=Math.min(anios,11),art161=esArt161(f.causal);
  const ias=art161?aniosTope*base:0,aviso=art161&&f.avisoDado!=='Sí'?base:0;
  // Vacaciones proporcionales: el saldo en días hábiles se cuenta desde el día siguiente al término, sumando sábados, domingos y feriados
  const habiles=Math.max(0,+(f.diasVac!==''&&f.diasVac!=null?f.diasVac:(vacSaldo(p)??0))||0);let corridos=0,cuenta=0,d=fin;
  if(habiles>0){const enteros=Math.floor(habiles);while(cuenta<enteros){d=addD(d,1);corridos++;if(esHabil(d))cuenta++}corridos+=habiles-enteros}
  corridos=Math.round(corridos*100)/100;
  const vac=Math.round((sueldo+fijosImp)/30*corridos);
  const prest=(S.d.prestamos||[]).filter(x=>x.persona===f.persona).reduce((a,x)=>a+saldoPrestamo(x),0);
  const pend=+f.remPendiente||0,otrosH=+f.otrosHaberes||0,desc=(+f.descuentos||0)+prest;
  return {ultima,tope,base,anios,aniosTope,art161,ias,aviso,habiles,corridos,vac,pend,otrosH,prest,desc,total:pend+ias+aviso+vac+otrosH-desc,uf:I.uf};
}
