// Horas de cada proyecto en las tareas de la persona que caen en el mes (por días hábiles); sin tareas, todo al centro de su área
function repartoPersona(pid,per){
  const a=per+'-01',b=addD(addM(a,1),-1),hs={};
  S.tasks.filter(t=>t.ownerId===pid&&t.projectId&&(t.start||t.due)).forEach(t=>{const i=t.start||t.due,f=t.due||t.start;if(f<a||i>b)return;
    let tot=0,en=0;for(let d=i;d<=f;d=addD(d,1)){if(!esHabil(d))continue;tot++;if(d>=a&&d<=b)en++}if(!tot)return;hs[t.projectId]=(hs[t.projectId]||0)+horasTarea(t)*en/tot});
  const tot=Object.values(hs).reduce((x,y)=>x+y,0);
  if(!tot){const p=person(pid),c=S.d.centros.find(z=>z.area===p?.area&&z.activo!=='No');return [{k:c?'c:'+c.id:'sin',f:1}]}
  return Object.entries(hs).map(([k,h])=>({k:'p:'+k,f:h/tot}));
}
const nombreImputa=k=>k==='sin'?'Sin centro de costo':k.startsWith('p:')?nombreProy(proj(k.slice(2))||{name:'Proyecto'}):(()=>{const c=S.d.centros.find(z=>z.id===k.slice(2));return c?`${c.codigo?c.codigo+' · ':''}${c.nombre}`:'Centro'})();
function asientoMes(per){
  const ls=S.d.liquidaciones.filter(l=>l.periodo===per&&liqAprobada(l)&&l.calc),hon=(S.d.honorarios||[]).filter(h=>String(h.fecha||'').slice(0,7)===per);
  const s=f=>ls.reduce((a,l)=>a+(+f(l.calc)||0),0);
  const prest=s(c=>(c.otros||[]).filter(o=>o.prest).reduce((a,o)=>a+o.v,0)),otrosD=s(c=>(c.otros||[]).filter(o=>!o.prest).reduce((a,o)=>a+o.v,0));
  const honB=hon.reduce((a,h)=>a+(+h.bruto||0),0),honR=hon.reduce((a,h)=>a+Math.round((+h.bruto||0)*retencionHon(h.fecha)/100),0);
  const debe=[['Remuneraciones (gasto)',s(c=>c.haberes)],['Aportes del empleador: cesantía, SIS, mutual y reforma (gasto)',s(c=>c.aportes.total)],['Honorarios (gasto)',honB]];
  const haber=[['AFP por pagar (trabajador, SIS y aporte de la reforma)',s(c=>c.afp+c.aportes.sis+c.aportes.reforma)],['Salud por pagar',s(c=>c.salud)],['Seguro de cesantía por pagar',s(c=>c.afcTrab+c.aportes.afc)],
    ['Mutual de seguridad por pagar',s(c=>c.aportes.mutual)],['Impuesto único por pagar',s(c=>c.impuesto)],['Anticipos y préstamos al personal (rebaja)',prest],['Otros descuentos por pagar',otrosD],
    ['Remuneraciones por pagar (líquido)',s(c=>c.liquido)],['Retención de honorarios por pagar',honR],['Honorarios por pagar (líquido)',honB-honR]];
  const dist={};ls.forEach(l=>{const costo=l.calc.haberes+l.calc.aportes.total;repartoPersona(l.persona,per).forEach(r=>{dist[r.k]=(dist[r.k]||0)+costo*r.f})});
  hon.forEach(h=>{const k=h.proyecto?'p:'+h.proyecto:h.centro?'c:'+h.centro:'sin';dist[k]=(dist[k]||0)+(+h.bruto||0)});
  return {ls,hon,debe:debe.filter(x=>x[1]),haber:haber.filter(x=>x[1]),dist:Object.entries(dist).map(([k,v])=>({k,n:nombreImputa(k),v:Math.round(v)})).sort((a,b)=>b.v-a.v)};
}
