/* ===== Modo terreno: formularios con firma, fotos con ubicación e indicador de conexión ===== */
/* Hoy la app guarda todo en el teléfono y funciona sin señal; con servidor, los cambios se sincronizan al volver la
   señal (función 9). Formularios de terreno (ENT.formularios, menú "Terreno"): charla de 5 minutos, ATS, entrega de EPP,
   revisión de herramientas y de vehículo. Dueño = autor; "Solo lo suyo" llena los suyos y los corrige el mismo día.
   Tanda de formularios (11-11-2026, decisiones de Miguel del 10-11-2026):
   - Participantes elegidos de la lista del personal (más externos) y firma de cada uno.
   - Cada «No» pide una foto y ofrece crear una observación de obra o reportar un incidente al guardar.
   - Las listas de cada formulario y los temas de la charla las cambian el administrador y los encargados de prevención
     (S.d.formListas; en la base formulario_lista y empresa.prevencion). Cada formulario guarda la lista con que se llenó.
   - Charla: expositor, hora, duración, riesgos de la matriz y temas sugeridos.
   - ATS: tabla por paso (paso, riesgo, control), permisos especiales, EPP requerido y «Detener el trabajo».
   - Herramientas: las herramientas revisadas y el color del mes (opcional). No se eligen de Activos.
   - Vehículo: desde Activos, con sus documentos, kilometraje, conductor y licencia, fotos de daños y la falla, que puede
     crear la mantención correctiva.
   - EPP: trabajador, y por elemento talla, cantidad, nuevo o reposición, vida útil y salida de bodega; firma el trabajador.
   Lo propio de cada tipo va en f.det (en la base formulario_terreno.detalle). */
const FORMS={
  charla:{n:FORM_TIPOS.charla,items:['Se explicó el tema de la charla','Se revisaron los riesgos del día','Se resolvieron las dudas del equipo'],tema:1,
    temas:['Trabajo en altura','Riesgo eléctrico y bloqueo','Manejo manual de carga','Orden y aseo','Radiación UV','Uso correcto del EPP','Conducción a la defensiva','Herramientas manuales y eléctricas','Fatiga y somnolencia','Plan de emergencia']},
  ats:{n:FORM_TIPOS.ats,items:['Se identificaron los peligros de la tarea','Se definieron las medidas de control','El área está señalizada y aislada','Hay permiso de trabajo (si aplica)','Todos conocen el plan de emergencia'],tema:1},
  epp:{n:FORM_TIPOS.epp,items:['Casco','Lentes de seguridad','Guantes','Zapatos de seguridad','Arnés (trabajo en altura)','Protector auditivo'],tema:0,sinLista:1},
  herramientas:{n:FORM_TIPOS.herramientas,items:['Cables y enchufes sin daño','Carcasas y protecciones completas','Discos y brocas en buen estado','Herramientas aisladas para trabajo eléctrico'],tema:0},
  vehiculo:{n:FORM_TIPOS.vehiculo,items:['Luces y señalizadores','Frenos y freno de mano','Neumáticos y repuesto','Niveles de aceite y agua','Extintor y botiquín','Cinturones de seguridad'],tema:0}};
const RESP=['Sí','No','No aplica'];
const ATS_PERMISOS=['Trabajo en altura','Trabajo eléctrico energizado','Bloqueo y etiquetado (LOTO)','Espacio confinado','Trabajo en caliente','Izaje de cargas','Excavación'];
const EPP_TIPOS=['Casco','Lentes de seguridad','Guantes','Zapatos de seguridad','Arnés','Protector auditivo','Respirador','Ropa ignífuga','Chaleco reflectante','Bloqueador solar'];
const COLORES_MES=['Rojo','Azul','Verde','Amarillo','Blanco','Naranjo'];
const LIC_CLASES=['B','A1','A2','A3','A4','A5','C','D'];
const NO_ACCION={'':'Solo anotar',obs:'Crear una observación de obra',inc:'Reportar un incidente'};
/* ---------- Listas que cambian el administrador y los encargados de prevención ---------- */
const esPrevencionista=()=>(S.prevencion?.encargados||[]).includes(S.me);
const editaListas=()=>isAdmin()||esPrevencionista();
function listaFila(tipo){return (S.d.formListas||[]).find(l=>l.tipo===tipo)}
function listaDe(tipo){const l=listaFila(tipo);return l&&(l.items||[]).length?l.items:FORMS[tipo].items}
function temasDe(tipo){const l=listaFila(tipo);return l&&(l.temas||[]).length?l.temas:(FORMS[tipo].temas||[])}
// La lista con que se llenó (si cambian la lista después, el formulario no se desordena)
const itemsDe=f=>FORMS[f.tipo]?.sinLista?[]:(f.det?.items||listaDe(f.tipo));
function formListasSection(){
  if(!editaListas())return '';
  const enc=S.prevencion?.encargados||[];
  return `<section class="box" id="fmlistas"><h2>Formularios de terreno</h2>
    <p class="hint">Lo que pregunta cada formulario, una línea por punto. Los cambian el administrador y los encargados de prevención; cada formulario ya llenado conserva la lista con que se llenó.</p>
    ${isAdmin()?`<label>Encargados de prevención (prevencionista o gerente de prevención)<select id="prevEnc" multiple size="4">${S.people.filter(p=>p.estado!=='Inactivo').map(p=>`<option value="${p.id}" ${enc.includes(p.id)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`:''}
    <div class="fmlgrid">${Object.entries(FORMS).map(([k,F])=>`<label>${esc(F.n)}${F.sinLista?' · elementos sugeridos':''}<textarea rows="6" data-fmlista="${k}|items">${esc(listaDe(k).join('\n'))}</textarea></label>
      ${F.temas?`<label>Temas sugeridos para la charla<textarea rows="6" data-fmlista="${k}|temas">${esc(temasDe(k).join('\n'))}</textarea></label>`:''}`).join('')}</div>
    <div class="bar-actions"><button type="button" class="btn" data-fmlistasave>Guardar las listas</button></div></section>`;
}
document.addEventListener('change',e=>{const t=e.target;if(t.id!=='prevEnc'||!isAdmin())return;
  guardarEmpresa('prevencion',x=>{x.encargados=[...t.selectedOptions].map(o=>o.value)},'cambió los encargados de prevención')});
document.addEventListener('click',e=>{if(!e.target.closest('[data-fmlistasave]')||!editaListas())return;
  S.d.formListas=S.d.formListas||[];let n=0;
  document.querySelectorAll('[data-fmlista]').forEach(t=>{const [tipo,k]=t.dataset.fmlista.split('|'),v=t.value.split('\n').map(x=>x.trim()).filter(Boolean);
    const base=k==='items'?FORMS[tipo].items:(FORMS[tipo].temas||[]);let l=listaFila(tipo);
    const igual=JSON.stringify(v)===JSON.stringify(l?.[k]?.length?l[k]:base);if(igual)return;
    if(!l){l={id:uid(),tipo,items:[],temas:[]};S.d.formListas.push(l)}l[k]=JSON.stringify(v)===JSON.stringify(base)?[]:v;n++});
  if(!n)return toast('No hay cambios en las listas');
  addLog(`${meName()} cambió las listas de los formularios de terreno`);commit();toast('Listas guardadas');
});
/* ---------- Estado ---------- */
function participantesDe(f){return f.tipo==='epp'?(f.det?.trabajador?[refName('people',f.det.trabajador)]:[]):(f.participantes||[])}
function faltanFirmas(f,firmas){const ya=(firmas||f.firmas||[]).map(x=>norm(x.nombre));return participantesDe(f).filter(n=>!ya.includes(norm(n)))}
function formSt(f){
  if(f.det?.detenido)return {label:'Trabajo detenido',tone:'stuck'};
  const no=Object.values(f.respuestas||{}).filter(v=>v==='No').length+(f.det?.falla?1:0);
  return !(f.firmas||[]).length?{label:'Sin firma',tone:'prog'}:no?{label:`${no} observación${no===1?'':'es'}`,tone:'stuck'}:{label:'Conforme',tone:'done'};
}
/* Fotos: adjuntos del formulario con la nota «Punto N» (cada «No») o «Daño» (vehículo) */
const fotosForm=(f,clave)=>f.id?S.d.adjuntos.filter(a=>a.ent==='formularios'&&a.reg===f.id&&(a.nota||'').startsWith(clave)&&/^image\//.test(a.tipo||'')):[];
const miniaturas=l=>l.map(x=>x.datos?`<img src="${esc(x.datos)}" alt="Foto">`:`<span class="hint">foto</span>`).join('');
