  if(f.tipo==='vehiculo')Object.assign(d,{activo:o.activo||'',km:+o.km||0,conductor:o.conductor||'',licClase:o.licClase||'',licVence:o.licVence||'',falla:(o.falla||'').trim(),crearMant:!!o.crearMant});
  if(f.tipo==='epp'){d.trabajador=o.trabajador||'';d.epp=[];const viejo=f.det?.epp||[];
    for(let i=0;o['e_item_'+i]!==undefined;i++){const it=(o['e_item_'+i]||'').trim();if(!it)continue;
      d.epp.push(Object.assign({item:it,talla:(o['e_talla_'+i]||'').trim(),cantidad:+o['e_cant_'+i]||1,tipo:o['e_tipo_'+i]||'Nuevo',vida:+o['e_vida_'+i]||'',producto:o['e_prod_'+i]??viejo[i]?.producto??''},viejo[i]?.mov?{mov:viejo[i].mov,producto:viejo[i].producto}:{}))}}
  return d;
