/* Firma con el dedo o el mouse */
function iniciarPad(){
  const c=$('modal').querySelector('.firmapad');if(!c)return;const g=c.getContext('2d');g.lineWidth=2.2;g.lineCap='round';g.strokeStyle='#0B2E4F';let on=false;c.dataset.trazos='0';
  const pos=e=>{const r=c.getBoundingClientRect();return [(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height]};
  c.addEventListener('pointerdown',e=>{on=true;try{c.setPointerCapture(e.pointerId)}catch(_){}const [x,y]=pos(e);g.beginPath();g.moveTo(x,y);c.dataset.trazos=+c.dataset.trazos+1});
  c.addEventListener('pointermove',e=>{if(!on)return;const [x,y]=pos(e);g.lineTo(x,y);g.stroke()});
  ['pointerup','pointerleave','pointercancel'].forEach(t=>c.addEventListener(t,()=>{on=false}));
}
