/* ===== ¿Puede salir la cuadrilla? (función 32) ===== */
/* Para cada proyecto activo y un día (por defecto el próximo día hábil) revisa en una sola vista lo que hoy está en
   varias áreas:
   - Equipo: dueños de las tareas abiertas del proyecto que ese día están en curso (inicio ≤ día ≤ plazo) o atrasadas.
   - Por persona: permiso o vacaciones aprobados ese día; acreditación ante el cliente del proyecto y su faena
     (clienteDe, reqsDe(cliente, p.site), semaforo); habilitación para el tipo de trabajo que exige el proyecto
     (p.trabajo, habilitacion); entrega de EPP registrada en el último año (formulario de terreno "epp").
   - Del proyecto: vehículos asignados (activos tipo Vehículo con proyecto = este) y su estado; materiales previstos
     que faltan entregar y si hay stock.
   Rojo = algo impide salir; amarillo = sale, pero hay algo que resolver. Cada problema dice a quién avisar, y
   "Avisar a los responsables" les deja un aviso en la campana. No guarda nada más. */
const proxHabil=d=>{let x=addD(d,1);while(!esHabil(x))x=addD(x,1);return x};
const responsablesArea=(mod,min)=>S.people.filter(p=>p.estado!=='Inactivo'&&nivelDe(p,mod)>=min).map(p=>p.id);
function equipoDe(pr,dia){
  const ts=S.tasks.filter(t=>t.projectId===pr.id&&t.status!=='done'&&t.ownerId&&t.due&&((t.start||t.due)<=dia&&t.due>=dia||t.due<dia));
  return [...new Set(ts.map(t=>t.ownerId))].map(person).filter(p=>p&&p.estado!=='Inactivo');
}
function eppAlDia(p,dia){
  const desde=addD(dia,-365);
  return S.d.formularios.some(f=>f.tipo==='epp'&&f.fecha>=desde&&f.fecha<=dia&&(f.participantes||[]).some(n=>norm(n)===norm(p.name)));
}
function salidaDe(pr,dia){
  const probs=[],add=(tone,txt,para,ent,reg,quien)=>probs.push({tone,txt,para:[...new Set(para)],ent,reg,quien});
  const cli=clienteDe(pr),reqs=cli?reqsDe(cli.id,pr.site):[],tb=pr.trabajo&&S.d.trabajos.find(t=>t.id===pr.trabajo);
  const vehs=S.d.activos.filter(a=>a.proyecto===pr.id&&a.tipo==='Vehículo'&&a.estado!=='Dado de baja');
  // En terreno: con cliente del directorio, tipo de trabajo, vehículo o materiales. Un proyecto interno no pide EPP ni vehículo.
  const terreno=!!(cli||tb||vehs.length||(pr.materiales||[]).length);
  const equipo=equipoDe(pr,dia).map(p=>{
    const r={p,tone:'done',notas:[]},mal=(tone,txt,para,ent,reg)=>{r.notas.push({tone,txt,para:[...new Set(para)]});r.tone=tone==='stuck'||r.tone==='stuck'?'stuck':'prog';add(tone,`${p.name}: ${txt}`,para,ent,reg,p.id)};
    if(conPermiso(p.id,dia))mal('stuck','tiene vacaciones o permiso aprobado ese día',responsablesArea('proyectos',3),'people',p.id);
    if(reqs.length){const s=semaforo(p.id,reqs);
      if(s.tone!=='done'){const fal=reqs.filter(q=>accSt(accDoc(p.id,q.id)).tone===s.tone).map(q=>q.nombre).join(', ');
        mal(s.tone,s.tone==='stuck'?`no está acreditado ante ${cli.nombre} (falta o venció: ${fal})`:`su acreditación ante ${cli.nombre} vence pronto (${fal})`,[p.id,...responsablesArea('acreditacion',4)],'people',p.id)}}
    if(tb){const h=habilitacion(p.id,tb);if(h.tone==='stuck'||h.tone==='prog')mal(h.tone,h.tone==='stuck'?`no está habilitado para ${tb.nombre}`:`su habilitación para ${tb.nombre} vence pronto`,[p.id,...responsablesArea('rrhh',3)],'people',p.id)}
    if(terreno&&!eppAlDia(p,dia))mal('prog','no tiene entrega de EPP registrada en el último año',[...responsablesArea('logistica',3)],'people',p.id);
    return r});
  if(terreno&&!vehs.length&&equipo.length)add('prog','no hay vehículo asignado al proyecto',responsablesArea('activos',3));
  vehs.forEach(a=>{const s=activoSt(a);if(s.tone==='stuck'||a.estado==='En mantención')add('stuck',`${a.nombre} (${a.codigo}): ${s.label.toLowerCase()}`,[a.responsable,...responsablesArea('activos',4)].filter(Boolean),'activos',a.id);
    else if(s.tone==='prog')add('prog',`${a.nombre} (${a.codigo}): ${s.label.toLowerCase()}`,[a.responsable].filter(Boolean),'activos',a.id)});
  if(equipo.length)(pr.materiales||[]).forEach(m=>{const prod=S.d.products.find(x=>x.id===m.producto);if(!prod)return;const falta=Math.max(0,m.cantidad-entregado(pr.id,prod.id)),st=stockOf(prod);
    if(!falta)return;
    if(st<falta)add('stuck',`faltan ${falta} ${prod.unidad||'un'} de ${prod.nombre} ${st>0?`y en bodega hay ${st}`:'y no hay en bodega'}`,responsablesArea('compras',3).concat(responsablesArea('logistica',3)),'products',prod.id);
    else add('prog',`retirar ${falta} ${prod.unidad||'un'} de ${prod.nombre} de bodega`,responsablesArea('logistica',3),'products',prod.id)});
  const tone=probs.some(x=>x.tone==='stuck')?'stuck':probs.length?'prog':'done';
  return {pr,dia,cli,tb,equipo,vehs,probs,tone,label:!equipo.length?'Sin equipo ese día':{stuck:'No puede salir',prog:'Sale con pendientes',done:'Todo listo'}[tone]};
}
