/* ===== Simulador "¿qué pasa si…?" por proyecto (función 33) ===== */
/* Vista "Simulador" del proyecto (Proyectos "Ver" y Contabilidad "Ver", porque muestra el margen). Nada se guarda:
   el escenario vive en SIM mientras se mira. Palancas:
   - dias: corre las tareas abiertas N días (negativo = adelantar).
   - cambio: el dólar y el euro suben o bajan un %; encarece o abarata las OC en moneda extranjera aún no recibidas.
   - personas: suma N personas de una jornada (jornada()) por semana al equipo; acorta lo que queda en proporción a la capacidad y
     cuesta N × jornada × semanas restantes × valor hora.
   - multa: CLP por día de atraso sobre el término del contrato (p.end).
   Resultado, hoy contra el escenario: término, días de atraso, margen estimado (presupuestoDe menos multa, personas
   y diferencia de cambio), cobros del proyecto en 8 semanas (estados de pago pendientes ligados a una tarea: plazo
   de la tarea + 30 días), saldo de caja al final de las 8 semanas (flujoCaja más esas diferencias) y personas
   sobrecargadas (sobrecargas con las fechas del escenario). */
let SIM={pid:null,dias:0,cambio:0,personas:0,multa:0};
function simTareas(p,x){
  const ab=S.tasks.filter(t=>t.projectId===p.id&&t.name&&t.status!=='done');
  const due=ab.map(t=>t.due?addD(t.due,x.dias):''),own=[...new Set(ab.map(t=>t.ownerId).filter(Boolean))].map(person).filter(Boolean);
  const cap=own.reduce((a,q)=>a+capacidad(q),0)||jornada(),factor=cap/(cap+jornada()*Math.max(0,x.personas));
  const comp=d=>!d||d<=TODAY?d:addD(TODAY,Math.round(diff(TODAY,d)*factor));
  return {ab,due:due.map(comp),start:ab.map((t,i)=>t.start?comp(addD(t.start,x.dias)):''),factor};
}
function simCalc(p,x){
  const st=simTareas(p,x),hechas=S.tasks.filter(t=>t.projectId===p.id&&t.status==='done'&&t.due).map(t=>t.due);
  const termino=[...st.due.filter(Boolean),...hechas].sort().pop()||p.end||'';
  const atraso=p.end&&termino>p.end?diff(p.end,termino):0;
  const pre=presupuestoDe(p),sem=termino>TODAY?diff(TODAY,termino)/7:0;
  const personas=Math.round(Math.max(0,x.personas)*jornada()*sem*(+p.valorHora||0));
  const ext=S.d.ocs.filter(o=>o.proyecto===p.id&&o.moneda&&o.moneda!=='CLP'&&['Por aprobar','Aprobada','Enviada'].includes(o.estado)).reduce((a,o)=>a+(aCLP(o.neto,o.moneda,TODAY)||0),0);
  const cambio=Math.round(ext*x.cambio/100),multa=Math.round(atraso*(+x.multa||0));
  const fin=addD(lunesDe(TODAY),SEM_CAJA*7),venc={};st.ab.forEach((t,i)=>venc[t.id]=st.due[i]);
  const cobros=S.d.edps.filter(r=>r.proyecto===p.id&&r.tarea&&['Pendiente','Enviado al cliente','Aprobado por el cliente'].includes(r.estado)).reduce((a,r)=>{
    const t=task(r.tarea),d=t?(t.status==='done'?TODAY:venc[t.id]||t.due):'';return d&&addD(d,30)<fin?a+Math.round(montoEDP(r)*1.19):a},0);
  let sobre=0;const S0=S;
  try{S=Object.assign({},S0,{tasks:S0.tasks.map(t=>Object.assign({},t))});st.ab.forEach((t,i)=>{const c=S.tasks.find(y=>y.id===t.id);c.due=st.due[i];if(c.start)c.start=st.start[i]});sobre=new Set(sobrecargas().map(s=>s.p.id)).size}
  finally{S=S0}
  return {termino,atraso,margen:pre.margen==null?null:pre.margen-multa-personas-cambio,multa,personas,cambio,ext,cobros,sobre};
}
