/* ===== Asistente que actúa (función 40) ===== */
/* El asistente (asistente.js) entiende órdenes simples y prepara el registro; la persona revisa y confirma (guarda el
   formulario o aprieta "Crear"). Nunca guarda solo. Sin IA, con palabras clave (entenderOrden):
   - "crea la OC de 8 baterías para Norte": OC en borrador con el producto (por nombre o código, en singular o plural),
     la cantidad, el proyecto (por nombre, sitio o cliente) y el último proveedor que lo vendió, con su precio.
   - "crea la tarea Revisar inversor en Norte para Técnico 1 el viernes": tarea con proyecto, responsable y plazo.
   - "pide vacaciones del 20 al 24 de octubre" (o permiso, día administrativo): solicitud a nombre de quien pregunta.
   - "reserva la camioneta para Costa del 20 al 22 de octubre": reserva del activo.
   - "registra un gasto de 15.000 en combustible para Norte": rendición.
   Fechas: hoy, mañana, pasado mañana, el lunes…domingo (el próximo), "20 de octubre", "20-10", "del 20 al 24 de octubre".
   Cada orden respeta los permisos de quien la da (canCreate, canEditProj). Las órdenes libres y más complejas quedan
   para el asistente con IA en el servidor (tarjeta en Integraciones). */
const MESES_N=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const DIAS_N=['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const raiz=w=>w.replace(/(es|s)$/,'');
const palabras=s=>norm(s).replace(/[^a-z0-9ñ\s-]/g,' ').split(/\s+/).filter(w=>w.length>2||/\d/.test(w));
/* Mejor coincidencia por palabras (en singular) */
function calce(texto,lista,campos){
  const ws=new Set(palabras(texto).map(raiz));let mejor=null,pts=0;
  lista.forEach(x=>{const n=campos(x).filter(Boolean).flatMap(palabras).map(raiz).filter((w,i,a)=>a.indexOf(w)===i&&!['sitio','proyecto','cliente','ejemplo'].includes(w)).filter(w=>ws.has(w)).length;if(n>pts){pts=n;mejor=x}});
  return mejor;
}
function fechasDe(texto){
  const t=norm(texto),out=[],anio=+TODAY.slice(0,4),y=(m,d)=>{let f=`${anio}-${pad(m)}-${pad(d)}`;if(f<TODAY&&diff(f,TODAY)>60)f=`${anio+1}-${pad(m)}-${pad(d)}`;return f};
  // un número suelto no puede venir pegado a letras o guiones (como en VEH-01 o 12V)
  const re=/\bpasado manana\b|\bmanana\b|\bhoy\b|(?:el |este |proximo )?\b(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b|(?<![\w-])(\d{1,2})(?![\d\w])(?: de (enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre))?(?:[-\/](\d{1,2})(?:[-\/](\d{2,4}))?)?/g;
  let m;const sueltos=[];
  while((m=re.exec(t))){
    if(m[0]==='hoy')out.push(TODAY);else if(m[0]==='manana')out.push(addD(TODAY,1));else if(m[0]==='pasado manana')out.push(addD(TODAY,2));
    else if(m[1]){const w=DIAS_N.indexOf(m[1]);let d=addD(TODAY,1);while(P(d).getDay()!==w)d=addD(d,1);out.push(d)}
    else if(m[2]&&m[3])out.push(y(MESES_N.indexOf(m[3])+1,+m[2]));
    else if(m[2]&&m[4]){const yy=m[5]?(m[5].length===2?2000+ +m[5]:+m[5]):null;out.push(yy?`${yy}-${pad(+m[4])}-${pad(+m[2])}`:y(+m[4],+m[2]))}
    else if(m[2]){sueltos.push({i:out.length,d:+m[2]})}
  }
  // "del 20 al 24 de octubre": el 20 toma el mes del 24
  sueltos.reverse().forEach(s=>{const sig=out[s.i];if(sig&&s.d>=1&&s.d<=31)out.splice(s.i,0,`${sig.slice(0,8)}${pad(s.d)}`)});
  return out;
}
const cantidadDe=t=>{const m=/(?:^|\s)(\d{1,3}(?:\.\d{3})+|\d+)(?:\s|$)/.exec(' '+norm(t).replace(/\$/g,'')+' ');return m?+m[1].replace(/\./g,''):null};
