    const f=fechasDe(q),tipo=/administrativo/.test(t)?'Día administrativo':/sin goce/.test(t)?'Permiso sin goce':/permiso/.test(t)?'Permiso con goce':/licencia/.test(t)?'Licencia médica':'Vacaciones';
    if(!f.length)return {error:'¿Desde y hasta qué día? Por ejemplo «pide vacaciones del 20 al 24 de octubre».'};
