    return {tipo:'rendicion',txt:`Rendición de ${fmtMoney(monto)} en ${cat.toLowerCase()}${proy?` para ${proy.name}`:''}, a tu nombre.`,puede:canCreate('rends','contabilidad'),
      hacer:()=>editRec('rends',null,{persona:S.me,monto,categoria:cat,proyecto:proy?.id||'',motivo:cat,fecha:TODAY,estado:'Pendiente'},'contabilidad')};
