/* ===== Lectura automática de documentos (función 41) ===== */
/* Lo que se puede leer sin servidor ya funciona: la factura electrónica del SII en XML (DTE). Trae el RUT y la razón
   social del emisor, el folio, la fecha de emisión y de vencimiento, los montos y el detalle.
   - Contabilidad → Por pagar → "Leer factura electrónica (XML)": abre la factura de proveedor llena para revisar y
     guardar (leerXMLFactura). El proveedor se busca en el Directorio por RUT y, si no, por razón social; si no está,
     se avisa y queda anotado en las notas. Si el folio ya existe para ese proveedor, se avisa antes de duplicarla.
   - Fotos y PDF (boletas, guías de despacho, certificados de acreditación) necesitan lectura con IA en el servidor:
     botón "Leer con IA" en los documentos de rendiciones, facturas, movimientos y acreditación (interfaz preparada). */
const rutN=s=>String(s||'').replace(/[^0-9kK]/g,'').toUpperCase();
const DTE_TIPOS={33:'Factura electrónica',34:'Factura exenta electrónica',46:'Factura de compra electrónica',56:'Nota de débito electrónica',61:'Nota de crédito electrónica'};
function leerDTE(texto){
  let doc;try{doc=new DOMParser().parseFromString(String(texto),'application/xml')}catch(e){return {err:'El archivo no es un XML válido.'}}
  if(doc.getElementsByTagName('parsererror').length)return {err:'El archivo no es un XML válido.'};
  const uno=(raiz,tag)=>{const x=(raiz||doc).getElementsByTagName(tag)[0];return x?x.textContent.trim():''};
  const enc=doc.getElementsByTagName('Encabezado')[0];if(!enc)return {err:'No encontré una factura electrónica (DTE) en el archivo.'};
  const tipo=+uno(enc,'TipoDTE'),num=x=>+String(x||'').replace(',','.')||0;
  const lineas=[...doc.getElementsByTagName('Detalle')].map(d=>({d:uno(d,'NmbItem'),q:num(uno(d,'QtyItem'))||1,p:num(uno(d,'PrcItem'))||num(uno(d,'MontoItem'))})).filter(l=>l.d);
  return {tipo,tipoTxt:DTE_TIPOS[tipo]||`Documento tipo ${tipo}`,folio:uno(enc,'Folio'),emision:uno(enc,'FchEmis'),vence:uno(enc,'FchVenc'),
    rut:uno(enc,'RUTEmisor'),razon:uno(enc,'RznSoc')||uno(enc,'RznSocEmisor'),receptor:uno(enc,'RUTRecep'),neto:num(uno(enc,'MntNeto'))||num(uno(enc,'MntExe')),iva:num(uno(enc,'IVA')),total:num(uno(enc,'MntTotal')),lineas};
}
function leerXMLFactura(texto){
  if(!canCreate('docs','contabilidad'))return toast('Tu rol no permite ingresar facturas');
  const x=leerDTE(texto);if(x.err)return toast(x.err);
  if([56,61].includes(x.tipo))return toast(`${x.tipoTxt} N° ${x.folio}: las notas de crédito y débito se ingresan a mano por ahora`);
  const prov=S.d.contacts.find(c=>c.rut&&rutN(c.rut)===rutN(x.rut))||S.d.contacts.find(c=>norm(c.nombre)===norm(x.razon));
  const dup=prov&&S.d.docs.find(d=>d.tipo==='Compra'&&d.contraparte===prov.id&&norm(d.numero)===norm(x.folio));
  if(dup)return toast(`La factura N° ${x.folio} de ${prov.nombre} ya está ingresada`);
  editRec('docs',null,{tipo:'Compra',numero:x.folio,contraparte:prov?.id||'',emision:x.emision||TODAY,vence:x.vence||addD(x.emision||TODAY,30),neto:x.neto,lineas:x.lineas.length?x.lineas:[{d:'',q:1,p:0}],pagado:0,
    notas:`Leída del XML del SII: ${x.tipoTxt} N° ${x.folio} de ${x.razon} (RUT ${x.rut}). Total ${fmtMoney(x.total)}.${prov?'':' El proveedor no está en el Directorio.'}`},'contabilidad');
  toast(prov?`Factura N° ${x.folio} de ${prov.nombre} leída: revísala y guárdala`:`Factura leída, pero ${x.razon} (RUT ${x.rut}) no está en el Directorio: agrégalo y elígelo`);
}
