/* ===== App conectada a Supabase (backend, etapa 2) ===== */
/* Solo se activa si la página trae window.HILVANTA_SERVIDOR = {url, anon} (la versión publicada en GitHub Pages;
   la de claude.ai y la del archivo local siguen guardando en el navegador).
   - Inicio de sesión con correo y clave (Supabase Auth). "Cambiar de usuario" pasa a ser "Cerrar sesión".
   - Al entrar: hilvanta_mis_empresas() dice la empresa y la persona; se leen todas las tablas (la base ya filtra lo
     que cada uno puede ver) y modelo/exportar.js las convierte en S.
   - En cada guardado, ALMACEN entrega los cambios; se convierten con modelo/importar.js (conserva los ids) y se
     escriben uno por uno, en el orden de las tablas: insertar lo nuevo, actualizar lo cambiado, borrar lo eliminado
     (no "insertar o reemplazar": choca con los permisos, p. ej. un técnico cambia su ficha pero no crea personas).
     Hijos: líneas, pagos, subtareas, materiales y permisos del rol se reemplazan con su registro; los comentarios
     solo se agregan; los ítems de ingreso y salida se actualizan uno a uno (los marca cada rol).
   - Si la base rechaza algo (permisos, reglas de aprobación, datos inválidos) o un cambio no toca ninguna fila,
     se avisa y se vuelve a cargar todo desde el servidor, para no quedar con datos que no son los reales.
   - El cliente es una interfaz chica (leer, insertar, actualizar, borrar, rpc): clienteSupabase en la app y uno
     sobre PostgreSQL en las pruebas (pruebas/servidor.js). */
const SRV_HIJOS={orden_compra:[['orden_compra_linea','orden_compra_id']],guia_despacho:[['guia_despacho_linea','guia_id']],factura:[['factura_linea','factura_id'],['pago','factura_id']],
  tarea:[['subtarea','tarea_id']],proyecto:[['proyecto_material','proyecto_id']],rol:[['rol_permiso','rol_id']]};
const SRV_NO_TOCA={persona:['usuario_id','pin_hash'],contacto:[],tarea:['creado_en']};   // columnas que la app no maneja
let SRV=null;   // {cli, E, me, foto, cola, ocupado, error}
const srvTabla=col=>col==='auto'?'automatizacion':HILVANTA_COL_TABLA[col];
function srvError(e){const m=String(e&&e.message||e||'');
  if(/row-level security|permission denied|42501|no permitido/i.test(m))return 'tu rol no permite ese cambio en el servidor';
  return m.replace(/^.*?ERROR:\s*/,'')}
/* ---------- Leer ---------- */
async function srvCargar(cli,preferida){
  try{await cli.rpc('hilvanta_ligarme')}catch(e){}   // liga la cuenta a fichas que la esperan con su correo (alta.js)
  const es=await cli.rpc('hilvanta_mis_empresas');
  if(!es.length)throw new Error('SIN_EMPRESA');
  const e=es.find(x=>x.empresa_id===preferida)||es[0];let t={},borrados='',delta=null;
  const tablas=HILVANTA_ORDEN_TABLAS.filter(x=>x!=='correlativo');
  // Con una copia reciente en el equipo se traen solo los cambios (delta.js); si no, todo
  delta=await filasDesdeCopia(cli,e.empresa_id,e.persona_id,tablas);
  if(delta){t=delta.t;borrados=delta.borrados}
  else{await Promise.all(tablas.map(async x=>{t[x]=await cli.leer(x)}));t.empresa=await cli.leer('empresa')}
  const s=hilvantaDesdeFilas(t,e.empresa_id);
  // Nombres, cargos y a quién reporta cada uno, para el organigrama de quien no ve Personas (organigrama.js)
  try{ORG_NOMBRES=(await cli.leer('v_persona_nombre')).filter(x=>x.empresa_id===e.empresa_id).map(x=>({id:x.id,name:x.nombre||'',role:x.cargo||'',area:x.area_trabajo||'',estado:x.estado||'Activo',reportaA:x.reporta_a||'',foto:x.foto||undefined}))}catch(er){ORG_NOMBRES=null}
  s.me=e.persona_id;s.empresas=es;
  return {s,t,E:e.empresa_id,me:e.persona_id,borrados,delta:!!delta};
}
/* ---------- Guardar ---------- */
const srvSinNoToca=(tabla,f)=>{const o=Object.assign({},f);(SRV_NO_TOCA[tabla]||[]).forEach(k=>delete o[k]);delete o.empresa_id;delete o.id;return o};
async function srvSincronizar(cli,E,me,foto,s,cambios){
  await srvSubirArchivos(cli,E,s,cambios);   // primero los archivos, así la fila del adjunto lleva su ruta
  const imp=await hilvantaAFilas(JSON.parse(JSON.stringify(s)),{empresa:E}),F=imp.filas,orden=HILVANTA_ORDEN_TABLAS;
  const antes=(col,id)=>{const x=foto.col[col]&&foto.col[col][id];return x?JSON.parse(x):null};
  const pos=c=>c.col==='log'?999:c.col==='ajustes'?-1:orden.indexOf(srvTabla(c.col));
  const altas=cambios.filter(c=>c.op!=='borrar').sort((a,b)=>pos(a)-pos(b)),bajas=cambios.filter(c=>c.op==='borrar').sort((a,b)=>pos(b)-pos(a));
  const filaDe=(tabla,id)=>(F[tabla]||[]).find(r=>r.id===id);
  const unaFila=async p=>{const n=await p;if(Array.isArray(n)&&!n.length)throw new Error('no permitido: la base no aplicó el cambio');return n};
  for(const c of [...altas,...bajas]){
    if(c.col==='auditoria')continue;                                         // la escriben los disparadores
    if(c.col==='log'){await cli.insertar('actividad',[{empresa_id:E,persona_id:me,en:c.reg.at,texto:c.reg.text}]);continue}
    if(c.col==='ajustes'){await srvAjuste(cli,E,F,c.clave);continue}
    const tabla=srvTabla(c.col);if(!tabla||tabla==='empresa')continue;
    if(c.col==='indicadores'){const a=antes(c.col,c.id);
      if(a)await cli.borrar('indicador',{empresa_id:E,fecha:a.fecha});
      if(c.op!=='borrar'){const f=F.indicador.find(r=>r.fecha===c.reg.fecha);if(f)await cli.insertar('indicador',[f])}continue}
    if(c.op==='borrar'){await unaFila(cli.borrar(tabla,{id:c.id}));srvQuitarFila(tabla,c.id);continue}
    const f=filaDe(tabla,c.id);if(!f)continue;
    if(tabla==='rol'&&c.op!=='crear'&&!isAdmin()){await unaFila(cli.actualizar('rol',{panel:f.panel},{id:c.id}));continue}   // Inicio del rol (persona.inicio_todos)
    if(tabla==='proyecto'&&f.cliente_id&&!(s.d.contacts||[]).some(x=>x.id===f.cliente_id)){   // cliente nuevo escrito a mano
      const ct=filaDe('contacto',f.cliente_id);if(ct){await cli.insertar('contacto',[ct]);s.d.contacts.push({id:ct.id,nombre:ct.nombre,tipo:'Cliente',pais:'Chile'})}}
    // Otra persona (que esta no ve) pudo anotar ya la misma ejecución de una automatización: no es un error
    if(c.op==='crear'){try{await cli.insertar(tabla,[f]);srvPonerFila(tabla,srvJSON(tabla)(f))}catch(e){if(!(tabla==='automatizacion_ejecucion'&&/ejecucion_clave|duplicate|23505/.test(e.message)))throw e}}
    else await srvActualizar(cli,tabla,c.id,srvSinNoToca(tabla,f),c.col,c.reg);   // revisa que nadie haya cambiado lo mismo (simultaneos.js)
    for(const [h,fk] of SRV_HIJOS[tabla]||[]){
      if(c.op!=='crear'){await cli.borrar(h,{[fk]:c.id});srvQuitarHijos(h,fk,c.id)}
      const hs=(F[h]||[]).filter(r=>r[fk]===c.id);if(hs.length){await cli.insertar(h,hs);hs.forEach(r=>srvPonerFila(h,srvJSON(h)(r)))}}
    if(tabla==='tarea'){const viejos=new Set(((antes(c.col,c.id)||{}).comments||[]).map(x=>x.id)),nuevos=new Set((c.reg.comments||[]).map(x=>x.id));
      const ins=F.comentario_tarea.filter(r=>r.tarea_id===c.id&&r.id&&!viejos.has(r.id));if(ins.length)await cli.insertar('comentario_tarea',ins);
      for(const id of viejos)if(!nuevos.has(id))await cli.borrar('comentario_tarea',{id})}
    if(tabla==='proceso_personal'){const items=F.proceso_item.filter(r=>r.proceso_id===c.id);
      if(c.op==='crear'){if(items.length)await cli.insertar('proceso_item',items)}
      else{const viejo=(antes(c.col,c.id)||{}).items||[];
        for(const it of items)if(JSON.stringify(viejo[it.orden])!==JSON.stringify((c.reg.items||[])[it.orden]))
          await unaFila(cli.actualizar('proceso_item',{hecho:it.hecho,hecho_por:it.hecho_por,hecho_en:it.hecho_en,texto:it.texto,rol_id:it.rol_id},{proceso_id:c.id,orden:it.orden}))}}
  }
}
async function srvAjuste(cli,E,F,clave){
  const em=F.empresa[0];
  if(clave==='inicioEmpresa')return cli.actualizar('empresa',{inicio:em.inicio?JSON.parse(em.inicio):null},{id:E});   // 'inicio' también es una fecha en otras tablas: aquí va como jsonb
  if(['company','caja','integ','feriados','flujos','gastoCats','funciones','jornada','marca','correlativos','textosDoc','estados','karin','vistasEmpresa','funcApagadas','jefaturas','prevencion'].includes(clave))return cli.actualizar('empresa',{funciones_apagadas:em.funciones_apagadas,jefaturas:em.jefaturas,prevencion:em.prevencion,nombre:em.nombre,saldo_banco:em.saldo_banco,fecha_saldo_banco:em.fecha_saldo_banco,integraciones:em.integraciones,feriados:em.feriados,flujos_gasto:em.flujos_gasto,gasto_categorias:em.gasto_categorias,funciones:em.funciones,
    jornada:em.jornada,marca:em.marca,correlativos:em.correlativos,textos_doc:em.textos_doc,estados:em.estados,karin:em.karin,vistas:em.vistas},{id:E});
  if(clave==='mods'){for(const a of F.empresa_area){await cli.borrar('empresa_area',{empresa_id:E,area:a.area});await cli.insertar('empresa_area',[a])}return}
  const T={custom:'campo_personalizado',aprob:'regla_aprobacion',checklists:'lista_personal',auto:'automatizacion'}[clave];if(!T)return;
  await cli.borrar(T,{empresa_id:E});if(F[T].length)await cli.insertar(T,F[T]);
}
/* ALMACEN de servidor: guarda en orden; si algo falla, avisa y recarga */
const ALMACEN_SERVIDOR={
  leer(){return null},leerAnterior(){return null},
  leerPrefs(){return ALMACEN_NAVEGADOR.leerPrefs()},guardarPrefs(p){ALMACEN_NAVEGADOR.guardarPrefs(p)},
  guardar(s,cambios){if(!SRV||!cambios.length)return;const foto=SRV.foto;SRV.foto=fotoDe(s);
    const copia=JSON.parse(JSON.stringify(s));
    SRV.cola=SRV.cola.then(()=>{srvEstado('guardando');return srvSincronizar(SRV.cli,SRV.E,SRV.me,foto,copia,cambios)})
      .then(()=>srvEstado(''),e=>{SRV.error=e;srvEstado('');toast(`No se guardó en el servidor: ${srvError(e)}. Se vuelven a cargar los datos.`,6000);return srvRecargar()});
    return SRV.cola}
};
function srvEstado(x){const b=$('sync');if(b){b.hidden=!x;b.textContent=x==='guardando'?'Guardando…':''}}
