/* ---------- Cliente sobre supabase-js ---------- */
// Columnas jsonb: el importador las entrega como texto JSON (sirve para SQL); a la API van como objeto
const SRV_JSONB=new Set(['accion','acceso','aprobaciones','cambios','columnas','datos','disparador','extra','fases','feriados','flujos_gasto','funciones','gasto_categorias','grupos','panel','permisos','firma','firmas','hitos','integraciones','items','materiales','niveles','ofertas','participantes','portal','preferencias','respuestas','ubicacion','condicion','jornada','revisiones','marca','correlativos','textos_doc','estados','karin','vistas','cierre','funciones_apagadas','jefaturas','tarjetas','filtros','envios','inicio','remuneracion','calculo','contenido','prevencion','temas']);
// Columnas de texto que se llaman igual que una jsonb de otra tabla (se revisan con esquema.sql al sumar un nombre a la lista)
const SRV_TEXTO={incidente:['accion'],auditoria:['accion'],activo:['marca'],observacion_obra:['ubicacion'],proyecto:['inicio'],tarea:['inicio'],oferta:['inicio']};
const srvJSON=t=>f=>{const o={},txt=SRV_TEXTO[t]||[];Object.keys(f).forEach(k=>{const v=f[k];if(v===undefined)return;o[k]=SRV_JSONB.has(k)&&!txt.includes(k)&&typeof v==='string'?JSON.parse(v):v});return o};
function clienteSupabase(sb){
  const ok=({data,error})=>{if(error)throw new Error(error.message+(error.code?` (${error.code})`:''));return data};
  const filtrar=(q,f)=>{Object.entries(f).forEach(([k,v])=>{q=Array.isArray(v)?q.in(k,v):q.eq(k,v)});return q};
  return {
    async leer(t){let out=[],i=0;for(;;){const d=ok(await sb.from(t).select('*').range(i,i+999));out=out.concat(d);if(d.length<1000)return out;i+=1000}},
    async leerDesde(t,desde,col='modificado_en'){let out=[],i=0;for(;;){let q=sb.from(t).select('*');if(desde)q=q.gt(col,desde);const d=ok(await q.order(col).range(i,i+999));out=out.concat(d);if(d.length<1000)return out;i+=1000}},
    async contar(t){const {count,error}=await sb.from(t).select('id',{count:'exact',head:true});if(error)throw new Error(error.message);return count},
    async leerUno(t,id){return (ok(await sb.from(t).select('*').eq('id',id).limit(1))||[])[0]||null},
    async insertar(t,filas){return ok(await sb.from(t).insert(filas.map(srvJSON(t))))},
    async actualizar(t,valores,f){return ok(await filtrar(sb.from(t).update(srvJSON(t)(valores)),f).select('*'))},
    async borrar(t,f){return ok(await filtrar(sb.from(t).delete(),f).select('*'))},
    async rpc(n,a){return ok(await sb.rpc(n,a||{}))||[]},
    // Archivos adjuntos (archivos.js): bucket privado «adjuntos»
    async subir(ruta,blob,tipo){return ok(await sb.storage.from('adjuntos').upload(ruta,blob,{contentType:tipo,upsert:false}))},
    async firmar(ruta){return ok(await sb.storage.from('adjuntos').createSignedUrl(ruta,600)).signedUrl},
    async quitar(ruta){return ok(await sb.storage.from('adjuntos').remove([ruta]))}
  };
}
