function contextoIA(q){
  const p=person(S.me),L=[`Hoy: ${fmt(TODAY)}. Persona: ${p?.name||''} (${myRole().name}). Empresa: ${S.company||''}.`];
  const areas=MODORDER.filter(k=>lvl(k)>=1).map(k=>`${MOD[k].name} (${(LVN.find(([v])=>LV[v]===lvl(k))||[])[1]||''})`);
  L.push(`Áreas a las que tiene acceso: ${areas.join(', ')||'ninguna'}.`);
  const pe=pendings();if(pe.length)L.push(`Aprobaciones esperando su respuesta (${pe.length}):`,...pe.slice(0,25).map(x=>`- ${x.mod}: ${x.txt} · ${x.det||''}`));
  const al=alerts();if(al.length)L.push(`Alertas (${al.length}):`,...al.slice(0,40).map(x=>`- ${x.mod}: ${x.txt} · ${x.det||''}`));
  const mias=S.tasks.filter(t=>t.ownerId===S.me&&t.status!=='done'&&t.name);
  if(mias.length)L.push(`Sus tareas abiertas (${mias.length}):`,...mias.slice(0,30).map(t=>`- ${t.name} · ${proj(t.projectId)?.name||''} · ${STATES.find(s=>s.id===t.status)?.name||t.status}${t.due?` · plazo ${fmt(t.due)}`:''}${isLate(t)?' (atrasada)':''}`));
  if(lvl('proyectos')>=1){const ps=visibleProjects().filter(x=>x.status==='activo');
    if(ps.length)L.push('Proyectos activos que ve:',...ps.map(x=>{const ts=S.tasks.filter(t=>t.projectId===x.id&&canSeeTask(t)),d=ts.filter(t=>t.status==='done').length;
      return `- ${x.name}${x.client?` (${x.client})`:''}: ${ts.length?Math.round(d/ts.length*100):0}% de tareas listas, ${ts.filter(isLate).length} atrasadas, término ${fmt(x.end)}`}))}
  const clave=String(q||'').replace(/[¿?¡!.,]/g,' ').split(/\s+/).filter(w=>w.length>3).join(' ');
  const res=clave?buscar(clave).slice(0,20):[];
  if(res.length)L.push('Registros que coinciden con la pregunta:',...res.map(x=>`- ${x.grupo}: ${x.tit}${x.sub?` · ${x.sub}`:''}`));
  return L.join('\n');
}
