// Foto → data URL de hasta 1600 px en JPEG (así pesa poco y la IA la acepta)
function fotoReducida(src){return new Promise((ok,mal)=>{const im=new Image();im.onload=()=>{const k=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement('canvas');
  c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);ok(c.toDataURL('image/jpeg',0.85))};im.onerror=()=>mal(new Error('No pude abrir la imagen'));im.src=src})}
function elegirFoto(){return new Promise(ok=>{const i=document.createElement('input');i.type='file';i.accept='image/*';i.setAttribute('capture','environment');
  i.onchange=()=>{const f=i.files?.[0];if(!f)return ok(null);const rd=new FileReader();rd.onload=()=>ok(rd.result);rd.onerror=()=>ok(null);rd.readAsDataURL(f)};i.click()})}
function ponerCampo(k,v){const el=$('m_'+k);if(!el||v==null||v==='')return false;
  if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===String(v)))return false;
  el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));return true}
