  const src=(ult&&await datosAdjunto(ult))||(!id&&FOTO_PEND?.datos)||await elegirFoto();if(!src)return;   // la foto puede estar en el servidor (archivos.js)
  if(!/^data:image\//.test(src))return toast('La IA lee fotos (JPG o PNG). Para facturas electrónicas usa «Leer factura electrónica (XML)».');
