    const n=v=>v==null||v===''?null:Math.round(+String(v).replace(/[^\d-]/g,''))||null,f=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')?v:null,puestos=[];
    const pon=(k,v,et)=>{if(ponerCampo(k,v))puestos.push(et)};
