      const mon=['CLP','USD','EUR'].includes(String(c.moneda||'').toUpperCase())?String(c.moneda).toUpperCase():'';
      pon('comercio',c.emisor,'proveedor');pon('rutComercio',c.rut_emisor,'RUT');pon('fecha',f(c.fecha),'fecha');pon('tipoDoc',tipo,'tipo de documento');pon('numDoc',c.folio,'N° de documento');
      if(mon)pon('moneda',mon,'moneda');pon('monto',mon&&mon!=='CLP'?(+String(c.total).replace(',','.')||null):n(c.total),'monto');
