  const extra=periodo==='noche'?`mañana ${c.min2}° a ${c.max2}°`:periodo==='manana'?`máx. ${c.max}° · mín. ${c.min}°`:`viento ${c.viento} km/h`;
  return `<button type="button" class="clima" data-clima title="Cambiar la ciudad del clima">${iconoClima(periodo,tipo)}<span>${esc(c.lugar)} · <b>${c.temp} °C</b> · ${esc(nombre)} <span class="clima-extra">· ${extra}</span></span></button>`;
