/* Permisos propios de una persona (pedido de Miguel, 21-10-2026): dos personas con el mismo rol pueden tener niveles
   distintos en un área. p.permisos = {área: nivel}; lo que no está ahí sigue a su rol. En la base, persona.permisos
   (lo cambia solo un administrador) y hilvanta.nivel lo aplica igual que nivelDe. */
const nivelNombre=v=>(LVN.find(x=>x[0]===v)||LVN[0])[1];
function permisosTxt(p){
  const ks=Object.keys(p.permisos||{}).filter(a=>MOD[a]&&modOn(a));
  if(roleOf(p).admin)return '<span class="hint">Todo (administrador)</span>';
  return ks.length?`<span class="pill perm-pers">${cuenta(ks.length,'área distinta','áreas distintas')} a su rol</span>`:'<span class="hint">Como su rol</span>';
}
function editPermisosPersona(pid){
  const p=person(pid);if(!p||!isAdmin())return;const r=roleOf(p);
  if(r.admin)return toast(`${p.name} es administrador: ya tiene acceso a todo.`);
  const areas=MODORDER.filter(modOn);
  const flds=areas.map(a=>({k:a,label:MOD[a].name,type:'select',options:[{id:'',name:`Como su rol (${nivelNombre(r.perms?.[a]||'none')})`},...LVN.map(([v,t])=>({id:v,name:t}))]}));
  const vals=Object.fromEntries(areas.map(a=>[a,p.permisos?.[a]||'']));
  openModal(`Permisos de ${esc(p.name)}`,flds,vals,o=>{
    const nuevo={};areas.forEach(a=>{if(o[a])nuevo[a]=o[a]});
    // Fuera de las áreas activas se conservan (se reactivan con su excepción)
    Object.keys(p.permisos||{}).filter(a=>!areas.includes(a)).forEach(a=>nuevo[a]=p.permisos[a]);
    if(Object.keys(nuevo).length)p.permisos=nuevo;else delete p.permisos;
    if(o.inicioTodos==='1')p.inicioTodos=true;else delete p.inicioTodos;
    addLog(`${meName()} ajustó los permisos de ${p.name}`);
  },null,'',[],`<p class="hint wide">${esc(p.name)} tiene el rol <b>${esc(r.name)}</b>. Elige un nivel solo en las áreas donde deba ser distinto; el resto sigue a su rol, también si después cambias el rol.</p>`+flds.map(f=>field(f,vals[f.k])).join('')
    +field({k:'inicioTodos',label:'Personalizar el Inicio para un rol o para toda la empresa',type:'select',options:[{id:'',name:'No: solo su propio Inicio'},{id:'1',name:'Sí'}]},p.inicioTodos?'1':''));
}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-permpers]');if(b){e.preventDefault();editPermisosPersona(b.dataset.permpers)}});
