const ROL_NIVEL={approve:'Aprueba',edit:'Edita',view:'Ve',own:'Solo lo suyo'};
function rolChips(r,areas){
  if(r.admin)return '<span class="rchip lv-admin">Acceso total, incluidos los ajustes</span>';
  const por=a=>areas.filter(x=>(r.perms?.[x]||'none')===a).map(x=>MOD[x].name);
  const sin=por('none').length;
  return Object.keys(ROL_NIVEL).filter(v=>por(v).length).map(v=>`<span class="rchip lv-${v}"><b>${ROL_NIVEL[v]}</b>${esc(por(v).join(', '))}</span>`).join('')
    +(sin?`<span class="rchip lv-none">Sin acceso a ${cuenta(sin,'área','áreas')}</span>`:'');
}
function editRol(id){
  const r=S.roles.find(x=>x.id===id);if(!r||!isAdmin())return;
  const areas=MODORDER.filter(modOn),usados=S.people.filter(p=>p.roleId===r.id).length;r.perms=r.perms||{};
  const flds=[{k:'name',label:'Nombre del rol',type:'text'},{k:'admin',label:'Acceso total (administrador)',type:'select',options:[{id:'no',name:'No'},{id:'si',name:'Sí: todo, incluidos los ajustes'}]},
    ...areas.map(a=>({k:a,label:MOD[a].name,type:'select',options:LVN.map(([v,t])=>({id:v,name:t}))}))];
  const vals={name:r.name,admin:r.admin?'si':'no',...Object.fromEntries(areas.map(a=>[a,r.perms[a]||'none']))};
  openModal(`Rol ${esc(r.name)}`,flds,vals,o=>{
    r.name=(o.name||'').trim()||r.name;
    const antes=r.admin;r.admin=o.admin==='si';if(antes&&!r.admin&&!adminCount()){r.admin=true;toast('Debe quedar al menos un administrador')}
    areas.forEach(a=>r.perms[a]=o[a]||'none');
    addLog(`${meName()} ajustó el rol ${r.name}`);
  },usados?null:()=>doAct('delrole|'+r.id),`¿Eliminar el rol ${esc(r.name)}?`,[],`<p class="hint wide">Con acceso total, los niveles por área no se usan.${usados?` Para eliminarlo, primero asigna otro rol a quienes lo tienen (${cuenta(usados,'usuario','usuarios')}).`:''}</p>`+flds.map(f=>field(f,vals[f.k])).join('')+rolInicioBloque(r));
}
