const monedaFicha=i=>i&&i.hasAttribute('data-monto-clp')?'CLP':$('m_moneda')?.value||'CLP';
function reformatearMontos(){document.querySelectorAll('#modal input[data-monto]').forEach(i=>{if(document.activeElement!==i)i.value=fmtMontoCampo(i.value,monedaFicha(i))})}
// Mientras se escribe: se ordenan los puntos de miles sin mover el cursor de su lugar respecto del final
