// Nombre de la tarea en varias líneas: el cuadro crece con el texto (donde el navegador no tiene field-sizing)
const altoNombre=()=>{const d=document.getElementById('dName');if(!d)return;d.style.height='';const h=d.scrollHeight;if(h>0&&!CSS.supports('field-sizing','content'))d.style.height=h+'px'};
{const _renderDrawer=renderDrawer;renderDrawer=function(){const r=_renderDrawer.apply(this,arguments);altoNombre();return r}}
