  if(so){const c=colsDe(t).find(x=>x.k===so.k);if(c){const key=f=>{const v=valorCol(t,f,c);return c.tipo==='persona'?refName('people',v):c.tipo==='proyecto'?(v?nombreProy(proj(v)||{}):''):c.tipo==='registro'?(v?regTitDe(c,v):''):v};
    fs=[...fs].sort((a,b)=>{const x=key(a),y=key(b);if(x==null||x==='')return 1;if(y==null||y==='')return -1;return (typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'es'))*so.dir})}}
