/* ---------- Edición en la celda (como Excel) ---------- */
function editorCelda(td){
  const [fid,k]=td.dataset.cel.split(':'),f=S.d.filas.find(x=>x.id===fid),t=f&&tableroDe(f.tablero);if(!t||accesoTablero(t)<2)return;
  const c=colsDe(t).find(x=>x.k===k);if(!c)return;
  if(c.tipo==='casilla'){f.datos=f.datos||{};f.datos[k]=!f.datos[k];return guardarFila(f)}
  const v=k==='nombre'?f.nombre||'':f.datos?.[k]??'';
  const sel=(ops,blank=1)=>`<select class="tbin">${blank?'<option value="">—</option>':''}${ops.map(o=>`<option value="${esc(o.id)}" ${String(v)===String(o.id)?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`;
  td.innerHTML=c.tipo==='estado'||c.tipo==='lista'?sel((c.opciones||[]).map(o=>({id:o.v,name:o.v})))
    :c.tipo==='persona'?sel(S.people.filter(p=>p.estado!=='Inactivo'||p.id===v).map(p=>({id:p.id,name:p.name})))
    :c.tipo==='proyecto'?sel(visibleProjects().map(p=>({id:p.id,name:nombreProy(p)})))
    :c.tipo==='registro'?sel(regsElegibles(c.ent,v))
    :`<input class="tbin" type="${c.tipo==='fecha'?'date':c.tipo==='numero'||c.tipo==='dinero'?'number':'text'}" ${c.tipo==='numero'||c.tipo==='dinero'?'step="any"':''} value="${esc(v)}">`;
  td.classList.add('editando');const el=td.querySelector('.tbin');el.focus();if(el.select&&el.type==='text')el.select();
  let hecho=false;
  const fin=guardar=>{if(hecho)return;hecho=true;
    if(guardar){let nv=el.value.trim();if(c.tipo==='numero'||c.tipo==='dinero')nv=nv===''?'':+nv;
      if(k==='nombre'){if(nv!==f.nombre){f.nombre=nv;return guardarFila(f)}}
      else if(String(nv)!==String(v)){f.datos=f.datos||{};if(nv==='')delete f.datos[k];else f.datos[k]=nv;return guardarFila(f)}}
    renderMain()};
  el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();fin(true)}else if(e.key==='Escape'){e.preventDefault();fin(false)}});
  el.addEventListener('blur',()=>fin(true));
  if(el.tagName==='SELECT')el.addEventListener('change',()=>fin(true));
}
function guardarFila(f){f.at=new Date().toISOString();commit()}
