  const pv=$('colPrev');if(!pv||tipo!=='formula')return;const src=$('cfFormula').value.trim(),t=tableroDe(colCtx.t);
  if(!src){pv.className='wide c-form prev';pv.textContent='Escribe una fórmula para ver el resultado con elementos reales.';return}
