/* ===== Inicio a la medida de cada persona y paneles propios (pedido de Miguel, 21-10-2026) =====
   "Personalizar Inicio" pone cada panel en modo edición: subir, bajar, pasar a la otra columna u ocultar, y agregar
   paneles propios que calculan sobre un tablero o sobre los registros de un área que la persona ya puede ver:
     indicador (contar, sumar, promedio, mínimo o máximo de una columna), barras (agrupado por una columna) y lista;
     desde el 24-10-2026 también meta con avance, indicador con semáforo, línea de 6 meses y próximos vencimientos.
   Cada panel puede llevar un filtro (filtros.js). Se guarda en la ficha de la persona: p.panel = {izq:[ids], der:[ids],
   ocultos:[ids], widgets:[{id,tipo,titulo,fuente:'t:<tablero>'|'e:<entidad>',op,col,agrupar,filtros:[{k,op,v}],n}],
   menu:[tableros fijados en su menú]}. En la base, persona.panel (lo cambia cada uno).
   Desde el 26-10-2026 (pedido de Miguel) se entra desde el menú del usuario, y quien tiene el permiso (el administrador, o la
   persona a quien él se lo da: p.inicioTodos; en la base persona.inicio_todos) elige si el cambio es solo para él, para un rol
   (rol.panel) o para toda la empresa (S.inicioEmpresa; en la base empresa.inicio). Cada persona parte del Inicio de su rol, si
   no del de la empresa, y si arma el suyo lo mantiene («Volver al original» la devuelve al de su rol o al de la empresa).
   «Actividad reciente» también pasó al menú del usuario (solo administrador). */
const PANELES={kpis:'Cifras de arriba',tudia:'Tu día',procesos:'Ingresos y salidas de personal',avisos:'Avisos',alertas:'Alertas',
  atajos:'Atajos',aprob:'Bandeja de aprobaciones',solicitudes:'Mis solicitudes',avance:'Avance por proyecto'};
const PANEL_IZQ=['tudia','procesos','avisos','alertas'],PANEL_DER=['atajos','aprob','solicitudes','avance'];
const PANEL_PROPIO=['menu','menuFav','menuOcultos','vistas'];   // lo de cada persona que no viene del rol ni de la empresa
const armoPanel=pn=>!!(pn&&(pn.izq||pn.der||pn.widgets||pn.ocultos));
const puedeInicioTodos=()=>isAdmin()||!!person(S.me)?.inicioTodos;
// Qué Inicio se está personalizando: '' = el mío, 'empresa' o 'r:<rol>' (solo con el permiso)
const destinoPanel=()=>S.ui.personalizar&&S.ui.pdest&&puedeInicioTodos()?S.ui.pdest:'';
const rolDestino=d=>d.startsWith('r:')?S.roles.find(r=>r.id===d.slice(2)):null;
function panelComun(rol){const b=(rol&&rol.panel)||S.inicioEmpresa;return b?JSON.parse(JSON.stringify(b)):{}}
// Si la persona aún no arma su Inicio, parte del de su rol (rol.panel) y, si no, del de toda la empresa
const panelDe=()=>{const d=destinoPanel();if(d)return d==='empresa'?JSON.parse(JSON.stringify(S.inicioEmpresa||{})):panelComun(rolDestino(d));
  const p=person(S.me),pn=p?.panel||{};if(armoPanel(pn))return pn;
  const b=panelComun(p&&roleOf(p));if(!armoPanel(b))return pn;
  PANEL_PROPIO.forEach(k=>{b[k]=pn[k]});return b};
const panelOculto=id=>(panelDe().ocultos||[]).includes(id);
const nombreDestino=d=>d==='empresa'?'toda la empresa':d?`el rol ${rolDestino(d)?.name||''}`:'';
function guardarPanel(fn){
  const d=destinoPanel(),x=JSON.parse(JSON.stringify(panelDe()));Object.keys(x).forEach(k=>x[k]===undefined&&delete x[k]);fn(x);
  if(d){PANEL_PROPIO.forEach(k=>delete x[k]);const vacio=!armoPanel(x);
    if(d==='empresa'){if(vacio)delete S.inicioEmpresa;else S.inicioEmpresa=x}
    else{const r=rolDestino(d);if(!r)return;if(vacio)delete r.panel;else r.panel=x}
    addLog(`${meName()} cambió el Inicio de ${nombreDestino(d)}`);return commit()}
  const p=person(S.me);if(!p)return;p.panel=x;commit()}   // parte de lo que ve (el Inicio de su rol o de la empresa, si aún no arma el suyo)
function ordenPanel(){
  const pn=panelDe(),ws=(pn.widgets||[]).map(w=>w.id),todos=[...Object.keys(PANELES).filter(k=>k!=='kpis'),...ws];
  const izq=(pn.izq||PANEL_IZQ).filter(k=>todos.includes(k)),der=(pn.der||PANEL_DER).filter(k=>todos.includes(k)&&!izq.includes(k));
  todos.forEach(k=>{if(!izq.includes(k)&&!der.includes(k))(PANEL_IZQ.includes(k)?izq:der).push(k)});
  return {izq,der};
}
function armarInicio(P){
  const pn=panelDe(),edit=!!S.ui.personalizar,o=ordenPanel();
  (pn.widgets||[]).forEach(w=>{try{P[w.id]=widgetHTML(w)}catch(e){P[w.id]=`<section class="box"><h2>${esc(w.titulo)}</h2>${empty('No se pudo calcular este panel: '+e)}</section>`}});
  const caja=(k,col)=>{const h=P[k];if(!h)return '';const oc=(pn.ocultos||[]).includes(k);if(oc&&!edit)return '';
    if(!edit)return h;const lista=o[col],i=lista.indexOf(k),w=(pn.widgets||[]).find(x=>x.id===k);
    return `<div class="pedit ${oc?'oculto':''}"><div class="pbar"><b>${esc(w?.titulo||PANELES[k]||k)}</b>${oc?'<span class="hint">Oculto</span>':''}
      <span class="bar-actions"><button type="button" class="iconbtn" data-pmov="${k}:-1" ${i===0?'disabled':''} aria-label="Subir" title="Subir">↑</button><button type="button" class="iconbtn" data-pmov="${k}:1" ${i===lista.length-1?'disabled':''} aria-label="Bajar" title="Bajar">↓</button>
      <button type="button" class="iconbtn" data-pcol="${k}" aria-label="Pasar a la otra columna" title="Pasar a la otra columna">${col==='izq'?'→':'←'}</button>
      ${w?`<button type="button" class="btn ghost sm" data-pwidget="${k}">Editar</button>`:''}<button type="button" class="btn ghost sm" data-pver="${k}">${oc?'Mostrar':'Ocultar'}</button></span></div>${h}</div>`};
  const d=destinoPanel(),todos=puedeInicioTodos();
  const destSel=todos?`<label class="pdest">Cambiar el Inicio de<select data-pdest aria-label="A quién le cambia el Inicio"><option value="" ${!d?'selected':''}>Solo para mí</option>${S.roles.map(r=>`<option value="r:${r.id}" ${d==='r:'+r.id?'selected':''}>Todo el rol ${esc(r.name)}</option>`).join('')}<option value="empresa" ${d==='empresa'?'selected':''}>Toda la empresa</option></select></label>`:'';
  const quien=d?`<b>Personalizando el Inicio de ${esc(nombreDestino(d))}.</b> Lo verán quienes ${d==='empresa'?'no tengan un Inicio de su rol ni hayan armado el suyo':'tienen ese rol y no han armado el suyo'}; cada uno ve sus propios datos.`:'<b>Personalizando tu Inicio.</b> Ordena, oculta o agrega paneles. Solo cambia para ti.';
  const top=edit?`<div class="note pnote"><span>${quien}</span>${destSel}
      <span class="bar-actions"><button class="btn ghost sm" data-pwidget="">+ Agregar panel</button><button class="btn ghost sm" data-pver="kpis">${panelOculto('kpis')?'Mostrar':'Ocultar'} las cifras de arriba</button><button class="btn ghost sm" data-preset>${d?'Quitar este Inicio':armoPanel(person(S.me)?.panel)?'Volver al de mi rol o empresa':'Volver al original'}</button><button class="btn sm" data-ppers>Listo</button></span></div>`:'';
  return `${top}<div class="inicio-cols"><div class="icol">${o.izq.map(k=>caja(k,'izq')).join('')}</div><div class="icol">${o.der.map(k=>caja(k,'der')).join('')}</div></div>`;
}

/* ---------- Paneles propios ---------- */
// Fuentes: tableros que la persona ve y registros de áreas a las que tiene acceso (con la misma visibilidad de siempre)
function fuentesWidget(){
  const ts=tablerosVisibles().map(t=>({id:'t:'+t.id,name:`Tablero · ${t.nombre}`}));
  const es=Object.keys(ENT).filter(e=>{const E=ENT[e];return E.mod&&lvl(E.mod)>=1&&!E.enProyecto&&!E.editor}).map(e=>({id:'e:'+e,name:`${MOD[ENT[e].mod]?.name||''} · ${ENT[e].name}`})).sort((a,b)=>a.name.localeCompare(b.name,'es'));
  return [...ts,...es];
}
function datosWidget(w){
  const [k,id]=[w.fuente.slice(0,1),w.fuente.slice(2)];
  if(k==='t'){const t=tableroDe(id);if(!t||accesoTablero(t)<1)return null;
    return {rows:filasDe(t),campos:camposTablero(t),val:(f,c)=>valorCol(t,f,c.col),txt:(f,c)=>celdaTxt(t,f,c.col),tit:f=>f.nombre||'Sin nombre',abrir:f=>`data-go="tablero#${t.id}"`,
      tono:(g,n)=>g.col?.tipo==='estado'?(g.col.opciones||[]).find(o=>o.v===n)?.c:null}}
  const E=ENT[id];if(!E||!E.mod||lvl(E.mod)<1)return null;
  return {rows:coll(id).filter(r=>{try{return canSee(id,r,E.mod)}catch(e){return false}}),campos:camposFiltroEnt(id),val:valorEnt,
    txt:(r,c)=>{const v=valorEnt(r,c);if(v==null||v==='')return '';if(c.f.type==='ref')return refName(c.f.ref,v);if(c.tipo==='dinero')return fmtMoney(+v);if(isDate(v))return fmt(v);return String(v)},
    tit:r=>E.title(r),abrir:r=>`data-rec="${id}:${r.id}"`,
    // Agrupado por estado: el tono del semáforo del registro, si su etiqueta es la misma del grupo
    tono:(g,n,rs)=>{if(g.k!=='estado'||!E.status||!rs?.length)return null;const s=E.status(rs[0]);return s.label===n?s.tone:null}};
}
function calcWidget(w,d){
  let rows=d.rows;(w.filtros||[]).forEach(x=>{const c=d.campos.find(y=>y.k===x.k);if(c)rows=rows.filter(r=>cumpleFiltro(d.val(r,c),c,x))});
  const c=d.campos.find(y=>y.k===w.col);
  const agg=rs=>{if(w.op==='contar'||!c)return rs.length;const vs=rs.map(r=>d.val(r,c)).map(Number).filter(v=>isFinite(v));
    if(!vs.length)return null;return w.op==='suma'?vs.reduce((a,b)=>a+b,0):w.op==='promedio'?vs.reduce((a,b)=>a+b,0)/vs.length:w.op==='min'?Math.min(...vs):Math.max(...vs)};
  return {rows,c,agg};
}
const OPS_W={contar:'Cantidad',suma:'Suma',promedio:'Promedio',min:'Mínimo',max:'Máximo'};
function widgetHTML(w){
  const d=datosWidget(w);if(!d)return `<section class="box"><h2>${esc(w.titulo)}</h2>${empty('Ya no tienes acceso a la fuente de este panel.')}</section>`;
  const {rows,c,agg}=calcWidget(w,d),dinero=c&&(c.tipo==='dinero')&&w.op!=='contar';
  const f=v=>v==null?'—':w.op==='contar'?String(v):fmtCF(dinero?'dinero':'numero',v).replace(/<[^>]+>/g,'');
  if(w.tipo==='indicador'){const v=agg(rows);
    return `<section class="box pwid"><h2>${esc(w.titulo)}</h2><div class="pwnum ${dinero?'money':''}">${esc(f(v))}</div><p class="hint">${OPS_W[w.op]||''}${c&&w.op!=='contar'?` de ${esc(c.label.toLowerCase())}`:''} · ${cuenta(rows.length,'registro','registros')}${(w.filtros||[]).length?' con filtro':''}</p></section>`}
  if(w.tipo==='barras'){const g=d.campos.find(y=>y.k===w.agrupar);if(!g)return `<section class="box"><h2>${esc(w.titulo)}</h2>${empty('Elige por qué columna agrupar.')}</section>`;
    const grupos={};rows.forEach(r=>{const k=d.txt(r,g)||'Sin valor';(grupos[k]=grupos[k]||[]).push(r)});
    const items=Object.entries(grupos).map(([n,rs])=>({n,v:agg(rs)||0,rs})).sort((a,b)=>b.v-a.v).slice(0,12);
    return `<section class="box pwid"><h2>${esc(w.titulo)}</h2>${items.length?barras(items,f,x=>d.tono(g,x.n,x.rs)):empty('Sin datos con este filtro.')}</section>`}
  if(w.tipo==='meta'){const v=agg(rows)||0,m=+w.meta||1,pc=Math.round(v/m*100),t=pc>=100?'done':pc>=60?'prog':'stuck';
    return `<section class="box pwid"><h2>${esc(w.titulo)}</h2><div class="pwnum ${dinero?'money':''}">${esc(f(v))} <span class="hint">de ${esc(f(+w.meta))}</span></div>
      <span class="bar pmeta" data-sem="no"><span style="width:${Math.min(100,pc)}%;background:var(--s-${t})"></span></span><p class="hint">${pc}% de la meta · ${cuenta(rows.length,'registro','registros')}</p></section>`}
  if(w.tipo==='semaforo'){const v=agg(rows),b=+w.bueno,m=+w.malo,mas=b>=m,t=v==null?'todo':(mas?v>=b:v<=b)?'done':(mas?v<=m:v>=m)?'stuck':'prog';
    return `<section class="box pwid"><h2>${esc(w.titulo)}</h2><div class="pwnum" style="color:var(--t-${t})">${esc(f(v))}</div><p class="hint">${tonePill({label:{done:'Bien',prog:'Atención',stuck:'Mal',todo:'Sin datos'}[t],tone:t})} ${OPS_W[w.op]||''}${c&&w.op!=='contar'?` de ${esc(c.label.toLowerCase())}`:''}</p></section>`}
  if(w.tipo==='linea'){const fc=d.campos.find(y=>y.k===w.fecha);if(!fc)return `<section class="box"><h2>${esc(w.titulo)}</h2>${empty('Elige la columna de fecha.')}</section>`;
    const pts=[...Array(6)].map((_,i)=>addM(TODAY.slice(0,7)+'-01',i-5).slice(0,7)).map(mm=>({mm,v:agg(rows.filter(r=>String(d.val(r,fc)||'').slice(0,7)===mm))||0}));
    return `<section class="box pwid"><h2>${esc(w.titulo)}</h2>${lineaSVG(pts,f)}</section>`}
  if(w.tipo==='proximos'){const fc=d.campos.find(y=>y.k===w.fecha);if(!fc)return `<section class="box"><h2>${esc(w.titulo)}</h2>${empty('Elige la columna de fecha.')}</section>`;
    const hasta=addD(TODAY,+w.dias||30),rs=rows.map(r=>({r,fe:String(d.val(r,fc)||'')})).filter(x=>isDate(x.fe)&&x.fe<=hasta).sort((a,b)=>a.fe.localeCompare(b.fe)),n=+w.n||8;
    return `<section class="box pwid"><h2>${esc(w.titulo)} <span class="hint">${rs.length}</span></h2>${rs.slice(0,n).map(({r,fe})=>{const dd=diff(TODAY,fe),t=dd<0?'stuck':dd<=7?'prog':'done';
      return `<div class="alrow" ${d.abrir(r)} tabindex="0"><span class="dot" style="background:var(--s-${t})"></span><span class="modtag">${fmt(fe)}</span><span class="tt"><span class="tname">${esc(d.tit(r))}</span><span class="hint">${esc(fc.label)} · ${dd<0?`venció hace ${cuenta(-dd,'día','días')}`:dd===0?'vence hoy':`en ${cuenta(dd,'día','días')}`}</span></span></div>`}).join('')||empty('Nada vence en ese plazo.')}${rs.length>n?`<p class="more">Y ${rs.length-n} más.</p>`:''}</section>`}
  const n=+w.n||8,col=c||d.campos.find(y=>y.k!=='nombre');
  return `<section class="box pwid"><h2>${esc(w.titulo)} <span class="hint">${rows.length}</span></h2>${rows.slice(0,n).map(r=>`<div class="alrow solo"${d.abrir(r)} tabindex="0"><span class="tt"><span class="tname">${esc(d.tit(r))}</span>${col?`<span class="hint">${esc(col.label)}: ${esc(d.txt(r,col)||'—')}</span>`:''}</span></div>`).join('')||empty('Nada con este filtro.')}${rows.length>n?`<p class="more">Y ${rows.length-n} más.</p>`:''}</section>`;
}
// Línea de 6 meses: puntos con su valor y el mes abajo (una sola serie, en azul firme)
function lineaSVG(pts,f){
  const W=320,H=120,max=Math.max(1,...pts.map(p=>Math.abs(p.v))),x=i=>20+i*(W-40)/(pts.length-1),y=v=>H-24-(v/max)*(H-44);
  const MES=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  return `<svg class="plinea" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(pts.map(p=>`${p.mm}: ${f(p.v)}`).join(', '))}">
    <line x1="10" x2="${W-10}" y1="${H-24}" y2="${H-24}" class="pl-eje"/><polyline points="${pts.map((p,i)=>`${x(i)},${y(p.v)}`).join(' ')}" class="pl-linea"/>
    ${pts.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.v)}" r="4" class="pl-punto"><title>${esc(MES[+p.mm.slice(5)-1])}: ${esc(f(p.v))}</title></circle><text x="${x(i)}" y="${H-8}" class="pl-mes">${MES[+p.mm.slice(5)-1]}</text>${i===pts.length-1?`<text x="${x(i)}" y="${y(p.v)-10}" class="pl-val">${esc(f(p.v))}</text>`:''}`).join('')}</svg>`;
}
