/* ---------- Deshacer el último cambio (60 segundos; Ctrl+Z fuera de un campo) ----------
   save() guarda una copia del estado antes de cada cambio de datos (DESHACER). Deshacer la repone y la guarda como
   un cambio más: el almacén (o el servidor) recibe lo que hay que revertir y la auditoría lo anota. */
function deshacer(){
  if(!DESHACER||Date.now()-DESHACER.at>60000)return toast('No hay nada reciente que deshacer.');
  const ui=S.ui,me=S.me,o=JSON.parse(DESHACER.s);DESHACER=null;
  S=o;S.ui=ui;S.me=me;normalize();addLog(`${meName()} deshizo el último cambio`);save('fechas');renderAll();ocultarDeshacer();toast('Se deshizo el último cambio');
}
let tDesh;
function mostrarDeshacer(){
  if(window.HILVANTA_PRUEBA)return;   // las pruebas comparan el texto de cada pantalla
  let b=$('deshacer');if(!b){b=document.createElement('button');b.id='deshacer';b.type='button';b.className='deshacer';b.textContent='Deshacer';b.addEventListener('click',deshacer);document.body.appendChild(b)}
  b.hidden=false;clearTimeout(tDesh);tDesh=setTimeout(ocultarDeshacer,8000);
}
function ocultarDeshacer(){const b=$('deshacer');if(b)b.hidden=true}
document.addEventListener('keydown',e=>{
  if(!(e.ctrlKey||e.metaKey)||e.key.toLowerCase()!=='z'||e.shiftKey)return;
  if(e.target.closest('input,textarea,select,[contenteditable]')||!$('modalScrim').hidden)return;
  e.preventDefault();deshacer();
});

/* ---------- Dictado por voz en los campos de texto largo (reconocimiento del navegador, en español de Chile) ---------- */
const VOZ=window.SpeechRecognition||window.webkitSpeechRecognition;
let vozActiva=null;
function agregarMicros(raiz){
  if(!VOZ||window.HILVANTA_PRUEBA)return;
  raiz.querySelectorAll('textarea:not([data-dictado])').forEach(t=>{
    t.dataset.dictado='1';const b=document.createElement('button');b.type='button';b.className='iconbtn micro';b.title='Dictar con la voz';b.setAttribute('aria-label','Dictar con la voz');
    b.innerHTML='<svg class="i" viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5.5 11a6.5 6.5 0 0 0 13 0M12 17.5V21"/></svg>';
    b.addEventListener('click',()=>dictar(t,b));t.insertAdjacentElement('afterend',b)});
}
function dictar(t,b){
  if(vozActiva){vozActiva.stop();return}
  const r=new VOZ();r.lang='es-CL';r.interimResults=false;r.continuous=true;vozActiva=r;b.classList.add('on');
  r.onresult=ev=>{const txt=[...ev.results].slice(ev.resultIndex).map(x=>x[0].transcript).join(' ').trim();if(!txt)return;
    t.value=(t.value&&!/\s$/.test(t.value)?t.value+' ':t.value)+txt.charAt(0).toUpperCase()+txt.slice(1);t.dispatchEvent(new Event('input',{bubbles:true}))};
  r.onerror=ev=>{if(ev.error==='not-allowed')toast('El navegador no dio permiso para usar el micrófono.')};
  r.onend=()=>{vozActiva=null;b.classList.remove('on')};
  try{r.start();toast('Habla ahora. Toca el micrófono otra vez para terminar.')}catch(e){vozActiva=null;b.classList.remove('on')}
}
new MutationObserver(()=>{if(!$('modalScrim').hidden)agregarMicros($('modal'))}).observe(document.getElementById('modal'),{childList:true});

/* ---------- Calendario para Google, Outlook o el teléfono (.ics con lo que se ve en Calendario) ---------- */
function exportarICS(){
  const ev=calEvents(),hoy=new Date().toISOString().replace(/[-:]/g,'').slice(0,15)+'Z',e=s=>String(s).replace(/([,;\\])/g,'\\$1').replace(/\n/g,' ');
  const lin=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Hilvanta//Calendario//ES','CALSCALE:GREGORIAN',`X-WR-CALNAME:${e(S.company||'Hilvanta')}`];
  ev.filter(x=>isDate(x.d)).forEach((x,i)=>{const d=x.d.replace(/-/g,''),fin=addD(x.d,1).replace(/-/g,'');
    lin.push('BEGIN:VEVENT',`UID:${d}-${i}-${(x.rec||x.task||'h').replace(/[^a-z0-9]/gi,'')}@hilvanta`,`DTSTAMP:${hoy}`,`DTSTART;VALUE=DATE:${d}`,`DTEND;VALUE=DATE:${fin}`,`SUMMARY:${e(x.label||'')}`,'END:VEVENT')});
  lin.push('END:VCALENDAR');
  bajarArchivo('hilvanta-calendario.ics',lin.join('\r\n'),'text/calendar');
  toast(`${cuenta(ev.length,'fecha','fechas')} en el archivo. Ábrelo o impórtalo en Google Calendar u Outlook.`);
}

