/* ---------- Dependencias entre tareas y ruta crítica (t.depende = [ids]) ---------- */
function dependenciasBloque(t,ro){
  const otras=S.tasks.filter(x=>x.projectId===t.projectId&&x.id!==t.id&&x.name&&canSeeTask(x)),dep=t.depende||[];
  const siguen=S.tasks.filter(x=>(x.depende||[]).includes(t.id));
  const antes=dep.map(task).filter(Boolean).filter(x=>x.due&&t.start&&t.start<=x.due&&x.status!=='done');
  const tarde=siguen.filter(x=>t.due&&x.start&&x.start<=t.due&&x.status!=='done');
  return `<section class="dsec"><h3>Depende de <span class="hint">${dep.length}</span></h3>
    ${otras.length?`<details class="mas" ${dep.length?'open':''}><summary>${dep.length?'Cambiar':'Elegir'} de qué tareas depende</summary><div class="deplista">${otras.map(x=>`<label class="subl"><input type="checkbox" data-dep="${x.id}" ${dep.includes(x.id)?'checked':''} ${ro?'disabled':''}><span class="depn"><span>${esc(x.name)}</span>${x.due?`<span class="hint">Vence ${fmt(x.due)}</span>`:''}</span></label>`).join('')}</div></details>`:'<p class="hint">No hay otras tareas en este proyecto.</p>'}
    ${antes.length?`<p class="warn">Empieza antes de que termine ${antes.map(x=>`«${esc(x.name)}» (${fmt(x.due)})`).join(', ')}.</p>${ro?'':`<button type="button" class="btn ghost sm" data-depcorrer="${t.id}">Empezar después (${fmt(addD(antes.map(x=>x.due).sort().at(-1),1))})</button>`}`:''}
    ${siguen.length?`<p class="hint">${cuenta(siguen.length,'tarea depende','tareas dependen')} de esta: ${siguen.map(x=>esc(x.name)).join(', ')}.</p>`:''}
    ${tarde.length&&!ro?`<p class="warn">${cuenta(tarde.length,'tarea siguiente empieza','tareas siguientes empiezan')} antes de que esta termine.</p><button type="button" class="btn ghost sm" data-depsig="${t.id}">Correr las siguientes</button>`:''}</section>`;
}
// Corre una tarea (inicio y plazo, misma duración) para que empiece el día después de que termine lo anterior; sigue en cadena
function correrDespues(t,desde,vistos=new Set()){
  if(vistos.has(t.id))return 0;vistos.add(t.id);if(!t.start||t.start>=desde||!canEditTask(t))return 0;
  const dur=t.due?diff(t.start,t.due):0;t.start=desde;if(t.due)t.due=addD(desde,dur);let n=1;
  S.tasks.filter(x=>(x.depende||[]).includes(t.id)).forEach(x=>{n+=correrDespues(x,addD(t.due||t.start,1),vistos)});return n;
}
$('drawer').addEventListener('change',e=>{const el=e.target;if(!el.dataset.dep)return;const t=task(openId);if(!t||!canEditTask(t))return;
  const d=new Set(t.depende||[]);if(el.checked)d.add(el.dataset.dep);else d.delete(el.dataset.dep);
  if(el.checked&&dependeDe(task(el.dataset.dep),t.id)){el.checked=false;return toast('Eso armaría un círculo: esa tarea ya depende de esta.')}
  t.depende=[...d];if(!t.depende.length)delete t.depende;save();renderDrawer();renderMain()});
const dependeDe=(t,id,v=new Set())=>!!t&&!v.has(t.id)&&(v.add(t.id),(t.depende||[]).some(x=>x===id||dependeDe(task(x),id,v)));
document.addEventListener('click',e=>{const c=s=>e.target.closest&&e.target.closest(s);let x;
  if(x=c('[data-depcorrer]')){const t=task(x.dataset.depcorrer);if(!t)return;const ult=(t.depende||[]).map(task).filter(y=>y&&y.due).map(y=>y.due).sort().at(-1);if(!ult)return;
    const n=correrDespues(t,addD(ult,1));addLog(`${meName()} corrió «${t.name}» después de sus dependencias`);commit();renderDrawer();toast(`${cuenta(n,'tarea corrida','tareas corridas')}`)}
  if(x=c('[data-depsig]')){const t=task(x.dataset.depsig);if(!t)return;let n=0;const v=new Set([t.id]);
    S.tasks.filter(y=>(y.depende||[]).includes(t.id)).forEach(y=>{n+=correrDespues(y,addD(t.due||t.start,1),v)});addLog(`${meName()} corrió las tareas que siguen a «${t.name}»`);commit();renderDrawer();toast(`${cuenta(n,'tarea corrida','tareas corridas')}`)}
});
/* Ruta crítica: la cadena de dependencias que termina más tarde (de ella depende el término del proyecto). */
function rutaCritica(ts){
  const ids=new Set(ts.map(t=>t.id)),con=ts.filter(t=>(t.depende||[]).some(d=>ids.has(d)));if(!con.length)return {set:new Set(),cadena:[],choques:[]};
  const fin=t=>t.due||t.start||'';const memo={};
  const largo=t=>{if(memo[t.id])return memo[t.id];memo[t.id]={c:[t]};const ps=(t.depende||[]).filter(d=>ids.has(d)).map(task).filter(Boolean);
    let mejor=null;ps.forEach(p=>{const l=largo(p);if(!mejor||fin(l.c.at(-1))>fin(mejor.c.at(-1))||(fin(l.c.at(-1))===fin(mejor.c.at(-1))&&l.c.length>mejor.c.length))mejor=l});
    return memo[t.id]={c:mejor?[...mejor.c,t]:[t]}};
  const ultima=ts.filter(t=>fin(t)).sort((a,b)=>fin(b).localeCompare(fin(a))||(b.depende||[]).length-(a.depende||[]).length)[0];
  const cadena=ultima&&(ultima.depende||[]).length?largo(ultima).c:[];
  const choques=con.flatMap(t=>(t.depende||[]).map(task).filter(p=>p&&ids.has(p.id)&&p.due&&t.start&&t.start<=p.due&&t.status!=='done').map(p=>`«${t.name}» empieza antes de que termine «${p.name}»`));
  return {set:new Set(cadena.map(t=>t.id)),cadena,choques};
}
