/* ---------- Toda barra de avance con el semáforo de su porcentaje (10-11-2026, pedido de Miguel) ----------
   Pinta cada .bar > span según su ancho (tonoPct). Las barras que no son de avance (carga del equipo, gasto contra
   presupuesto, metas de paneles) llevan data-sem="no" y conservan su color. */
function pintarBarras(){document.querySelectorAll('.bar:not([data-sem="no"])>span').forEach(b=>{const w=parseFloat(b.style.width);
  if(isNaN(w))return;const c=`var(--s-${tonoPct(w)})`;if(b.style.background!==c)b.style.background=c})}
let barrasPend=false;
new MutationObserver(()=>{if(barrasPend)return;barrasPend=true;requestAnimationFrame(()=>{barrasPend=false;pintarBarras()})}).observe(document.documentElement,{childList:true,subtree:true});
/* ===== Trazabilidad entre documentos (pedido de Miguel, 01-11-2026) =====
   Cuadro comparativo → OC → embarque, guías de despacho y movimientos de bodega → factura → notas de crédito, y estado de
   pago → factura. Cada ficha de esos documentos muestra la cadena completa de documentos relacionados (no solo los
   vecinos), para que todas las áreas vean de dónde viene y a dónde fue cada cosa.
   - Los enlaces son los campos que ya existen: cc.oc, ship.oc, doc.oc, doc.guia, nc.factura, guia.oc, move.guia y
     edp.factura (en la base, las mismas llaves foráneas). No se guarda nada nuevo.
   - Cada documento se abre solo si quien mira lo ve en su área (regVisible, igual que la base); si no, sale «Sin acceso». */
const TRAZA_ORDEN=['cotizaciones','ocs','ships','guias','moves','docs','ncs','edps'];
const TRAZA_TIPO={cotizaciones:'Cuadro comparativo',ocs:'Orden de compra',ships:'Embarque',guias:'Guía de despacho',moves:'Movimiento de bodega',docs:'Factura',ncs:'Nota de crédito',edps:'Estado de pago'};
// Vecinos directos de un documento: [[entidad, id], …]
function trazaVecinos(ent,r){
  const de=(e,f)=>(coll(e)||[]).filter(f).map(x=>[e,x.id]),uno=(e,id)=>id?[[e,id]]:[];
  switch(ent){
    case 'cotizaciones':return uno('ocs',r.oc);
    case 'ocs':return [...de('cotizaciones',c=>c.oc===r.id),...de('ships',x=>x.oc===r.id),...de('docs',d=>d.oc===r.id),...de('guias',g=>g.oc===r.id)];
    case 'ships':return uno('ocs',r.oc);
    case 'guias':return [...uno('ocs',r.oc),...de('moves',m=>m.guia===r.id),...de('docs',d=>d.guia===r.id)];
    case 'moves':return uno('guias',r.guia);
    case 'docs':return [...uno('ocs',r.oc),...uno('guias',r.guia),...de('ncs',n=>n.factura===r.id),...de('edps',x=>x.factura===r.id)];
    case 'ncs':return uno('docs',r.factura);
    case 'edps':return uno('docs',r.factura);
  }
  return [];
}
// Todos los documentos conectados, recorriendo la cadena en ambos sentidos (hasta 40)
function trazaDe(ent,r){
  const visto=new Set([ent+':'+r.id]),cola=[[ent,r]],res=[];
  while(cola.length&&res.length<40){
    const [e,x]=cola.shift();
    trazaVecinos(e,x).forEach(([e2,id])=>{const k=e2+':'+id;if(visto.has(k))return;visto.add(k);
      const y=(coll(e2)||[]).find(z=>z.id===id);if(!y)return;res.push([e2,y]);cola.push([e2,y])});
  }
  const fecha=x=>x.fecha||x.emision||x.etd||'';
  return res.sort((a,b)=>TRAZA_ORDEN.indexOf(a[0])-TRAZA_ORDEN.indexOf(b[0])||fecha(a[1]).localeCompare(fecha(b[1])));
}
function trazaBloque(ent,r){
  if(!r||!r.id||!TRAZA_ORDEN.includes(ent))return '';
  const l=trazaDe(ent,r);if(!l.length)return '';
  const item=([e,x])=>{const area=areaDeRegistro(e,x),st=ENT[e].status?ENT[e].status(x):null;
    const tit=area?`<button type="button" class="lnkbtn" data-rec="${e}:${x.id}:${area}">${esc(audTitulo(e,x))}</button>`:`<span>${esc(audTitulo(e,x))}</span> <span class="hint">(sin acceso)</span>`;
    return `<li><span class="traza-tipo">${TRAZA_TIPO[e]}</span><span class="traza-doc">${tit}${x.fecha||x.emision?` <span class="hint">· ${fmt(x.fecha||x.emision)}</span>`:''}</span>${st&&st.label?tonePill(st):''}</li>`};
  return `<div class="wide traza"><b>Trazabilidad: documentos relacionados</b><ol class="traza-lista">${l.map(item).join('')}</ol></div>`;
}
// Se suma al bloque extra de la ficha de cada documento de la cadena
TRAZA_ORDEN.forEach(e=>{const ent=ENT[e];if(!ent)return;const x0=ent.extra;ent.extra=(r,...m)=>(x0?x0(r,...m)||'':'')+trazaBloque(e,r)});
