  if(k==='sample'){S=sample();normalize();commit(true);if(revisarFechas())renderAll();toast('Datos de ejemplo restaurados')}
  else if(k==='blank'){S.projects=[];S.tasks=[];S.log=[];COLLS.forEach(c=>S.d[c]=[]);S.isSample=false;S.ui.route='panel';S.ui.projectId='';addLog('Se empezó en blanco');commit();toast('Listo. Empieza creando tus clientes, proveedores y proyectos.')}
